(window.GIM_TS=window.GIM_TS||{})["Ketubot.7"]={"from":168,"a":[["\u0003תיזיל ותיחלה\u0004 \u0005[תלך ותמחל]\u0006 את \u0003כתובתה\u0004 של \u0003אמה לגבי אבוה\u0004 \u0005[לאביה]\u0006 שהרי הכתובה היא שטר חוב של האם על האב, והבת היורשת יכולה למחול אותו ולא יהא חייב עוד לפרוע אותה, \u0003ו\u0004אחר כך \u0003תירתה מיניה\u0004 \u0005[תירש אותו,\u0006 את סכום הכתובה, \u0005ממנו].\u0006 \u0003שמעה\u0004 זאת הבת, \u0003אזלה אחילתה\u0004 \u0005[הלכה, ומחלה]\u0006 כפי שאמר רב נחמן.","\u0003אמר רב נחמן\u0004 בצער: \u0003עשינו עצמינו כעורכי הדיינין,\u0004 לתת לבעל דין עצה מה לעשות, דבר שאינו ראוי לחכם. ושואלים: \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 כאשר אמר את הדבר בודאי התכוון שתשמע הקרובה \u0003מאי סבר\u0004 \u0005[מה חשב],\u0006 \u0003ולבסוף מאי סבר\u0004 \u0005[מה חשב],\u0006 שהתחרט? ומסבירים: \u0003מעיקרא סבר\u0004 \u0005[מתחילה חשב]:\u0006 הרי נאמר \u0003\"ומבשרך לא תתעלם\"\u0004 (ישעיה נח, ז), ומשום כך ראוי לאדם לסייע ולתת עצה טובה לקרובתו, \u0003ולבסוף סבר\u0004 \u0005[חשב]:\u0006 \u0003אדם חשוב שאני\u0004 \u0005[שונה],\u0006 שצריך לדקדק הרבה במעשיו, שלא יבואו לדבר בגנותו שעשה דין לטובת קרוביו, וכן שלא יבואו ללמוד ממעשיו ויטעו לנהוג כן אף שלא בקרובים.","כיון שהזכרנו את ההלכה שאמר שמואל, דנים עכשיו \u0003גופא\u0004 \u0005[\u0006ב\u0005גופה]\u0006 של הלכה זו. \u0003אמר שמואל: המוכר שטר חוב לחבירו, וחזר ומחלו\u0004 ללווה — \u0003מחול, ואפילו יורש מוחל\u0004 את החוב בשטר שהיה למורישו על אחר ומכרו. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ואי\u0004 \u0005[ואם]\u0006 \u0003פקח הוא\u0004 הקונה את השטר, וחושש מדבר כזה, \u0003מקרקש ליה זוזי\u0004 \u0005[מצלצל לו\u0006 ב\u0005דינרים],\u0006 כלומר, משלם או מבטיח כסף ללווה, \u0003וכתב ליה שטרא בשמיה\u0004 \u0005[וכותב לו\u0006 הלווה \u0005שטר\u0006 חוב חדש \u0005בשמו]\u0006 של הקונה מחזיק השטר, ושוב לא תועיל מחילת השטר הראשון, והקונה לא יפסיד.","\u0003אמר אמימר: מאן דדאין דינא\u0004 \u0005[מי שדן דינים]\u0006 של \u0003גרמי,\u0004 שסבור שאדם שמעשיו גרמו הפסד ונזק לאחרים, גם אם לא עשה המזיק מעשה בידיים, חייב לשלם — זה שמחל את החוב וגרם בכך הפסד לקונה, נחשב אף הוא כמזיק, ולכן \u0003מגבי ביה\u0004 \u0005[מגבה בו]\u0006 \u0003דמי שטרא מעליא\u0004 \u0005[שטר מעולה],\u0006 שכיון שהמלווה הראשון גרם לקונה השטר שלא יוכל לזכות בו, צריך הוא לשלם לו את כל דמי השטר. \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003לא דאין דינא\u0004 \u0005[דן דינים]\u0006 של \u0003גרמי, מגבי ביה דמי ניירא בעלמא\u0004 \u0005[מגבה בו דמי נייר בלבד],\u0006 שהפסידו את הנייר שעליו כתוב השטר.","מסופר: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 כגון זה שבא לפני בית הדין \u0003וכפייה\u0004 \u0005[וכפה אותו]\u0006 \u0003רפרם לרב אשי\u0004 בדברים כדי שיפסוק הלכה ברורה בענין זה, \u0003ואגבי ביה כי כשורא לצלמי\u0004 \u0005[והגבה בו כמו קורה\u0006 שעושים \u0005לפסלים]\u0006 שמדקדקים שתהא שלימה לגמרי, כלומר, עמד על כך לגבות את כל הנזק כולו בלי להשאיר דבר (ראה \"עיונים\").","\u0003אמר אמימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב חמא: האי מאן דאיכא עליה\u0004 \u0005[מי שיש עליו]\u0006 התחייבות של \u0003כתובת אשה ובעל חוב\u0004 הנושה בו כסף, \u0003ואית ליה ארעא ואית ליה זוזי\u0004 \u0005[ויש לו קרקע ויש לו כספים]\u0006 — \u0003לבעל חוב מסלקינן ליה בזוזי\u0004 \u0005[מסלקים לו\u0006 את החוב \u0005בכספים],\u0006 ואילו \u0003לאשה מסלקינן\u0004 \u0005[מסלקים]\u0006 \u0003לה\u0004 את חוב כתובתה \u0003בארעא\u0004 \u0005[בקרקע],\u0006 \u0003האי כי דיניה והאי כי דיניה\u0004 \u0005[זה כדינו וזה כדינו],\u0006 כי המלווה הלווה לו כסף — ולכן ראוי שיקבל כסף מזומן, והאשה שלא נתנה דבר אלא סמכה על שעבוד הקרקע — מקבלת קרקע.","\u0003ואי לא איכא\u0004 \u0005[ואם אין]\u0006 \u0003אלא חד ארעא\u0004 \u0005[קרקע אחת]\u0006 \u0003ולא חזיא\u0004 \u0005[ואינה ראויה]\u0006 לתשלום \u0003אלא לחד\u0004 \u0005[לאחד] —\u0006 \u0003לבעל חוב יהבינן ליה\u0004 \u0005[נותנים לו],\u0006 \u0003לאשה לא יהבינן\u0004 \u0005[נותנים]\u0006 \u0003לה. מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003יותר ממה שהאיש רוצה לישא, אשה רוצה להנשא,\u0004 ואינה נישאת דווקא משום הכתובה, ומוטב להקדים את בעל החוב, כדי שלא יפסיד וימנעו אנשים מלהלוות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרב חמא: ודאי דאמריתו משמיה\u0004 \u0005[\u0006האם \u0005נכון\u0006 הוא שמה \u0005שאתם אומרים משמו]\u0006 של \u0003רבא\u0004 כי \u0003האי מאן דמסקי ביה זוזי ואית ליה ארעא\u0004 \u0005[מי שנושים בו כסף ויש לו קרקע]\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003בעל חוב וקא תבע מיניה\u0004 \u0005[ותובע ממנו]\u0006 את תשלום הכסף, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 הלווה: \u0003\"זיל, שקול מארעא\u0004 \u0005[לך, קח מן הקרקע]\u0006 כשיעור מעותיך \u0003\", אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003זיל זבין את ואייתי הב ליה\u0004 \u0005[לך מכור אתה\u0006 את הקרקע \u0005והבא לו\u0006 כסף\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חמא: \u0003לא\u0004 אמרתי כך משמו של רבא.","אמר לו רב פפא: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לי גופא דעובדא היכי הוה\u0004 \u0005[גופו של מעשה איך היה],\u0006 שודאי היה מעשה שגרם לייחס לרבא שיטה זו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אותו לווה \u0003תולה מעותיו בגוי הוה\u0004 \u0005[היה],\u0006 כלומר, שהיה לו כסף, אלא טען שהכסף הזה שייך לגוי, ואי אפשר היה לתבוע אותו מן הגוי, וכיון ש\u0003הוא עשה שלא כהוגן\u0004 שאינו נאמן על כך — \u0003לפיכך עשו בו שלא כהוגן\u0004 וחייבו אותו לטרוח ולמכור בעצמו את הקרקע.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב פפא: לדידך דאמרת\u0004 \u0005[לשיטתך שאתה אומר]\u0006 כי \u0003פריעת בעל חוב מצוה\u0004 היא, אם \u0003אמר\u0004 הלווה: \u0003\"לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דאיעביד\u0004 \u0005[לעשות]\u0006 \u0003מצוה\" מאי\u0004 \u0005[מה]\u0006 יהיה הדין? שאם רואים בכך רק מצוה, מה הדין אם אדם אינו רוצה לקיים את המצוה? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003במה דברים אמורים\u0004 שיש דין מלקות ארבעים על עבירות — \u0003במצות לא תעשה, אבל במצות עשה, כגון שאומרין לו\u0004 לאדם \u0003\"עשה סוכה\" ואינו עושה,\u0004 או שאומרים לו \u0003\"\u0004עשה \u0003לולב\" ואינו עושה\u0004 —"],["\u0003מכין אותו\u0004 ואין לכך שיעור מוגדר, ואפילו \u0003עד שתצא נפשו\u0004 על מנת לכפותו שיקיים את המצוה. שפריעת חוב — אף היא מצות עשה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רמי בר חמא מרב חסדא:\u0004 אמר לאשה \u0003\"הרי זה גיטיך, ולא תתגרשי בו אלא לאחר שלשים יום\"\u0004 ולקחה את הגט \u0003והלכה והניחתו בצידי רשות הרבים,\u0004 במקום הפתוח לרשות הרבים ואולם אין דרך הרבים להלך שם, והיה הגט מונח שם לאחר שלושים יום, \u0003מהו,\u0004 האם מגורשת היא?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינה מגורשת,\u0004 ודבר זה נלמד \u0003מ\u0004כלל דברי \u0003רב ושמואל.\u0004 ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 לענין משנתנו, שאנשים יכולים לזכות ולתפוס חפצים (שהיו קודם שייכים לאחרים) \u0003והוא\u0004 דווקא כ\u0003שצבורין ומונחין ברשות הרבים\u0004 שבה אין קניינו של אדם חל, ולכן מועילה התפיסה בהם, מפני שאין לבעליהם קנין בהם, \u0003וצידי רשות הרבים כרשות הרבים דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 ולכן גם בענייננו, כיון שבזמן חלות הגט לא היה הגט במקום שיש לה קנין בו, אלא ברשות הרבים — אינו חל.","אמר לו: \u0003אדרבה,\u0004 להיפך, אשה זו צריכה להיות \u0003מגורשת, מ\u0004חמת דברי שאמר \u0003רב נחמן.\u0004 ש\u0003אמר רב נחמן אמר רבה בר אבוה: האומר לחבירו \"משוך פרה זו\u0004 עכשיו, \u0003ולא תהיה קנויה לך\u0004 אלא \u0003עד לאחר שלשים יום\" — קנה, ואפילו עומדת\u0004 הפרה לאחר שלושים יום \u0003באגם\u0004 שהוא מקום הפקר. שכיון שהמשיכה היתה עכשיו, הרי היא חלה גם לאחר זמן. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003היינו\u0004 \u0005[זהו\u0006 די\u0005]\u0006 \u0003אגם, והיינו\u0004 \u0005[וזהו]\u0006 דין \u0003צידי רשות הרבים\u0004 ששם היה מונח הגט? ודחה רב חסדא: \u0003לא, אגם לחוד וצידי רשות הרבים לחוד.\u0004 שצידי רשות הרבים נחשבים כרשות הרבים ממש.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהויכוח בין רב חסדא ורמי בר חמא היה באופן אחר, שרב חסדא \u0003אמר ליה\u0004 \u0005[לו]\u0006 לרמי בר חמא: \u0003מגורשת, מ\u0004חמת דברי \u0003רב נחמן\u0004 לגבי קנין פרה, \u0003וצידי רשות הרבים כאגם דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 ורמי בר חמא הוא שענה: \u0003אדרבה\u0004 (להיפך), \u0003אינה מגורשת\u0004 וזאת \u0003מ\u0004חמת דברי \u0003רב ושמואל\u0004 בענין תפיסה מרשות הרבים, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003\"רשות הרבים\" והיינו\u0004 \u0005[וזהו]\u0006 \u0003\"צידי רשות הרבים\".\u0004 ודחה רב חסדא: \u0003לא, רשות הרבים לחוד, וצידי רשות הרבים לחוד,\u0004 ואין דינם שווה.","\u0003המושיב את אשתו\u0004 להיות \u0003חנוונית\u0004 בחנותו, \u0003או שמינה\u0004 אותה להיות \u0003אפוטרופיא\u0004 (אפוטרופסית) שתטפל בנכסיו ובפועליו — \u0003הרי זה משביעה\u0004 שלא נטלה לעצמה מנכסיו \u0003כל זמן שירצה. ר' אליעזר אומר:\u0004 משביע אותה \u0003אפילו על פילכה ועל עיסתה,\u0004 כלומר, שלא גנבה ממה שהיא טווה בפלך, ומן העיסה שהיא עושה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003ר' אליעזר\u0004 שאמר שמשביע אותה על פילכה ועל עיסתה, \u0003על ידי גלגול\u0004 שבועה \u0003קאמר\u0004 \u0005[אמר],\u0006 כלומר, שאם משביע אותה משום שהיא חנוונית — יכול לגלגל עליה גם שתשבע שלא גנבה דברים אחרים, \u0003או לכתחלה קאמר\u0004 \u0005[אמר],\u0006 שבכל מקרה יכול להשביע את אשתו על כך?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר מברייתא, ששנינו בה: \u0003אמרו לו\u0004 חכמים \u0003לר' אליעזר\u0004 כדחייה לדבריו: \u0003אין אדם דר עם נחש בכפיפה\u0004 (בסל) אחד, וכמו כן אשה יכולה לדור עם בעל שחושד בה בגניבת כל דבר. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר פה בהשבעה \u0003לכתחלה — שפיר\u0004 \u0005[יפה]\u0006 אמרו חכמים. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמשביעה רק \u0003על ידי גלגול, מאי נפקא\u0004 \u0005[מה יוצא]\u0006 \u0003לה מינה\u0004 \u0005[מזה],\u0006 ומה היא מפסידה? שהרי סוף סוף היא צריכה להשבע, ומה לה אם תשבע גם על דברים אלה.","ודוחים: מכאן אין ראיה, כיון שאפילו כשמשביעה על ידי גלגול, אפשר לומר \u0003דאמרה ליה\u0004 \u0005[שאומרת\u0006 היא \u0005לו]:\u0006 \u0003כיון דקדייקת בתראי כולי האי\u0004 \u0005[שאתה מדקדק אחרי כל כך] —\u0006 \u0003לא מצינא דאדור בהדך\u0004 \u0005[אינני יכולה לגור איתך],\u0006 ואין איפוא להוכיח מכאן.","ומציעים עוד לומר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003הרי שלא פטר את אשתו מן הנדר ומן השבועה\u0004 בתנאי הכתובה, \u0003והושיבה חנוונית\u0004 בחנותו \u0003או שמינה\u0004 (קבע אותה) להיות \u0003אפוטרופיא — הרי זה משביעה כל זמן שירצה. לא הושיבה חנוונית ולא מינה אפוטרופיא — אינו יכול להשביעה.\u0004","\u0003ר' אליעזר אומר: אף על פי שלא הושיבה חנוונית ולא מינה אפוטרופיא — הרי זה משביעה כל זמן שירצה, שאין לך אשה שלא נעשית אפוטרופיא שעה אחת בחיי בעלה\u0004 לפחות \u0003על פילכה ועל עיסתה. אמרו לו\u0004 חכמים: \u0003אין אדם דר עם נחש בכפיפה.\u0004 ולענייננו \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שר' אליעזר אומר שמשביעה על כל דבר אפילו \u0003לכתחלה.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003כתב לה\u0004 בכתובה: \u0003\"נדר ושבועה אין לי עליך\" — אין\u0004 הוא \u0003יכול להשביעה, אבל\u0004 אם גירשה ומתה ובאים יורשיה לתבוע ממנו כתובתה — \u0003משביע הוא את יורשיה,\u0004 או \u0003את הבאים ברשותה\u0004 (הבאים מכוחה כקונים ממנה), שאינם יודעים לא ממנה ולא בדרך אחרת שכבר נפרעה כתובתה.","כתב לה \u0003\"נדר ושבועה אין לי עליך ועל יורשיך ועל הבאים ברשותך\" — אינו יכול להשביעה לא היא\u0004 (אותה), \u0003ולא\u0004 את \u0003יורשיה, ולא את הבאים ברשותה. אבל יורשיו משביעין אותה, ואת יורשיה, ואת הבאים ברשותה.\u0004","ואם כתב \u0003\"נדר ושבועה אין לי ולא ליורשי ולא לבאים ברשותי עליך ועל יורשיך ועל הבאים ברשותיך\" — אינו יכול להשביעה, לא הוא ולא יורשיו ולא הבאים ברשותו, לא אותה ולא\u0004 את \u0003יורשיה ולא\u0004 את \u0003הבאים ברשותה.\u0004","\u0003הלכה\u0004 האשה שפטרה בעלה מן השבועה \u0003מקבר בעלה,\u0004 כלומר, מיד אחר מות בעלה, \u0003לבית אביה\u0004 ולא טיפלה בנכסי בעלה, \u0003או שחזרה לבית חמיה ולא נעשית אפוטרופיא\u0004 על נכסיו כלל במשך הזמן — \u0003אין היורשין משביעין אותה\u0004 על מה שעשתה בחייו, כיון שפטר אותה גם מן היורשים. \u0003ואם נעשית\u0004 בין הזמן שמת לבין הזמן שתבעה כתובתה \u0003אפוטרופיא\u0004 לנכסיו — \u0003היורשין משביעין אותה על העתיד לבא,\u0004 כלומר, על מה שעשתה בנכסים לאחר מות בעלה, \u0003ואין משביעין אותה על מה שעבר,\u0004 בחיי בעלה.","שואלים: \u0003שבועה מאי עבידתה\u0004 \u0005[מה מעשיה],\u0006 כלומר, מדוע בכלל יכול הבעל להשביע את אשתו, עד שצריך לכתוב תנאי מפורש בכתובתה לפוטרה מן השבועה? \u0003אמר רב יהודה אמר רב:\u0004"],["\u0003על אפוטרופיא\u0004 (אפוטרופסית) \u0003שנעשית בחיי בעלה,\u0004 שדבר מצוי הוא שישאיר את אשתו לפקח על נכסיו, ופוטר אותה מן החובה המוטלת על כל אפוטרופוס להשבע שלא מעל באימון בעל הנכסים ולא נטל מאומה מן הנכסים עליהם היה מופקד. \u0003רב נחמן אמר\u0004 בשם \u0003רבה בר אבוה: שבועה זו על הפוגמת כתובתה,\u0004 שאשה המודה שקיבלה חלק מכתובתה, חייבת להשבע שלא קיבלה יותר ממה שהודתה, ובמשנה מדובר במי שפוטר את אשתו משבועה זו.","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב מרדכי אמרה לשמעתא\u0004 \u0005[להלכה\u0006 זו\u0005]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אשי,\u0004 ושאל: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי שבועה זו \u0003על הפוגמת כתובתה\u0004 — מובן הדבר, ומדוע — \u0003דמסקא אדעתה\u0004 \u0005[ש\u0006היא \u0005מעלה על דעתה]\u0006 שיבואו הדברים לידי כך, ואומרת: \u0003דלמא מצטרכי\u0004 \u0005[שמא יצטרכו]\u0006 \u0003לי זוזי\u0004 \u0005[כספים]\u0006 \u0003ושקילנא מכתובתאי\u0004 \u0005[ואקח מכתובתי]\u0006 על החשבון, \u0003ו\u0004לכן \u0003אמרה ליה\u0004 \u0005[אומרת לו]\u0006 לפני הנישואין: \u0003כתוב לי דלא משבעת לי\u0004 \u0005[שאין אתה משביע אותי]\u0006 כשאבוא להיפרע שאר סכום הכתובה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי שבועה זו \u0003על אפוטרופיא שנעשית בחיי בעלה, איהי מי הות ידעה דמותיב לה אפוטרופיא דאמרה ליה\u0004 \u0005[היא, האם היא היתה יודעת\u0006 מראש \u0005שיושיב אותה\u0006 בעלה \u0005אפוטרופסית, שאומרת לו\u0006 מראש\u0005]:\u0006 \u0003\"כתוב לי דלא משבעת לי\u0004 \u0005[שאין אתה משביע אותי]\u0006","\u0003\"? אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אתון, אהא מתניתו לה\u0004 \u0005[אתם, על\u0006 קטע \u0005זה\u0006 במשנה \u0005שונים אתם אותה]\u0006 את ההלכה לרב יהודה בשם רב ולכן קשה לכם, \u0003אנן אהא מתנינן לה\u0004 \u0005[אנו על\u0006 קטע \u0005זה\u0006 במשנה \u0005שונים אנו אותה]:\u0006 \u0003הלכה מקבר בעלה\u0004 ישר \u0003לבית אביה, או שחזרה לבית חמיה ולא נעשית אפוטרופיא\u0004 על נכסי בעלה המת — \u0003אין היורשין משביעין אותה. ואם נעשית אפוטרופיא\u0004 — \u0003יורשין משביעין אותה על העתיד לבא, ו\u0004אולם \u0003אין\u0004 הם \u0003משביעין אותה על שעבר.\u0004","ויש לשאול: \u0003שעבר מאי עבידתיה\u0004 \u0005[מה עניינו],\u0006 עד מתי הוא נחשב עדיין כלשעבר ועדיין אין הנכסים נחשבים כרכוש היתומים ושוב אין תנאו לפוטרה מן השבועה מועיל? ועל כך \u0003אמר רב יהודה אמר רב: על אפוטרופיא שנעשית בחיי הבעל,\u0004","\u0003אבל\u0004 לגבי מה שנתעסקה בהם \u0003בין מיתה לקבורה — משבעינן לה\u0004 \u0005[משביעים אנו אותה],\u0006 שבאותה שעה הם כבר נחשבים כנכסי היתומים, ואין תנאו מועיל אלא כל עוד הם נכסיו. \u0003ורב מתנא אמר: אפילו בין מיתה לקבורה לא משבעינן לה\u0004 \u0005[אין אנו משביעים אותה],\u0006 \u0003דאמרי נהרדעי\u0004 \u0005[שאומרים\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003לכרגא ולמזוני\u0004 \u0005[ל\u0006צורך תשלום \u0005מיסים, ול\u0006צורך דמי \u0005מזונות\u0006 לילדים\u0005],\u0006 \u0003ול\u0004צורך הוצאות \u0003קבורה\u0004 שלו או של היתומים, \u0003מזבנינן בלא אכרזתא\u0004 \u0005[מוכרים אנו\u0006 נכסים שירשו היתומים \u0005בלי הכרזה].\u0006 משמע, שכיון שהדבר דחוף אין מקפידים ומדקדקים שלא יהא בכך הפסד ליורשים, ומאותו טעם גם אין משביעים אותה על מה שעשתה לצורך הקבורה, שבזמן דוחק כזה אינה יכולה לדקדק היטב בחשבונות.","\u0003אמר רבה אמר ר' חייא:\u0004 אם כתב נוסח \u0003\"\u0004ש\u0003לא נדר ו\u0004ש\u0003לא שבועה\",\u0004 המשמעות היא ש\u0003הוא אינו יכול להשביעה, אבל יורשין משביעין אותה.\u0004 ואם כתב לה \u0003\"נקי נדר נקי שבועה\" — בין הוא ובין יורשין אין משביעין אותה.\u0004 וטעמו של דבר — כי \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003לה\u0004 על ידי ניסוח הדברים בצורה זו: \u0003מנקית משבועתא\u0004 \u0005[\u0006הרי \u0005את מנוקה משבועה],\u0006 שאין עליך חובת שבועה בכל מקרה.","\u0003ורב יוסף אמר\u0004 בשם \u0003ר' חייא\u0004 להיפך: אם כתב לה \u0003\"\u0004ש\u0003לא נדר ו\u0004ש\u0003לא שבועה\" — הוא אינו יכול להשביעה, אבל יורשין משביעין אותה.\u0004 ואם כתב \u0003\"נקי נדר נקי שבועה\" — בין הוא ובין יורשין משביעין אותה.\u0004 וטעם הדבר כי \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003לה,\u0004 כלומר, זו היתה הכוונה: \u0003נקי נפשך בשבועתא\u0004 \u0005[עצמך\u0006 מחשד \u0005על ידי שבועה].\u0006","\u0003שלח ר' זכאי\u0004 מארץ ישראל \u0003למר עוקבא\u0004 פסק הלכה זה: \u0003בין\u0004 שכתב \u0003\"\u0004ש\u0003לא שבועה\" בין \"\u0004ש\u0003נקי שבועה\" בין\u0004 שכתב \u0003\"\u0004ש\u0003לא נדר\" ובין \"\u0004ש\u0003נקי נדר\"\u0004 והוסיף \u0003\"בנכסי\" — הוא אינו יכול להשביעה, אבל יורשין משביעין אותה.\u0004 אם כתב לה \u0003\"מנכסיא אילין\"\u0004 \u0005[מנכסים אלה] —\u0006 \u0003בין הוא ובין יורשיו אין משביעין אותה.\u0004","\u0003אמר רב נחמן אמר שמואל משום\u0004 (בשם) \u0003אבא שאול בן אימא מרים,\u0004 באופן אחר: \u0003בין\u0004 שכתב \u0003\"\u0004ש\u0003לא שבועה\" בין \"נקי שבועה\" בין\u0004 שכתב \u0003\"לא נדר\" ובין \"נקי נדר\" בין\u0004 שכתב \u0003\"מנכסי\" ובין\u0004 שכתב \u0003\"מנכסיא אילין\" — בין הוא ובין יורשיו אין משביעין אותה\u0004 מעיקר הדין, \u0003אבל מה אעשה שהרי אמרו חכמים: הבא ליפרע מנכסי יתומים — לא יפרע אלא בשבועה.\u0004 ולכן משביעים אותה בכל מקרה אם היא באה ליטול מן היתומים.","\u0003ואיכא דאמרי לה\u0004 \u0005[ויש שאומרים אותה]\u0006 את ההלכה הזו בנוסח אחר, בתור \u0003מתניתא\u0004 \u0005[ברייתא];\u0006 \u0003אבא שאול בן אימא מרים אמר: בין\u0004 שכתב \u0003\"\u0004ש\u0003לא שבועה\" בין \"נקי שבועה\" בין\u0004 שכתב \u0003\"\u0004ש\u0003לא נדר\" ובין \"נקי נדר\" בין\u0004 שכתב \u0003\"מנכסי\" ובין \"מנכסיא אילין\"\u0004 — מעיקר הדין \u0003בין הוא ובין יורשיו אין משביעין אותה, אבל מה אעשה שהרי אמרו חכמים: הבא ליפרע מנכסי יתומים לא יפרע אלא בשבועה. אמר רב נחמן אמר שמואל: הלכה\u0004 למעשה \u0003כבן אימא מרים.\u0004","\u0003הפוגמת כתובתה,\u0004 שמודה שנפרעה חלק מכתובתה — \u0003לא תפרע\u0004 את שאר הכתובה \u0003אלא בשבועה\u0004 שלא נפרעה כבר את כולה. וכן אם היה \u0003עד אחד מעידה שהיא,\u0004 הכתובה, \u0003פרועה — לא תפרע אלא בשבועה.\u0004 ובכל מקרה אם רצתה לגבות כתובתה \u0003מנכסי יתומים,\u0004 או \u0003מנכסים משועבדים,\u0004 או \u0003שלא בפניו\u0004 — \u0003לא תפרע אלא בשבועה.\u0004","ומסבירים: \u0003הפוגמת כתובתה כיצד?\u0004 — \u0003היתה כתובתה אלף זוז, ואמר לה\u0004 הבעל: \u0003התקבלת\u0004 (קיבלת) כבר \u0003כתובתיך, והיא אומרת: לא התקבלתי\u0004 (קיבלתי) \u0003אלא מנה\u0004 (מאה זוז) ממנה, כיון שהיא מודה במקצת — \u0003לא תפרע אלא בשבועה.\u0004","\u0003עד אחד מעידה שהיא פרועה כיצד?\u0004 — \u0003היתה כתובתה אלף זוז ואמר לה\u0004 הבעל: \u0003התקבלת כתובתיך, והיא אומרת: לא התקבלתי\u0004 כלל, \u0003ועד אחד מעידה שהיא פרועה — לא תפרע אלא בשבועה.\u0004","\u0003מנכסים משועבדים כיצד?\u0004 — \u0003מכר\u0004 הבעל \u0003נכסיו לאחרים\u0004 לאחר שנשאה \u0003והיא נפרעת מן הלקוחות,\u0004 שהרי שטר כתובה קודם לשטרי המכירה והיא טורפת את הנכסים מהם — \u0003לא תפרע אלא בשבועה.\u0004","\u0003מנכסי יתומים כיצד?\u0004 — \u0003מת והניח נכסיו ליתומים, והיא נפרעת מן היתומים\u0004 את סכום הכתובה — \u0003לא תפרע אלא בשבועה.\u0004","\u0003ושלא בפניו כיצד?\u0004 — \u0003הלך לו למדינת הים\u0004 ושלח לה גט, \u0003והיא נפרעת שלא בפניו — אינה נפרעת אלא בשבועה.\u0004"],["\u0003ר' שמעון אומר: כל זמן שהיא תובעת כתובתה — היורשין משביעין אותה, ואם אינה תובעת כתובתה — אין היורשין משביעין אותה.\u0004","\u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]\u0006 ששבועה זו של הפוגמת כתובתה \u0003שבועה דאורייתא\u0004 \u0005[מן התורה\u0006 היא, שהיא שבועת המודה במקצת, \u0003דקא טעין\u0004 \u0005[ש\u0006הוא \u0005טוען]\u0006 שפרע לה \u0003מאתים וקא\u0004 \u0005[והיא]\u0006 \u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003במאה, הויא ליה\u0004 \u0005[הרי זו]\u0006 \u0003הודאה במקצת הטענה, ו\u0004כלל הוא: \u0003כל המודה במקצת הטענה ישבע\u0004 מדין תורה.","\u0003אמר רבא: שתי תשובות בדבר\u0004 כדי לדחות סברה זאת: \u0003חדא\u0004 \u0005[אחת]\u0006 היא — ש\u0003כל הנשבעין ש\u0004מקור חובתם להשבע \u0003בתורה, נשבעין ולא משלמין,\u0004 כלומר, שאדם נשבע רק לפטור את עצמו מתשלום תביעה, \u0003ו\u0004אילו \u0003היא\u0004 במקרה זה \u0003נשבעת ונוטלת. ועוד:\u0004 הלא כלל הוא ש\u0003אין נשבעין על כפירת שעבוד קרקעות.\u0004 שאין שבועה מן התורה אלא לגבי מטלטלין, ולא על קרקעות ואם יש בתביעה גם צד של שעבוד קרקעות — אין מקום לשבועת המודה במקצת, והרי בכל כתובה יש שעבוד קרקעות!","\u0003אלא אמר רבא:\u0004 שבועה זו היא \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 ומדוע תיקנו אותה — כי \u0003דפרע\u0004 \u0005[\u0006זה \u0005שפורע] —\u0006 \u0003דייק\u0004 \u0005[מדייק]\u0006 וזוכר היטב, אבל \u0003דמיפרע\u0004 \u0005[\u0006זה \u0005שפורעים לו\u0006 כסף\u0005] —\u0006 \u0003לא דייק\u0004 \u0005[איננו מדייק],\u0006 וכיון שהבעל טוען שפרע, ודאי זוכר היטב \u0003ורמו רבנן\u0004 \u0005[והטילו חכמים]\u0006 חובת \u0003שבועה עלה\u0004 \u0005[עליה]\u0006 \u0003כי היכי דתידוק\u0004 \u0005[כדי שתדקדק]\u0006 ותיזכר בדבר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003פוגמת כתובתה בעדים,\u0004 שאומרת שנפרעה כבר חלק מכתובתה בפני עדים, \u0003מהו\u0004 הדין? האם לומר ש\u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לומר \u0003דפרעה\u0004 \u0005[שפרע לה]\u0006 את שאר הכתובה — \u0003בעדים הוה פרע\u0004 \u0005[היה פורע]\u0006 \u0003לה,\u0004 וכיון שאין לו עדים על השאר — הרי זו הוכחה שלא קיבלה יותר ואינה צריכה להשבע, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003איתרמויי איתרמי ליה\u0004 \u0005[נזדמן לו]\u0006 הדבר אז שהיו עדים בשעת פרעון, ואת שאר הכתובה פרע לה שלא בפני עדים, וצריכה להשבע על החלק האחר?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003כל הנשבעין ש\u0004מקור חובתם להשבע \u0003בתורה\u0004 — \u0003נשבעין ולא משלמין. ואלו נשבעין ונוטלין: השכיר\u0004 שתובע את שכרו מבעל הבית ובעל הבית טוען שכבר פרעו, \u0003והנגזל,\u0004 שראוהו נכנס לבית של אחר, וכשיצא ראוהו שמסתיר כלים תחת בגדיו, ולאחר מכן טען בעל הבית שנגנבו ממנו כלים, \u0003והנחבל\u0004 שתובע דמי פיצויים מן החובל בטענה שחבל בו והנתבע טוען שלא חבל בו כלל ועיקר, \u0003ו\u0004מי \u0003שכנגדו,\u0004 הצד האחר העומד כנגדו בבית הדין, שהיה צריך להשבע, והוא \u0003חשוד על השבועה, וחנוני\u0004 התובע חובו \u0003על\u0004 סמך הרשום ב\u0003פנקסו,\u0004 והנתבע טוען שלא נתחייב לו כלל, \u0003והפוגם שטרו שלא בעדים.\u0004 ומכאן נדייק ונאמר כי דווקא זה הפוגם שטרו \u0003שלא בעדים — אין\u0004 \u0005[כן]\u0006 חייב בשבועה, ואולם זה הפוגם שטרו \u0003בעדים — לא\u0004 נשבע כלל!","ודוחים: בלשון \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר],\u0006 ובאופן זה: \u0003לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאם נפרעה חלק \u0003בעדים\u0004 ש\u0003ודאי צריכה שבועה, אבל שלא בעדים אימא תיהוי\u0004 \u0005[אמור\u0006 ש\u0005תהיה]\u0006 \u0003כמשיב אבידה,\u0004 שהרי אין לו עדים שפרע, ואם היא הודתה מעצמה, נחשוב אותה כאילו השיבה לו אבידה, \u0003ותשקול\u0004 \u0005[ותיקח]\u0006 את השאר \u0003בלא שבועה\u0004 כדין כל משיב אבידה שאינו צריך להשבע שלא נטל חלק מן המציאה לעצמו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו בזה צריכה שבועה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003הפוגמת כתובתה\u0004 ומדייקת בסכום עד \u0003פחות פחות משוה פרוטה,\u0004 שאומרת בדיוק גמור כמה נטלה, ולא רק סכומים גדולים אלא אף סכומים קטנים מאד, \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דקא דייקא כולי האי\u0004 \u0005[שהיא מדייקת כל כך],\u0006 ודאי \u0003קושטא קא אמרה\u0004 \u0005[אמת היא אומרת],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003איערומי קא מערמא\u0004 \u0005[מערימה היא]?\u0006 שאלה זו לא נפתרה, והריהי \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003פוחתת כתובתה,\u0004 שאומרת שסכום הכתובה לא היה כסכום הרגיל, או כסכום הכתוב בשטר הכתובה אלא פחות מזה, \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003היינו\u0004 \u0005[זו היא]\u0006 ה\u0003פוגמת,\u0004 ואין הבדל בדין ביניהן, \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לחלק, שהרי \u0003פוגמת מודיא\u0004 \u0005[מודה]\u0006 \u0003במקצת\u0004 היא, ואילו \u0003הא לא קא מודיא\u0004 \u0005[זו אינה מודה]\u0006 \u0003במקצת\u0004 היא, ובכלל טוענת שלא קיבלה כלל, אלא שמעיקר הדבר סכום התביעה שלה היה קטן יותר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003פוחתת\u0004 כתובתה — \u0003תפרע שלא בשבועה. כיצד? היתה כתובתה אלף זוז, ואמר לה \"התקבלת\u0004 (קיבלת) \u0003כתובתיך\" והיא אומרת \"לא התקבלתי\u0004 (קיבלתי) כתובתי, \u0003ו\u0004אולם הכתובה \u0003אינה אלא מנה\"\u0004 — הרי זו \u0003נפרעת שלא בשבועה.\u0004","ושואלים: אם סומכים על דבריה, \u0003במאי גביא\u0004 \u0005[במה\u0006 היא \u0005גובה]\u0006 בעצם? \u0003בהאי שטרא\u0004 \u0005[בשטר זה]\u0006 של כתובה? הלא \u0003האי שטרא חספא בעלמא\u0004 \u0005[שטר זה חרס סתם]\u0006 \u0003הוא,\u0004 שהרי היא עצמה מודה שהשטר אינו שטר, שהרי הסכום שכתוב בו אינו אמיתי! \u0003אמר רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה: באומרת \"אמנה\u0004 (הסכם של נאמנות) \u0003היתה לי ביני לבינו\",\u0004 שאף שכתוב בו סכום גדול, לא אתבע אותו אלא בסכום קטן יותר, אבל השטר היה שטר אמיתי.","שנינו במשנה: היה \u0003עד אחד מעידה שהיא,\u0004 הכתובה, \u0003פרועה\u0004 — נשבעת האשה שעדיין לא נפרעה כתובתה כלל. \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]\u0006 כי מה שהיא נשבעת היא \u0003שבועה דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יקום עד אחד באיש לכל עון ולכל חטאת\"\u0004 (דברים יט, טו), ומכאן מדייקים: \u0003לכל עון ולכל חטאת הוא\u0004 ש\u0003אינו קם,\u0004 שאין עדות עד אחד מספיקה לצורך זה, \u0003אבל קם הוא לשבועה.\u0004 שלענין שבועה, עדות עד אחד יש בה כדי לחייב את הצד שכנגד בשבועה. \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל מקום שהשנים,\u0004 שני עדים שהיו מעידים כנגדו, \u0003מחייבין אותו\u0004 לשלם \u0003ממון\u0004 — עד \u0003אחד\u0004 שמעיד כנגדו \u0003מחייבו שבועה.\u0004","\u0003אמר רבא: שתי תשובות בדבר,\u0004 לדחות את הסברה שמדובר בשבועה מן התורה: \u0003חדא\u0004 \u0005[\u0006סיבה \u0005אחת]:\u0006 ש\u0003כל הנשבעין ש\u0004מקור חובתם להשבע \u0003בתורה, נשבעין ולא משלמין, והיא\u0004 במקרה הזה הלא \u0003נשבעת ונוטלת. ועוד:\u0004 הלא כלל הוא ש\u0003אין נשבעין על כפירת שיעבוד קרקעות,\u0004 והכתובה יש בה גם שעבוד קרקעות.","\u0003אלא אמר רבא:\u0004 שבועה זו \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 היא \u0003כדי להפיס\u0004 (לפייס, להרגיע) \u0003דעתו של בעל,\u0004 שכיון שיש עד שמעיד כנגד דבריה, רצו חכמים שתנוח דעתו של הבעל ותיקנו שתישבע, כדי שיהיה בטוח שאינו משלם לחינם.","\u0003אמר רב פפא:\u0004"],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003פיקח הוא\u0004 הבעל, \u0003מייתי לה\u0004 \u0005[מביא אותה]\u0006 \u0003לידי שבועה דאורייתא\u0004 \u0005[מן התורה],\u0006 במקרה בו יש לו רק עד אחד על פרעון הכתובה. כיצד? \u0003יהיב\u0004 \u0005[נותן]\u0006 \u0003לה\u0004 את פרעון \u0003כתובתה באפי חד סהדא\u0004 \u0005[בפני עד אחד]\u0006 פעם שניה \u0003וסמיך סהדא קמא אסהדא בתרא\u0004 \u0005[ומצרף\u0006 את \u0005העד הראשון לעד השני]\u0006 ויש כאן איפוא שני עדים על פרעון הכתובה \u0003ומוקים להו להנך קמאי\u0004 \u0005[ומעמיד את\u0006 הכספים \u0005הראשונים הללו\u0006 שנתן לה\u0005]\u0006 \u0003במלוה,\u0004 ואת הסכום שפרע בראשונה הוא תובע עכשיו כמלוה, וכיון שיש לו עד אחד המסייע לדבריו הוא יכול להשביעה מן התורה, משום שבמקרה זה היא נשבעת ונפטרת, וכן משום שאין בתביעה זו משום כפירה בקרקעות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: היאך סמיך סהדא קמא אסהדא בתרא\u0004 \u0005[איך סומך\u0006 מצרף את \u0005העד הראשון לעד השני],\u0006 שהרי אין הם מעידים כלל על אותו מעשה? \u0003אלא אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: יהיב\u0004 \u0005[נותן]\u0006 \u0003לה\u0004 את פרעון \u0003כתובתה\u0004 בפעם השניה \u0003באפי סהדא קמא וסהדא בתרא\u0004 \u0005[בפני העד הראשון והעד האחרון]\u0006 \u0003ומוקים לה להנך קמאי\u0004 \u0005[ומעמיד את\u0006 הכספים \u0005הראשונים הללו]\u0006 \u0003בהלואה\u0004 ותובעם ממנה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: אכתי\u0004 \u0005[עדיין]\u0006 \u0003יכולה\u0004 האשה \u0003למימר\u0004 \u0005[לומר]:\u0006 \u0003שתי כתובות הואי\u0004 \u0005[היו]\u0006 לי, שכתבת לי פעמיים כתובה ואת הראשונה קיבלתי בשעתה, ועוד אחת קיבלתי לאחר מכן ולא היתה הלוואה כלל! \u0003אלא אמר רב אשי: הוא דמודע להו\u0004 \u0005[שמודיע להם],\u0006 גם לעד הראשון וגם לאחרון שכבר פרע לה את כתובתה בפני אחד מהם והיא כופרת בפרעון זה ושרצונו לפורעה בשנית לשם כתובה כדי שיהיו לו שני עדים בדבר ויתבע את הראשונים שיש לו עליהם עד אחד כהלואה,, ותתחייב לו שבועה מן התורה, ומכיון שהודיע להם ואין העד הראשון מסייע לדבריה, שוב אינה יכולה לטעון שהיו אלה שתי כתובות, לפי שאין זה דבר מצוי.","שנינו במשנה שאם באה אשה ליטול את כתובתה \u0003מנכסים משועבדים,\u0004 אינה נפרעת אלא בשבועה. \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת שבועות: \u0003וכן היתומים לא יפרעו אלא בשבועה.\u0004","ושואלים: \u0003ממאן\u0004 \u0005[ממי]\u0006 צריכים הם להפרע בשבועה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מ\u0004ן ה\u0003לוה\u0004 שלווה מאביהם — \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003אביהן\u0004 שהוא המלווה \u0003שקיל\u0004 \u0005[לוקח]\u0006 מן הלווה \u0003בלא שבועה\u0004 וסומך על השטר \u0003ואינהו\u0004 \u0005[והם]\u0006 יתומים, שהקלו חכמים בדיניהם צריכים להפרע \u0003בשבועה?! אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וכן היתומים\u0004 של המלווה הבאים להפרע \u0003מן היתומים\u0004 של הלווה — \u0003לא יפרעו\u0004 מהם \u0003אלא בשבועה.\u0004","\u0003אמר רב זריקא אמר רב יהודה, לא שנו\u0004 שאם נשבעו היתומים כדין הריהם נפרעים, \u0003אלא\u0004 כ\u0003שאמרו\u0004 ה\u0003יתומים\u0004 של הלווה: \u0003אמר לנו אבא \"לויתי ופרעתי\", אבל\u0004 אם \u0003אמרו\u0004 היתומים: \u0003אמר לנו אבא \"לא לויתי\u0004 כלל\u0003\" — אף בשבועה לא יפרעו\u0004 מהם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: אדרבה\u0004 (להיפך), הלא כלל הוא בדיני טענות: \u0003כל האומר \"לא לויתי\",\u0004 בזמן שיש ראיות נגדו — \u0003כאומר \"לא פרעתי\" דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שהרי אם כדבריו שלא לוה כלל, הרי שודאי גם לא פרע, שהרי לדבריו לא היתה סיבה כלשהי לפרעון,","ומשלם הכל אף בלא שישבע המלווה! \u0003אלא\u0004 יש לתקן את הדברים, ו\u0003אי אתמר, הכי אתמר\u0004 \u0005[אם נאמר, כך נאמר],\u0006 \u0003אמר רב זריקא אמר רב יהודה: לא שנו אלא שאמרו יתומים: אמר לנו אבא \"לויתי ופרעתי\", אבל אמרו: אמר לנו אבא \"לא לויתי\" — נפרעין\u0004 אפילו \u0003שלא בשבועה. שכל האומר \"לא לויתי\" כאומר \"לא פרעתי\" דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ויש כאן הודאה מצד הלווה שלא פרע.","שנינו במשנה: \u0003ונפרעת שלא בפניו, לא תפרע אלא בשבועה. אמר רב אחא שר הבירה: מעשה בא לפני ר' יצחק באנטוכיא, ואמר: לא שנו\u0004 דין זה שיכולה האשה להפרע כתובתה בשבועה שלא בפני בעלה, \u0003אלא לכתובת אשה,\u0004 וזאת \u0003משום חינא\u0004 \u0005[\u0006שימצא \u0005חן]\u0006 בעיני האשה להינשא לו, ועשו תקנות לטובתה בכתובה. \u0003אבל בעל חוב — לא\u0004 יפרע כלל שלא בפני הלווה, שמא כבר פרע לו.","\u0003ורבא אמר\u0004 בשם \u0003רב נחמן: אפילו בעל חוב\u0004 נפרע בשבועה שלא בפני הלווה. וטעם הדבר: \u0003שלא יהא כל אחד ואחד נוטל\u0004 בהלוואה \u0003מעותיו של חברו, והולך ויושב במדינת הים,\u0004 ואי אפשר לגבות מנכסיו, \u0003ו\u0004אם אתה עושה כן, \u0003אתה\u0004 נמצא \u0003נועל דלת בפני לווין,\u0004 שאיש לא ירצה להלוות להם.","שנינו במשנה ש \u0003ר' שמעון אומר: כל זמן שתובעת כתובתה\u0004 היורשים משביעים אותה. ושואלים: \u0003ר' שמעון אהייא\u0004 \u0005[על איזה]\u0006 דבר במשנה הוא מתייחס? \u0003אמר ר' ירמיה: אהא\u0004 \u0005[על זו]\u0006 שאמרו \u0003ונפרעת שלא בפניו לא תפרע אלא בשבועה.\u0004 ומכאן אנחנו מבינים: \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היא באה להפרע מן הנכסים \u0003למזוני\u0004 \u0005[ל\u0006צורך \u0005מזונותיה],\u0006 \u0003ולא שנא\u0004 \u0005[שונה]\u0006 אם היא באה להפרע \u0003ל\u0004צורך ה\u0003כתובה, ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' שמעון למימר\u0004 \u0005[לומר]:\u0006 \u0003כל זמן שתובעת כתובתה — יורשיה\u0004 (יורשי נכסי בעלה) \u0003משביעין אותה\u0004 שלא נטלה מן הירושה כלום."],["\u0003אינה תובעת כתובתה — אין יורשין משביעין אותה. וקמיפלגי בפלוגתא\u0004 \u0005[וחלוקים\u0006 הם אפוא \u0005במחלוקת]\u0006 של \u0003חנן ובני כהנים גדולים. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהלך למדינת הים ואשתו תובעת מזונות, חנן אומר: תשבע בסוף,\u0004 כלומר, כאשר היא באה ליטול את כתובתה, תשבע שלא השאיר לה בעלה בצאתו שום כסף, ושלקחה רק למזונותיה, \u0003ולא תשבע בתחלה,\u0004 כאשר היא מקבלת את דמי המזונות מנכסיו.","\u0003נחלקו עליו בני כהנים גדולים ואמרו: תשבע בתחלה ובסוף.\u0004 שצריכה להשבע גם בתחילה כאשר היא באה ליטול מזונות, שלא השאיר לה בעלה כסף, וגם בסוף, כאשר היא באה ליטול כתובתה. ואם כן \u0003ר' שמעון כ\u0004שיטת \u0003חנן\u0004 שנשבעת רק כאשר באה ליטול כתובתה, ו\u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו — \u0003כבני כהנים גדולים\u0004 האומרים שנשבעת גם כאשר נוטלת מזונות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת\u0004 על דברי ר' ירמיה: \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של הבאה ליפרע שלא בפניו שנשבעת, וכי ה\u0003יורשין\u0004 הם ה\u0003משביעין אותה?\u0004 הלא \u0003בית דין משביעין אותה מיבעי ליה\u0004 \u0005[היה צריך לו\u0006 לומר\u0005]!\u0006","\u0003אלא אמר רב ששת:\u0004 יש לומר שדברי ר' שמעון מתייחסים \u0003אהא\u0004 \u0005[על זו]\u0006 ששנינו קודם: \u0003הלכה מקבר בעלה לבית אביה, או שחזרה לבית חמיה ולא נעשית אפוטרופיא\u0004 (אפוטרופסית) לנכסיו — \u0003אין היורשים משביעין אותה. ואם נעשית אפוטרופיא — יורשין משביעין אותה על העתיד לבא, ואין משביעין אותה על מה שעבר. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' שמעון למימר\u0004 \u0005[לומר]:\u0006 \u0003כל זמן שתובעת כתובתה — יורשין משביעין אותה,\u0004 וכל עוד \u0003אינה תובעת כתובתה — אין היורשין משביעין אותה.\u0004","\u0003וקמיפלגי\u0004 \u0005[וחלוקים\u0006 הם איפוא\u0005]\u0006 \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003אבא שאול ורבנן. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אפוטרופוס שמינהו אבי יתומים\u0004 שהוא יטפל בנכסים — כשגדלו ומחזיר להם את הנכסים, \u0003ישבע\u0004 שלא נטל לעצמו כלום. ואם \u0003מינוהו בית דין\u0004 לאפוטרופוס — \u0003לא ישבע\u0004 כדי שלא יימנעו אנשים מלהתמנות לאפוטרופוסים. \u0003אבא שאול אומר: חילוף הדברים\u0004 (להיפך), אם \u0003מינוהו בית דין — ישבע,\u0004 ואם \u0003מינהו אבי יתומים — לא ישבע.\u0004 וטעם הדבר: שכבוד הוא לאדם שמתמנה לאפוטרופוס על ידי בית דין ומוכן אף להשבע בשביל כך, אבל כשמינהו אבי יתומים, הוכיח על ידי מינוי זה שהוא סומך עליו ומאמין בו.","ונסביר כי \u0003ר' שמעון\u0004 סבור \u0003כאבא שאול,\u0004 שהואיל ונחשבת האשה כאפוטרופוס שמינהו אבי יתומים — לא תשבע אף על העתיד לבוא, אלא נשבעת רק אם תבעה כתובתה. \u0003ורבנן כרבנן\u0004 \u0005[וחכמים\u0006 סבורים \u0005כחכמים]\u0006 שאמרו שאם מינהו אבי יתומים צריך להשבע.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: האי\u0004 \u0005[זה],\u0006 הביטוי \u0003\"כל זמן שתובעת כתובתה\u0004 היורשים משביעים אותה\" מתאים רק אם בא ר' שמעון להחמיר על חכמים הפוטרים אותה בכל מקרה. אבל לפי הסברו של ר' ששת שבא ר' שמעון להקל, רק \u0003אם תובעת מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, כלומר, רק במקרה כזה צריכה שבועה!","\u0003אלא אמר אביי:\u0004 יש לומר שדברי ר' שמעון מתייחסים \u0003אהא\u0004 \u0005[על זה]\u0006 ששנינו למעלה: \u0003כתב לה \"נדר ושבועה אין לי עליך\" — אינו יכול להשביעה כו'.\u0004 ואם אמר: \u0003\"נדר ושבועה אין לי ולא ליורשי ולא לבאים ברשותי עליך ועל יורשיך ועל הבאין ברשותך\" — אין יכול להשביעה לא הוא ולא יורשיו ולא הבאין ברשותו, לא היא ולא יורשיה ולא הבאין ברשותה. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' שמעון למימר\u0004 \u0005[לומר]\u0006 כי \u0003כל זמן שתובעת כתובתה — יורשין\u0004 בכל זאת \u0003משביעין אותה.\u0004","\u0003וקמיפלגי בפלוגתא\u0004 \u0005[וחלוקים במחלוקת]\u0006 של \u0003אבא שאול בן אימא מרים ורבנן\u0004 \u0005[וחכמים]\u0006 שהזכרנו קודם (דף פז, א). \u0003ר' שמעון\u0004 סבור \u0003כ\u0004שיטת \u0003אבא שאול\u0004 האומר שגם כאשר פטר אותה משבועה תיקנו חכמים שאין נפרעים מנכסי יתומים אלא בשבועה. \u0003ורבנן כרבנן\u0004 \u0005[וחכמים\u0006 סבורים \u0005כחכמים]\u0006 שאמרו שאם פטר אותה משבועה — לא תשבע כלל.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: התינח\u0004 \u0005[זה נוח]\u0006 ומסביר במה חולק ר' שמעון על חכמים כשפסק ש\u0003כל זמן שתובעת כתובתה\u0004 משביעים אותה, אבל בחלק השני של דברי ר' שמעון כאשר \u0003אינה תובעת כתובתה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלפי הסבר זה אינו אלא חזרה בלבד על דבריו הקודמים!","\u0003אלא אמר רב פפא:\u0004 דברי ר' שמעון לא לענין זה הם מתייחסים אלא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004שיטת \u0003ר' אליעזר ומחלוקתו\u0004 (והחולקים עליו), ששניהם מודים (לעיל) שאפשר להשביע את האשה שלא נטלה מן הנכסים, אלא שלדעת חכמים משביעים אותה רק אם נעשתה אפוטרופסית, ולדעת ר' אליעזר בכל מקרה יכול להשביעה. ור' שמעון חולק עליהם ואומר שרק כאשר היא באה ליטול כתובתה, היורשים משביעים אותה על הכל (אף על פילכה). ואם אינה תובעת כתובה — אין להם רשות להשביעה אפילו על אפוטרופסות וחנות.","\u0003הוציאה גט ואין עמו כתובה,\u0004 שאין בידה כתובה, והיא תובעת דמי הכתובה מבעלה —"],["\u0003גובה כתובתה\u0004 ואינו יכול לטעון שכבר נתן לה.","אם הוציאה \u0003כתובה ואין עמה גט, היא אומרת: אבד גיטי. והוא אומר:\u0004 כמו שאבד גיטך כך \u0003אבד שוברי\u0004 (הקבלה שלי), שכבר שילמתי לך את כתובתך, ונתת לי שוברקבלה, ואבדתי אותו. \u0003וכן בעל חוב שהוציא שטר חוב\u0004 לאחר שנת השמיטה \u0003ואין עמו פרוזבול\u0004 (שטר שכתוב בו שמוסר את גביית החוב לבית דין, ואין השמיטה משמטתו) — \u0003הרי אלו לא יפרעו.\u0004","\u0003רבן שמעון בן גמליאל אומר: מן הסכנה ואילך,\u0004 שגזרה המלכות על המצוות ולכן היו משמידים מיד את הגט או את הפרוזבול — \u0003אשה גובה כתובתה שלא בגט, ובעל חוב גובה שלא בפרוזבול,\u0004 משום שיש מקום להניח שמן הסתם כתבו, אבל לא החזיקו אותם בידם משום שהיתה סכנה בכך.","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ממשנתנו ש\u0003כותבין שובר.\u0004 שאם פורע אדם שטרחוב, צריך המלוה לכתוב לו שוברקבלה ששולם. וכיצד מוכח הדבר — \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003אין כותבין שובר, ליחוש\u0004 \u0005[נחשוש]\u0006 בדין הראשון של משנתנו שגובה כתובתה על ידי הגט, שמא באמת הכתובה עדיין ברשותה, ו\u0003דלמא מפקא לה לכתובתה\u0004 \u0005[שמא תוציא את כתובתה]\u0006 בבית דין אחר, \u0003וגביא\u0004 \u0005[וגובה]\u0006 \u0003בה\u0004 בפעם שניה, שהרי לא יוכל בעלה להוכיח שפרע אלמלא יש לו שובר.","\u0003אמר רב:\u0004 יש לדחות ראיה זו, כי \u0003במקום שאין כותבין כתובה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ששם מסתפקים בתנאי הקבוע של חכמים שהבעל חייב לתת את סכום הכתובה, גם אם לא כתב שטר, ואין לחשוש שמא הכתובה בידה ותוציא אותה פעם אחרת. \u0003ושמואל אמר:\u0004 כאשר האשה מציגה את גיטה — נותן לה כתובתה \u0003אף במקום שכותבין כתובה\u0004 ואומרת שאיבדה אותה.","ושואלים: \u0003ול\u0004דעת \u0003שמואל\u0004 האם באמת \u0003כותבין שובר? אמר רב ענן: לדידי מיפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003מר שמואל\u0004 עצמו שמדובר בשני אופנים, או \u0003במקום שאין כותבין\u0004 כתובה \u0003ו\u0004הוא \u0003אמר \"כתבתי\u0004 כתובה \u0003\"\u0004— \u0003עליו להביא ראיה\u0004 שכתב כתובה, ואז אינה יכולה להפרע אלא כאשר מביאה את כתובתה, או \u0003במקום שכותבין\u0004 כתובה \u0003ואמרה \"לא כתב לי\" — עליה להביא ראיה\u0004 שלא כתב, ותגבה בלא כתובה.","\u0003ואף רב הדר ביה\u0004 \u0005[חזר בו]\u0006 מדבריו בפירוש המשנה, ש\u0003אמר רב\u0004 פסק הלכה: \u0003בין במקום שכותבין, בין במקום שאין כותבין,\u0004 אם מוציאה \u0003גט\u0004 בלא כתובה — \u0003גובה עיקר\u0004 כתובה, כלומר, את סכום הכתובה הקטן ביותר שתיקנו חכמים לאשה במעמדה (מאתים לבתולה, ומאה לאשה אחרת). ואם מוציאה \u0003כתובה\u0004 ובה כתוב סכום גדול יותר ואינה מוציאה גיטה — \u0003גובה\u0004 רק את ה\u0003תוספת\u0004 הכתובה בכתובה יתר על עיקר הכתובה. \u0003וכל הרוצה להשיב\u0004 — \u0003יבא וישיב,\u0004 שאין עוד מקום לחשוש לרמאות, שלא תרוויח כלום אם תוציא את הכתובה במקום אחר.","ותוהים: מדוע אין מקום לחשוש? והרי \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 הוציאה \u0003כתובה ואין עמה גט, היא אומרת \"אבד גיטי\" והוא אומר \"אבד שוברי\", וכן בעל חוב שהוציא שטר חוב ואין עמו פרוזבול — הרי אלו לא יפרעו.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003שמואל — מוקי לה\u0004 \u0005[מעמיד,\u0006 מסביר, \u0005אותה]\u0006 \u0003במקום שאין כותבין ואמר \"כתבתי\", דאמרינן ליה\u0004 \u0005[שאנו אומרים לו]\u0006 לדעת שמואל: \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה\u0004 שאכן כתבת, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא מייתי\u0004 \u0005[מביא]\u0006 \u0003ראיה, אמרינן ליה\u0004 \u0005[אומרים אנו לו]:\u0006 \u0003זיל פרעיה\u0004 \u0005[לך פרע]\u0006 אותן, ועכשיו שהוציאה הכתובה טוען הבעל שכבר פרע על ידי הגט, ואבד השובר.","\u0003אלא לרב, נהי\u0004 \u0005[אם אמנם]\u0006 שאת \u0003עיקר\u0004 הכתובה \u0003לא גביא\u0004 \u0005[אינה גובה]\u0006 על ידי כתובה, שיכול לטעון שכבר קיבלה את עיקר כתובתה בבית דין אחר על ידי הגט, מכל מקום את ה\u0003תוספת מיהא תיגבי\u0004 \u0005[על כל פנים תגבה]\u0006 מכוח הכתובה.","\u0003אמר רב יוסף: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשאין שם\u0004 גם \u0003עדי גירושין. מיגו\u0004 \u0005[מתוך]\u0006 ש\u0003יכול למימר\u0004 \u0005[לומר]\u0006 ולהכחיש הכל, ולומר \u0003לא גירשתיה\u0004 כלל, ולא מגיע לה ולא כלום,"],["\u0003יכול\u0004 הוא אף \u0003למימר\u0004 \u0005[לומר]:\u0006 \u0003גירשתיה ונתתי לה כתובתה.\u0004","ושואלים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה\u0006 ב\u0005סופה]\u0006 של המשנה: \u0003רבן שמעון בן גמליאל אומר: מן הסכנה ואילך אשה גובה כתובתה שלא בגט, ובעל חוב שלא בפרוזבול.\u0004 ובעל כורחנו \u0003בדאיכא\u0004 \u0005[בשיש]\u0006 \u0003עדי גירושין עסקינן\u0004 \u0005[אנו עוסקים],\u0006 \u0003דאי ליכא\u0004 \u0005[שאם אין]\u0006 \u0003עדי גירושין, במאי גביא\u0004 \u0005[במה\u0006 היא \u0005גובה]?\u0006 שהרי אין לה שום עדות שהיא גרושה, ומכיון שיש עידי גירושין ממילא אין אפשרות לטעון \"לא גרשתיה\"!","\u0003אלא\u0004 עלינו לחזור מן הפירוש הקודם ולהסביר כי המשנה \u0003כולה\u0004 שיטת \u0003רבן שמעון בן גמליאל היא, וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה \u0005וכך\u0006 היא \u0005שנויה,\u0006 כך צריך לשנותה\u0005]:\u0006 \u0003הרי אלו לא יפרעו, במה דברים אמורים — כשאין שם עדי גירושין, אבל\u0004 אם \u0003יש שם עדי גירושין — גביא\u0004 \u0005[גובה]\u0006 \u0003תוספת\u0004 ולא עיקר, שמא תוציא את הגט ותגבה פעם שניה. \u0003ועיקר\u0004 כתובה, \u0003אי מפקא גיטא\u0004 \u0005[אם מוציאה\u0006 את ה\u0005גט] —\u0006 \u0003גביא\u0004 \u0005[גובה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא מפקא גיטא\u0004 \u0005[מוציאה\u0006 את ה\u0005גט]\u0006 — הריהי \u0003לא גביא\u0004 \u0005[גובה].\u0006","\u0003ומן הסכנה ואילך, אף על גב דלא מפקא גיטא\u0004 \u0005[אף על פי שאינה מוציאה\u0006 את ה\u0005גט] —\u0006 \u0003גביא\u0004 \u0005[גובה]\u0006 אף את העיקר. \u0003שרבן שמעון בן גמליאל אומר: מסכנה ואילך אשה גובה כתובתה שלא בגט, ובעל חוב שלא בפרוזבול.\u0004","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003רב כהנא ורב אסי לרב: לדידך\u0004 \u0005[לשיטתך]\u0006 ש\u0003אמרת\u0004 כי כאשר מוציאה \u0003גט היא גובה\u0004 את \u0003עיקר\u0004 הכתובה, אם כן \u0003אלמנה מן הנשואין במאי גביא\u0004 \u0005[במה\u0006 היא \u0005גובה]\u0006 את עיקר הכתובה והרי לא קיבלה ממנו גט? — ודאי שהיא גובה \u0003בעדי מיתה,\u0004 המעידים שמת בעלה, ועדיין יש לשאול: \u0003וליחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 \u0003גירשה\u0004 לפני מותו, \u0003ו\u0004לאחר שתקבל את כתובתה על ידי עדי מיתה, \u0003מפקא לגיטא וגביא ביה\u0004 \u0005[מוציאה את הגט\u0006 שקיבלה \u0005וגובה בו]\u0006 פעם שניה?! תירץ להם רב: מדובר פה \u0003ביושבת תחת בעלה\u0004 כל הזמן, ויודעים שלא גירשה.","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003סמוך למיתה גירשה,\u0004 שאז אין יודעים שגירש אותה, ויש לחשוש שתגבה כתובתה פעמיים! ומשיבים: במקרה כזה \u0003איהו הוא דאפסיד אנפשיה\u0004 \u0005[הוא\u0006 עצמו זה \u0005שהפסיד לעצמו]\u0006 בזה שלא נזהר להודיע על הגירושין לאחרים, ואין צריכים לחשוש לכך.","ועוד שאלו אותו: \u0003אלמנה מן האירוסין במאי גביא\u0004 \u0005[במה\u0006 היא \u0005גובה]\u0006 את כתובתה — \u0003בעדי מיתה, וליחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 \u0003גירשה\u0004 לפני כן, \u0003ו\u0004לאחר שתקבל כתובה על ידי עדי מיתה \u0003מפקא גיטא וגביא\u0004 \u0005[מוציאה\u0006 את \u0005הגט וגובה],\u0006 וכיון שהארוסה לא היתה גרה בביתו, אין יודעים אם גירש אותה!","\u0003אלא\u0004 צריך לומר: \u0003במקום\u0004 ש\u0003לא אפשר\u0004 ואין דרך אחרת, \u0003כתבינן\u0004 \u0005[כותבים אנו]\u0006 \u0003שובר\u0004 המוכיח שכבר נפרעה כתובתה ואותו היא נותנת לו. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שלעיתים צריך לכתוב שובר, לגבי \u0003עדי מיתה גופייהו\u0004 \u0005[עצמם]\u0006 \u0003ניחוש דלמא מפקא\u0004 \u0005[נחשוש שמא מוציאה,\u0006 מביאה\u0005]\u0006 \u0003עדי מיתה בהאי בי דינא וגביא\u0004 \u0005[בבית דין זה וגובה\u0006 את הכתובה\u0005],\u0006 \u0003והדר מפקא בבי דינא אחרינא וגביא\u0004 \u0005[וחוזרת\u0006 ו\u0005מוציאה,\u0006 מביאה, עדים \u0005בבית דין אחר וגובה\u0006 שוב\u0005]\u0006 ואין לדבר סוף. \u0003אלא ודאי במקום\u0004 ש\u0003לא אפשר\u0004 למנוע ממנה שתוציא שלא כדין, \u0003כתבינן\u0004 \u0005[כותבים אנו]\u0006 לו \u0003שובר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר קשישא\u0004 \u0005[הזקן]\u0006 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חסדא לרב אשי: אלמנה מן האירוסין, מנלן דאית\u0004 \u0005[מנין לנו שיש]\u0006 \u0003לה\u0004 בכלל \u0003כתובה?\u0004 שמא לא תיקנו כתובה אלא לנשואה בלבד?! \u0003אילימא מהא\u0004 \u0005[אם תאמר\u0006 שהראיה היא \u0005מזו]\u0006 ששנינו: \u0003נתארמלה\u0004 (נתאלמנה) \u0003או נתגרשה, בין מן האירוסין בין מן הנשואין — גובה את הכל,\u0004 אולם מכאן אין ראיה, כי \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר במקרה שהוא \u0003כתב לה\u0004 כתובה מעצמו, אף שאין זו תקנת חכמים קבועה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כתב לה\u0004 כתובה, \u0003מאי למימרא\u0004 \u0005[\u0006לצורך \u0005מה\u0006 יש \u0005לומר]\u0006 שגובה הכל, הרי שטר בידה! אפשר להסביר שבא הדבר \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' אלעזר בן עזריה,\u0004 ש\u0003אמר\u0004 שאין לארוסה שנתגרשה או שמת בעלה תוספת כתובה, כיון \u0003שלא כתב לה\u0004 תוספת \u0003אלא על מנת שהוא כונסה\u0004 (נושא אותה), ובודאי אם היה יודע שימות עוד לפני שישא אותה לא היה מתחייב לה כלום.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 לפרש כך, \u0003דקתני\u0004 \u0005[ששנה\u0006 שם\u0005]\u0006 \u0003גובה את הכל,\u0004 ומשמע, בין עיקר בין תוספת. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003כתב לה\u0004 כתובה — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003גובה את הכל,\u0004 את עיקר הכתובה ואת התוספת. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא כתב לה\u0004 כתובה, והיא גובה על סמך תקנת חכמים. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"גובה את הכל\"? מנה\u0004 או \u0003מאתים\u0004 שזה עיקר הכתובה \u0003הוא דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 ולא יותר, ואין מקום ללשון \"הכל\"!","\u0003ואלא\u0004 יש להביא ראיה שיש לארוסה כתובה מתקנת חכמים, \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003רב חייא בר אבין: אשתו ארוסה — לא אונן\u0004 (באבילות חמורה ביום ראשון למיתתה), שאינו נאסר באכילת קדשים, \u0003ולא מיטמא לה\u0004 אם כהן הוא. \u0003וכן היא לא אוננת ולא מיטמאה לו.\u0004 אם \u0003מתה — אינו יורשה,\u0004 ואם \u0003מת הוא — גובה כתובתה.\u0004 ומכאן נוכיח שיש לה כתובה.","אולם אפשר לדחות גם כאן ולומר: \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר דווקא במקרה ש\u0003כתב לה\u0004 מעצמו. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כתב לה\u0004 כתובה \u0003מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר],\u0006 מה החידוש בכך שגובה? יש לומר: כי \u0003מתה אינו יורשה איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 שבזה יש חידוש שלמרות שכתב לה כתובה, אינו יורשה אם מתה. ולשאלה העיקרית לא נמצא איפוא פתרון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב הונא: ל\u0004דעת \u0003רב\u0004 ש\u0003אמר\u0004 כי אם הוציאה \u0003גט גובה\u0004 את \u0003עיקר\u0004 הכתובה, \u0003ליחוש דלמא מפקא גיטא בהאי בי דינא וגביא\u0004 \u0005[נחשוש שמא תוציא\u0006 את ה\u0005גט בבית דין זה ותגבה],\u0006 \u0003והדרא מפקא בבי דינא אחרינא וגביא\u0004 \u0005[וחוזרת ומוציאה\u0006 את אותו גט \u0005בבית דין אחר וגובה\u0006 שוב\u0005]?\u0006 \u0003וכי תימא דקרעינן ליה\u0004 \u0005[ואם תאמר שקורעים\u0006 אנו \u0005אותו]\u0006 כדרך שעושים בכל שטר פרוע — כאן לא תניח שיקרעוהו! והטעם — \u0003אמרה\u0004 \u0005[אומרת\u0006 היא\u0005]:\u0006 אינני רוצה שתקרעו את השטר, כי \u0003בעינא לאנסובי ביה\u0004 \u0005[רוצה אני להינשא בו],\u0006 כלומר, כשארצה להינשא תהיה בידי ראיה שאני גרושה ואיני עוד נשואה.","השיב רב הונא: \u0003דקרעינן ליה וכתבינן אגביה\u0004 \u0005[שקורעים אותו,\u0006 את הגט, \u0005וכותבים על גביו]\u0006 נוסח זה: \u0003גיטא דנן קרענוהי לאו משום דגיטא\u0004 \u0005[גט זה קרענוהו לא מפני שגט]\u0006 \u0003פסול הוא, אלא\u0004 כדי ש\u0003לא תיהדר ותיגבי ביה זמנא אחרינא\u0004 \u0005[תחזור ותגבה בו פעם אחרת].\u0006","היו לאשה \u0003שני גיטין ושתי כתובות,\u0004 שנישאה לבעלה והתגרשה וחזרה ונישאה לו; כיון שיש בידה מסמכים אלה משמע שלא שילם לה גם את הכתובה הראשונה, ולכן היא \u0003גובה שתי כתובות.\u0004","היו לה \u0003שתי כתובות וגט אחד\u0004 בלבד, \u0003או כתובה\u0004 אחת \u0003ושני גטין, או כתובה וגט ו\u0004עדי \u0003מיתה\u0004 המעידים שמת בעלה אחרי שחזרה ונישאה לו — \u0003אינה גובה אלא כתובה אחת.\u0004 ומדוע? שאנחנו מניחים בדרך כלל \u0003שהמגרש את אשתו והחזירה — על מנת כתובה הראשונה מחזירה,\u0004 והיא הסכימה שתפרע ממנו רק כתובה הראשונה, אלא אם כן כתב לה כתובה חדשה.","שנינו במשנה שאם היו לה שתי כתובות וגט אחד אינה גובה אלא כתובה אחת, אבל לא נאמר איזו מן הכתובות היא גובה, והאם נאמר ש\u0003אי בעיא בהאי\u0004 \u0005[אם\u0006 היא \u0005רוצה\u0006 לגבות \u0005בזה] —\u0006 \u0003גביא\u0004 \u0005[גובה],\u0006 ו\u0003אי בעיא בהאי\u0004 \u0005[אם\u0006 היא \u0005רוצה\u0006 לגבות \u0005בזה] —\u0006 \u0003גביא\u0004 \u0005[גובה]?\u0006 שהיא יכולה להחליט באיזו מן הכתובות היא רוצה, וכגון באופן שמעדיפה אחת מהן מאחר והיא מרובה מחברתה, או שמעדיפה כתובה שהתאריך בה מוקדם משל חברתה ויכולה לטרוף מלקוחות.","ושואלים: אם כן, \u0003לימא תיהוי תיובתא\u0004 \u0005[נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה\u0006 על\u0005]\u0006 שיטת \u0003רב נחמן אמר שמואל.\u0004 ש\u0003אמר רב נחמן אמר שמואל: שני שטרות היוצאין בזה אחר זה\u0004 בהפרש של כמה ימים באותו ענין עצמו (מכר, או מתנה) ההנחה היא ש\u0003ביטל\u0004 השטר ה\u0003שני את הראשון\u0004 ומדוע לא נאמר גם כאן שביטלה כתובה שניה את הראשונה?","ומשיבים: \u0003לאו אתמר עלה\u0004 \u0005[\u0006וכי \u0005לא נאמר עליה]\u0006 ש\u0003אמר רב פפא: ומודה רב נחמן דאי אוסיף ביה דיקלא\u0004 \u0005[שאם הוסיף בו דקל],\u0006 כגון שבשטר מכר השני הוסיף והזכיר דקל שלא היה בראשון, מסתבר שלא ביטל השני את הראשון, אלא את השני רק \u0003לתוספת כתביה\u0004 \u0005[כתבו],\u0006 \u0003הכא נמי בדאוסיף\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005ב\u0006מקרה \u0005שהוסיף]\u0006 \u0003לה\u0004 דבר מה בכתובה השניה ואז מוכח שלא ביטל את הכתובה הראשונה, אלא רצה להוסיף עליה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הוציאה גט וכתובה ו\u0004עדי \u0003מיתה\u0004 המעידים שמת בעלה אחרי שחזרה ונישאה לו,"],["\u0003אם\u0004 התאריך המצויין ב\u0003גט קודם ל\u0004תאריך המצויין ב\u0003כתובה — גובה שתי כתובות,\u0004 שמגיעה לה כתובה אחת כשמוציאה את הגט, וכתובה שניה שכתב לה כאשר חזר ונשאה. ואם היה זמן ה\u0003כתובה קודמת לגט — אינה גובה אלא כתובה אחת,\u0004 ומדוע? \u0003שהמגרש את אשתו והחזירה — על מנת כתובה הראשונה החזירה,\u0004 אלא אם כן יש הוכחה להיפך.","\u0003קטן שהשיאו אביו\u0004 אשה — \u0003כתובתה\u0004 שכתב לה כשהוא קטן \u0003קיימת\u0004 ויש לה תוקף גם כאשר גדל, ואין הוא יכול לומר שבעודו קטן נכתבה, ולכן, אין לה תוקף, \u0003שעל מנת כן,\u0004 על מנת התנאים הכתובים בכתובה הזו, \u0003קיימה\u0004 כשגדל. וכן \u0003גר שנתגיירה אשתו עמו — כתובתה\u0004 שהיתה לה בזמן שהיתה גויה \u0003קיימת, שעל מנת כן קיימה.\u0004","\u0003אמר רב הונא: לא שנו\u0004 שהכתובה קיימת \u0003אלא\u0004 לענין \u0003מנה\u0004 או \u0003מאתים\u0004 שמגיעים לה מכוח תקנת חכמים, \u0003אבל תוספת\u0004 שכתב בכתובה — \u0003אין לה,\u0004 ששטר זה שנכתב בשעתו שלא כדין, אין לו בעצם כל תוקף. \u0003ורב יהודה אמר: אפילו תוספת יש לה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: אם \u0003חידשו\u0004 הקטן לאחר שהגדיל, או הגר לאחר שנתגייר, משהו בכתובה הישנה והוסיפו בה דברים — \u0003נוטלת מה שחידשו,\u0004 ומכאן נדייק: מה ש\u0003חידשו — אין\u0004 \u0005[כן]\u0006 נוטלת, מה ש\u0003לא חידשו — לא!\u0004","ודוחים: \u0003אימא\u0004 \u0005[אמור]:\u0006 נוטלת \u0003אף מה שחידשו\u0004 נוסף על הכתובה הישנה כולה. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא תני הכי\u0004 \u0005[שנה כך],\u0006 אלא שנה בהמשך להיפך: \u0003חידשו — נוטלת מה שחידשו, לא חידשו — בתולה גובה מאתים ואלמנה מנה\u0004 אבל לא תוספת! הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רב יהודה,\u0004 ונדחו דבריו.","ומסבירים: \u0003רב יהודה מתניתין אטעיתיה\u0004 \u0005[משנתנו הטעתה אותו],\u0006 שמלשון המשנה הגיע למסקנה לא נכונה, כי \u0003הוא סבר\u0004 \u0005[חשב]\u0006 שמה ששנינו \u0003\"כתובתה קיימת\" אכולה מילתא קאי\u0004 \u0005[על כל הדברים\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 שכל מה שכתוב בשטר הכתובה עומד בתוקפו. \u0003ולא היא\u0004 \u0005[ואינו כן],\u0006 אלא על \u0003עיקר\u0004 ה\u0003כתובה קאי\u0004 \u0005[עומד,\u0006 מתייחס הדבר\u0005],\u0006 שיש לה כתובה כתקנת חכמים ולא תוספת.","","\u0003מי שהיה נשוי שתי נשים, ומת\u0004 — האשה \u0003הראשונה\u0004 שנשא \u0003קודמת לשניה\u0004 לגבי גביית הכתובה, שהרי שטרה הוא מתאריך מוקדם לזה של חברתה. \u0003ו\u0004כן אם מתה לפני שהספיקה לגבות את כתובתה — \u0003יורשי הראשונה\u0004 הבאים לגבות את כתובת אמם \u0003קודמין ליורשי\u0004 האשה \u0003השניה.\u0004","\u0003נשא את הראשונה ומתה\u0004 בחייו, \u0003נשא שניה ומת הוא — שניה ויורשיה קודמין ליורשי הראשונה\u0004 הבאים לגבות \"כתובת בנין דיכרין\". משום שהכתובה של השניה נגבית בגדר חוב, ואילו לגבי כתובה הראשונה — היורשים באים לקחת מכוח ירושה, ואין היורשים נוטלים מן המשועבדים לבעלי החובות, אלא ממה שנותר לאחר תשלום החובות.","בלשון המשנה מדייקים: \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003\"הראשונה קודמת לשניה\", ולא קתני\u0004 \u0005[שנה]\u0006 בלשון פשוטה יותר \u0003\"הראשונה יש לה והשניה אין לה\", מכלל\u0004 הדברים אתה יכול להסיק \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003קדמה\u0004 ה\u0003שניה ותפסה\u0004 נכסים לפרעון כתובתה — \u0003לא מפקינן מינה\u0004 \u0005[מוציאים ממנה]\u0006 את שתפסה, ואין זכותה מתבטלת לגמרי,","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כלל: \u0003בעל חוב\u0004 ששטרו \u0003מאוחר, שקדם וגבה\u0004 מן הנכסים — \u0003מה שגבה גבה\u0004 ואין מוציאים מידו.","ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003מה שגבה — לא גבה\u0004 וצריך להחזיר לבעל חוב ראשון. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"קודמת\"\u0004 במשנה — \u0003לגמרי קתני\u0004 \u0005[שנה],\u0006 כלומר, שקודמת ויש לה זכות בלעדית, ואין לאחרת כל זכות אף על ידי תפיסה. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003בן קודם לבת\u0004 בירושה, שאין הכוונה שאם קדמה הבת ונטלה — זכתה, אלא הבן קודם לגמרי, ובמקום שיש בן אין לבת כלום, וכך הוא גם בעניינינו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את הדיון הזה בנוסח אחר: \u0003מ\u0004כיון ש\u0003לא קתני\u0004 \u0005[שנה]\u0006 \u0003\"אם קדמה שניה ותפסה אין מוציאין מידה\", מכלל\u0004 הדברים אתה יכול ללמוד \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003קדמה\u0004 ה\u0003שניה ותפסה — מפקינן מינה\u0004 \u0005[מוציאים ממנה],\u0006","\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כלל: \u0003בעל חוב מאוחר שקדם וגבה — מה שגבה לא גבה.\u0004","ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003מה שגבה\u0004 בעל חוב מאוחר — \u0003גבה,\u0004 אלא \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 בהמשך \u0003שניה ויורשיה קודמין ליורשי הראשונה,\u0004 ואפילו תפסו יורשי הראשונים — מוציאים מידם, משום שאינם יורשים חוב זה."],["\u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 באותו סגנון: \u0003הראשונה קודמת לשניה\u0004 ולא אמר בלשון חד משמעית שאם תפסה השניה מוציאה מידה.","שנינו במשנה: \u0003נשא את הראשונה\u0004 ומתה, נשא את השניה ומת הוא — שניה ויורשיה קודמים ליורשי הראשונה. ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד ממנה,\u0006 מהלכה זו, \u0005שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שאם מתו נשיו \u0003אחת בחייו ואחת במותו יש להן\u0004 לבנים מאשתו הראשונה שמתה בחייו \u0003כתובת בנין דכרין, ולא חיישינן לאינצויי\u0004 \u0005[ואין אנו חוששים לקטטה]\u0006 שמא ירצו בני השניה שאין להם \"כתובת בנין דכרין\", שכבר קיבלו את חלקם בכתובת אמם, למנוע מהם לקחת את חלקם בירושה וירצו לחלוק עימם בתור יורשי האב.","\u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 יודע אתה דבר זה — \u0003מדקתני\u0004 \u0005[ממה ששנה]:\u0006 \u0003שניה ויורשיה קודמים ליורשי ראשונה,\u0004 ונדייק: \u0003מיקדם הוא דקדמי\u0004 \u0005[קודמים\u0006 הם להם\u0005],\u0006 \u0003הא איכא\u0004 \u0005[הרי\u0006 אם \u0005יש]\u0006 נכסים כדי לשלם לכולם — \u0003שקלי\u0004 \u0005[לוקחים]\u0006 גם בני הראשונה חלקם בכתובת בנין דיכרין.","\u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 גם ש\u0003כתובה נעשית מותר לחברתה,\u0004 שאמרו חכמים שכאשר באים היורשים ליטול כתובת בנין דכרין, צריך שישאר סכום שיוכלו לקיים בו דין הירושה שמן התורה, ואמרו שיכולה הכתובה שנוטלים יורשי השניה להיחשב בתור ירושה.","\u0003ממאי\u0004 \u0005[ממה]\u0006 לומד אתה דבר זה? \u0003מ\u0004מה ש\u0003לא קתני\u0004 במשנה \u0003\"אם יש שם מותר דינר\"\u0004 נוסף לכתובות.","\u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 ש\u0003כתובת בנין דכרין לא טרפה ממשעבדי\u0004 \u0005[אינה טורפת מ\u0006נכסים \u0005משועבדים]\u0006 כשאר חוב, \u0003דאי סלקא דעתין טרפה ממשעבדי\u0004 \u0005[שאם עולה על דעתנו\u0006 לומר שהיא \u0005טורפת מ\u0006נכסים \u0005משועבדים],\u0006 אם כן \u0003ליתו\u0004 \u0005[שיבואו]\u0006 \u0003בני\u0004 האשה ה\u0003ראשונה ולטרפינהו\u0004 \u0005[ויטרפו]\u0006 את כתובת בנין דיכרין שלהם מ\u0003בני\u0004 האשה ה\u0003שניה\u0004 מהנכסים שגבו לכתובת אמם, שהרי להם יש שעבוד מוקדם על הנכסים מכוח כתובת אמם, אלא נחשבים לענין זה כיורשים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי\u0004 על מסקנות אלה: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוציא אתה מסקנות אלה? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי מתה \u0003אחת בחייו ואחת במותו אין להן\u0004 לבניה \u0003כתובת בנין דכרין\u0004 כלל, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"קודמין\"\u0004 שנאמר במשנה, לא לענין כתובת בנין דכרין, אלא \u0003ל\u0004ענין \u0003נחלה קתני\u0004 \u0005[שנה],\u0006 שקודם נוטלים בני השניה כתובת אמן ואחר כך חולקים עם בני הראשונה במה שנותר מנחלת אביהם.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 אם מדובר כאן בירושת האב, הבאה לבנים מכוחו, \u0003\"יורשי הראשונה\" למה לי,\u0004 שהרי לפי הסבר זה הם יורשים את אביהם ולא מכוח כתובת אמם, ומדוע קוראים להם \"יורשי הראשונה\"? יש לומר \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003\"שניה ויורשיה\"\u0004 שהם יורשים את כתובת אמם, \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 באותו סגנון \u0003\"ליורשי הראשונה\",\u0004 אבל אין מכאן הוכחה לענין הלכה.","\u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 כי מוכח מכאן כי \u0003כתובה נעשית מותר לחברתה\u0004 — גם את זה יש לדחות: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003אין כתובה נעשית מותר לחברתה, והכא הוא דאיכא\u0004 \u0005[וכאן הוא\u0006 מדובר \u0005שיש]\u0006 גם בלעדי זה \u0003מותר דינר,\u0004 ודי בכך כדי שיוכלו ליטול כתובת בנים דיכרין, ולא פירש את הדבר, משום שאינו עניינה של משנה זו.","\u0003\"ואחת בחייו ואחת במותו\" — תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 אם יש לבני זו שמתה בחייו כתובת בנין דכרין, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מתו\u0004 הנשים שנשא \u0003אחת בחייו ואחת במותו, בן ננס אומר:\u0004 אם אין מותר דינר, \u0003יכולין בני הראשונה לומר לבני השניה: בני בעלת חוב אתם,\u0004 שהרי אתם באים לקבל כתובת אמכם כיורשי שטר חוב (כתובה), אם כן \u0003טלו כתובת אמכם וצאו.\u0004 ואנו נירש את השאר מכוח כתובת בנין דיכרין.","\u0003ר' עקיבא אומר:\u0004 אינו כן, אלא כאשר מת האב \u0003כבר קפצה נחלה מלפני בני הראשונה ונפלה\u0004 כירושה גם \u0003לפני בני השניה,\u0004 ובני השניה מקבלים כתובת אמם, ויחלקו עם יורשי הראשונה בשאר מדין ירושת האב.","\u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים]\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 בן ננס\u0005]\u0006 \u0003סבר: אחת בחייו ואחת במותו יש להן כתובת בנין דכרין,\u0004 ולכן בני הראשונה יש להם תביעה מכוח כתובת בנין דכרין שכבר זכו בה בחייו. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא\u0005]\u0006 \u0003סבר: אחת בחייו ואחת במותו אין להן כתובת בנין דכרין.\u0004 ולכן בני השניה מקבלים חלקם בתורת כתובת אמם, ויחלקו איתם בני הראשונה בנותר מכוח ירושת האב.","\u0003אמר רבה: אשכחתינהו לרבנן דבי רב דיתבי וקאמרי\u0004 \u0005[מצאתי את החכמים מבית\u0006 מדרשו \u0005של רב שיושבים ואומרים]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אחת בחייו ואחת במותו יש להן כתובת בנין דכרין, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003כתובה נעשית מותר לחברתה\u0004 כשאין מותר דינר פרט לסכום הכתובות עצמן, שייחשב כירושה, \u0003והוא הדין\u0004 בענין \u0003בעל חוב\u0004 אם נשאר מהנכסים סכום עבור חוב שחייב המוריש, האם נעשה סכום זה כמותר לכתובה ומתקיים דין ירושה מן התורה, \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006","\u0003מר\u0004 \u0005[חכם זה,\u0006 בן ננס\u0005]\u0006 \u0003סבר: כתובה נעשית מותר לחברתה, והוא הדין לבעל חוב, ומר\u0004 \u0005[וחכם זה,\u0006 ר' עקיבא\u0005]\u0006 \u0003סבר: אין כתובה נעשית מותר לחברתה והוא הדין לבעל חוב,\u0004 ומאחר ופרט לכתובה אין כאן מותר דינר, לכן אינם זכאים לכתובת בנים דיכרין.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003בבעל חוב כולי עלמא לא פליגי דהוי\u0004 \u0005[הכל אינם חלוקים שהוא\u0006 נעשה\u0005]\u0006 \u0003מותר,\u0004 ואף שיש לו שעבוד, נחשב כמותר בירושה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003בכתובה,\u0004 אם היא נחשבת כמותר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, מה שנאמר \u0003\"ר' עקיבא אומר: כבר קפצה נחלה\",\u0004 והרי לא זה טעמו של דבר, אלא \u0003\"אם יש מותר דינר\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005],\u0006 שלשיטת פירוש זו שאלה זו היא נקודת המחלוקת!","\u0003אלא אמר רב יוסף: באחת בחייו ואחת במותו קא מיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים],\u0006 וכפי שהסברנו תחילה.","\u0003והני תנאי כי הני תנאי\u0004 \u0005[ותנאים אלה\u0006 שנחלקו בדבר הם \u0005כשיטת אלה התנאים\u0006 האחרים\u0005]\u0006 שחלקו בבעיה זו עצמה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נשא את הראשונה ומתה, נשא את השניה ומת הוא — באין בניה של זו\u0004 (ואנו מבינים — בניה של השניה) \u0003לאחר מיתה ונוטלין כתובת אמן\u0004 (\"כתובת בנין דכרין\"), והשאר חולקים בשווה. \u0003ר' שמעון אומר: אם יש מותר דינר — אלו נוטלין כתובת אמן ואלו נוטלין כתובת אמן, ואם לאו\u0004 \u0005לא —\u0006 \u0003חולקין בשוה.\u0004","\u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים]\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר: אחת בחייו ואחת במותו יש להן כתובת בנין דכרין, ומר\u0004 \u0005[וחכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר: אחת בחייו ואחת במותו אין להם כתובת בנין דכרין\u0004 אלא לבני השניה דווקא.","ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אחת בחייו ואחת במותו יש להן כתובת בנין דכרין,\u0004"],["\u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שווי \u0003דינר מקרקעי\u0004 \u0005[קרקעות]\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים];\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר:\u0004 אם יש מותר בשווי דינר של \u0003מקרקעי\u0004 \u0005[קרקעות]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 נוטלים שניהם כתובת אימם, אבל אם היה המותר \u0003מטלטלי\u0004 \u0005[מטלטלים]\u0006 — \u0003לא. ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר:\u0004 אם היה המותר \u0003אפילו מטלטלי\u0004 \u0005[מטלטלים]\u0006 הריהו נחשב לענין זה כמותר ונוטלים כתובת אימם.","ומקשים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה הבאה\u0005]:\u0006 \u0003ר' שמעון אומר: אפילו יש שם נכסים שאין להם אחריות\u0004 (מטלטלים) — \u0003אינן כלום, עד שיהא שם נכסים שיש להן אחריות\u0004 (קרקעות) ששוויים \u0003יתר על שתי כתובות דינר!\u0004","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 \u0003בדינר משעבדי קמיפלגי\u0004 \u0005[\u0006של נכסים \u0005משועבדים\u0006 הם \u0005חלוקים];\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר:\u0004 מותר דינר \u0003מבני חורין — אין\u0004 \u0005[כן],\u0006 הוא נחשב מותר, ואולם \u0003ממשעבדי\u0004 \u0005[ממשועבדים] —\u0006 \u0003לא, ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר: אפילו ממשעבדי\u0004 \u0005[ממשועבדים]\u0006 הריהו נחשב מותר.","ויש להקשות \u0003אי הכי\u0004 \u0005[אם כך],\u0006 הלשון ששנינו, \u0003ר' שמעון אומר: \"אם יש שם מותר דינר\"?!\u0004 הרי זו לשון לא מדוייקת, אלא \u0003\"כיון שיש שם מותר דינר\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005],\u0006 שמותר דינר נחשב בכל אופן שהוא מצוי!","\u0003אלא\u0004 יש לומר באופן אחר: \u0003בפחות מדינר קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר: דינר — אין\u0004 \u0005[כן]\u0006 נחשב כמותר, ואולם \u0003פחות מדינר — לא\u0004 נחשב כמותר, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון\u0005]\u0006 \u0003סבר: אפילו פחות מדינר\u0004 נחשב כמותר.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' שמעון \"\u0004אם יש שם מותר \u0003דינר\" קאמר\u0004 \u0005[אמר],\u0006 ומשמע ולא פחות! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003איפוך\u0004 \u0005[נהפוך\u0006 את הדעות\u0005],\u0006 מכל מקום ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003דמתניתין\u0004 \u0005[של המשנה\u0006 הבאה\u0005],\u0006 שהוא כפי הנראה גם תנא קמא של הברייתא, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003דינר קאמר\u0004 \u0005[אמר]!\u0006","\u0003אלא\u0004 צריך לפרש \u0003כי הנך תרי לישנאי קמאי ואיפוך\u0004 \u0005[כמו אותן שתי לשונות ראשונות\u0006 שהזכרנו למעלה בהסבר המחלוקת, או במותר מטלטלים או במשועבדים \u0005ולהפוך]\u0006 את הדעות.","\u0003אמר מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: הלכתא\u0004 \u0005[הלכה\u0006 פסוקה היא\u0005]:\u0006 \u0003אחת בחייו ואחת במותו — יש להן,\u0004 לבנים, \u0003כתובת בנין דכרין, ו\u0004עוד: \u0003כתובה נעשית מותר לחברתה.\u0004","על צירוף ההלכות האלה תוהים: \u0003בשלמא אי אשמעינן\u0004 \u0005[נניח אם\u0006 היה \u0005משמיע לנו]\u0006 רק כי \u0003אחת בחייו ואחת במותו יש להן כתובת בנין דיכרין, ולא אשמעינן\u0004 \u0005[\u0006היה \u0005משמיע לנו]\u0006 כי \u0003כתובה נעשית מותר לחברתה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003מותר דינר\u0004 נוסף לכתובות — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא — לא.\u0004","\u0003אלא לישמעינן\u0004 \u0005[שישמיע לנו]\u0006 רק כי \u0003כתובה נעשית מותר לחברתה, ואנא ידענא\u0004 \u0005[ואני יודע]\u0006 ומבין מכאן ש\u0003משום\u0004 כך \u0003אחת בחייו ואחת במותו יש להן כתובת בנין דכרין,\u0004 ואין צורך לומר זאת במפורש, שהרי ממילא אנו מבינים כך!","ומשיבים: \u0003אי אשמעינן הכי\u0004 \u0005[אם היה משמיע לנו\u0006 רק \u0005כך]\u0006 שכתובה נעשית מותר, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שזהו דווקא \u0003כגון שנשא שלש נשים, ומתו שתים בחייו, ואחת במותו. והך דמיית\u0004 \u0005[וזו שמתה]\u0006 \u0003לאחר\u0004 ה\u0003מיתה\u0004 שלו \u0003יולדת נקבה היא, ו\u0004בתה \u0003לאו בת ירושה היא,\u0004 ולכן אין לה תביעה לגבי הנכסים עצמם אלא למזונות בלבד. ואין כאן חשש לקטטה אלא דיון בין יורשי הכתובות.","\u0003אבל אחת בחייו ואחת במותו, והא\u0004 \u0005[וזו]\u0006 שמתה \u0003לאחר מיתה\u0004 של בעלה \u0003יולדת זכר היא\u0004 ובנה תובע גם הוא חלק בירושה \u0003אימא ליחוש לאינצויי\u0004 \u0005[אמור שנחשוש לקטטה],\u0006 שיתרעמו בני השניה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים.","\u0003מי שהיה נשוי שתי נשים, ומתו, ואחר כך מת הוא, ויתומים מבקשין כתובת אמן\u0004 (\"כתובת בנין דיכרין\") \u0003ואין שם\u0004 בנכסים \u0003אלא\u0004 כדי לשלם \u0003שתי כתובות\u0004 ולא יותר — במקרה זה מבטלים את דין כתובת בנין דיכרין, ו\u0003חולקין\u0004 הבנים \u0003בשוה\u0004 בנכסים, כדין ירושה מן התורה.","\u0003היה שם מותר דינר\u0004 בנכסים, נוסף לדמי הכתובות — \u0003אלו נוטלים כתובת אמן, ואלו נוטלים כתובת אמן,\u0004 ובשווה הדינר שנשאר — חולקים בשווה בין כולם.","\u0003אם אמרו\u0004 ה\u0003יתומים\u0004 שכתובת אמם גדולה משל חברתה: \u0003אנחנו מעלים על נכסי אבינו,\u0004 שאנו מקבלים עלינו את ערכם בסכום גדול יותר ממחירם בשוק, כדי שיהא ערכם נוסף על הכתוב בכתובות עוד \u0003יפה\u0004 (שווה) \u0003דינר כדי ש\u0004יהיה שם מותר דינר ו\u0003יטלו כתובת אמן — אין שומעין להן, אלא שמין\u0004 (מעריכים) \u0003את הנכסים בבית דין\u0004 ולפי זה קובעים.","\u0003היו שם נכסים בראוי\u0004 שלא היה בנכסים הקיימים מותר דינר, אבל היו שם נכסים הראויים (עתידים) ליפול להם בירושה ולהגדיל את סכום הירושה הכללי — \u0003אינן\u0004 נחשבים \u0003כבמוחזק\u0004 כעת בידיהם, ואין קובעים אלא לפי מצב הדברים באותה שעה.","\u0003ר' שמעון אומר: אפילו יש שם נכסים שאין להם אחריות\u0004 (כספים ומטלטלים), \u0003אינן כלום\u0004 לענין זה, \u0003עד שיהיו שם נכסים שיש להן אחריות\u0004 (כלומר, קרקעות) \u0003יותר על שתי הכתובות דינר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לזו\u0004 כתובה \u0003אלף, ולזו חמש מאות, אם יש שם מותר דינר, אלו,\u0004 יורשי אשה אחת, \u0003נוטלין כתובת אמן\u0004 (\"כתובת בנים דיכרין\"), \u0003ואלו\u0004 היורשים האחרים \u0003נוטלין כתובת אמן. ואם לאו — יחלקו בשוה.\u0004","כאן נשאלת שאלה שתחילה מקדימים לה מעין הקדמה, \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 שאם היו הנכסים \u0003מרובין\u0004 בשעת מיתה ובאותה שעה היה ערכם כדי שתי הכתובות ויתר דינר, \u0003ונתמעטו\u0004 לאחר זמן — \u0003כבר זכו בהן יורשין,\u0004 כל אחד בכתובת אמו, אף שכעת אין מותר דינר. ואולם אם היו \u0003מועטין ונתרבו מאי\u0004 \u0005[מה]\u0006 הדין? האם הולכים אחר זמן המיתה או אחר זמן החלוקה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממעשה שהיה: \u0003דניכסי דבי בר\u0004 \u0005[שנכסיו של בית בן]\u0006 \u0003צרצור מועטין ונתרבו הוו\u0004 \u0005[היו],\u0006 \u0003ואתו לקמיה\u0004 \u0005[ובאו\u0006 היורשים \u0005לפני]\u0006 \u0003רב עמרם\u0004 לדון בדבר. \u0003אמר להו\u0004 \u0005[להם]\u0006 ליורשי הכתובה הקטנה: \u0003זילו פייסינהו\u0004 \u0005[לכו פייסו אותם]\u0006 את יורשי הכתובה הגדולה ותנו להם משהו מחלקכם. \u0003לא אשגחו\u0004 \u0005[השגיחו]\u0006 בדבריו.","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא מפייסיתו להו\u0004 \u0005[תפייסו אותם]\u0006 \u0003מחינא לכו בסילוא דלא מבע דמא\u0004 \u0005[אכה אתכם בקוץ שאינו מוציא דם,\u0006 כלומר אטיל עליכם נידוי\u0005].\u0006 \u0003שדרינהו לקמיה\u0004 \u0005[שלח אותם לפני]\u0006 \u0003רב נחמן\u0004 שידון בדינם, \u0003אמר להן\u0004 רב נחמן: \u0003כשם שמרובין ונתמעטו\u0004"],["\u0003זכו בהן יורשין\u0004 — \u0003כך מועטין ונתרבו זכו בהן יורשין,\u0004 שהכל הולך לפי שעת המיתה, ואם כן מעיקר הדין צריכים לחלק את הנכסים בשווה.","\u0003(סימן: אלף ומאה מצוה בכתובה יעקב זקף שדותיו בדברים עסיקין)\u0004 והוא סימן להלכות הבאות, הקשורות במידה מסויימת לבעיה שבמשנה.","מסופר: \u0003ההוא גברא דהוו מסקי ביה אלפא זוזי\u0004 \u0005[אדם אחד שהיו נושים בו אלף זוז],\u0006 \u0003הוו ליה תרי אפדני\u0004 \u0005[היו לו שני ארמונות],\u0006 \u0003זבינהו חדא בחמש מאה וחדא בחמש מאה\u0004 \u0005[מכר אותם אחד בחמש מאות\u0006 זוז \u0005ואחד בחמש מאות\u0006 זוז\u0005].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003בעל\u0004 ה\u0003חוב\u0004 של המוכר \u0003טרפא לחדא מינייהו\u0004 \u0005[\u0006ו\u0005טרף את אחד מהם]\u0006 בחובו, \u0003הדר קטריף לאידך\u0004 \u0005[\u0006ו\u0005חזר\u0006 ורצה \u0005לטרוף את השני]\u0006 כדי להשלים את גביית חובו.","\u0003שקל\u0004 \u0005[לקח]\u0006 זה שקנה את הארמון \u0003אלפא זוזי\u0004 \u0005[אלף זוז]\u0006 \u0003וקא אזיל לגביה\u0004 \u0005[והלך אליו]\u0006 למלווה, \u0003אמר ליה: אי שויא\u0004 \u0005[אם שווה]\u0006 \u0003לך\u0004 הארמון הראשון שלקחת \u0003אלפא זוזי\u0004 \u0005[אלף זוזים] —\u0006 \u0003לחיי\u0004 \u0005[בסדר],\u0006 הרי הוא שלך תמורת כל הכסף, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — שקיל אלפא זוזי ואיסתלק\u0004 \u0005[קח\u0006 לך \u0005אלף זוזים\u0006 בכסף \u0005והסתלק]\u0006 משניהם והשאר לי את שני הארמונות.","\u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]\u0006 כי \u0003היינו מתניתין\u0004 \u0005[זו היא משנתנו]\u0006 ששנינו בה ש\u0003אם אמרו\u0004 ה\u0003יתומים,\u0004 יורשי הכתובה הגדולה: \u0003\"הרי אנו מעלין על נכסי אבינו יפה דינר\"\u0004 — אין שומעים להם. ואף כאן לא יכול המחזיק בבית להעריכו בסכום גבוה מערכו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מי דמי\u0004 \u0005[האם דומה הדבר]?\u0006 \u0003התם אית להו פסידא ליתמי\u0004 \u0005[שם\u0006 במשנתנו \u0005יש הפסד ליתומים]\u0006 האחרים שכתובת אמם יותר קטנה, אם יעריכו את הנכסים ביותר משווים, שכן אם יעריכו את הנכסים ביותר משוויים יהיה ממילא מותר דינר על סכום הכתובות, ורק בשל כך יוכלו בני בעלת הכתובה הגדולה ליטול כתובת בנים דיכרין, ואולם \u0003הכא מי אית ליה פסידא\u0004 \u0005[כאן האם יש לו הפסד]\u0006 למלווה? הלא \u0003אלפא יהיב ואלפא שקיל\u0004 \u0005[אלף\u0006 דינרים \u0005נתן ואלף לקח]\u0006 ולא הפסיד דבר, ובמקרה כזה מידת סדום היא אם לא ירצה לקבל את הכסף!","ושואלים: אם החליט הנושה להחזיק בארמון אחד ולוותר על שאר הכסף, \u0003וטירפא\u0004 \u0005[ו\u0006שטר \u0005הטריפה]\u0006 שכותבים ללוקח, \u0003בכמה כתבינן\u0004 \u0005[אנו כותבים]?\u0006 שאמנם הלוקח שילם בעד הארמון חמש מאות דינרים, אבל המוכר הלא הרויח על ידי כך אלף דינרים שהרי סילק על ידי כך את חובו. וכאשר בא הלוקח לבית דין לקבל אישור שטרפו ממש את הנכס, ויחזור למוכר הראשון לתבוע ממנו, מה יתבע?","\u0003רבינא אמר: באלפא\u0004 \u0005[באלף]\u0006 כותבים, שהרי אלף דינר היה סכום החוב. \u0003רב עוירא אמר: בחמש מאה\u0004 (מאות), שהרי הוא לא קנה אלא בחמש מאות, ומה שויתר הנושה — מדעת עצמו הוסיף. ומסכמים \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003בחמש מאה\u0004 (מאות)","כותבים. וכן מסופר: \u0003ההוא גברא דהוו מסקי ביה\u0004 \u0005[אדם אחד שהיו נושים בו]\u0006 \u0003מאה זוזי\u0004 \u0005[זוזים],\u0006 \u0003הוו ליה תרי קטיני דארעא\u0004 \u0005[היו לו שתי\u0006 חלקות \u0005אדמה קטנות],\u0006 \u0003חד זבינהו בחמשין וחד בחמשין\u0004 \u0005[אחת מכר בחמישים\u0006 זוז \u0005ואחת בחמישים\u0006 זוז\u0005].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003בעל\u0004 ה\u0003חוב טרפא לחד מינייהו\u0004 \u0005[\u0006ו\u0005טרף את אחת מהן].\u0006 \u0003הדר אתא וקטריף לאידך\u0004 \u0005[חזר בא ו\u0006רצה \u0005לטרוף את האחרת].\u0006","\u0003שקל\u0004 \u0005[לקח]\u0006 קונה השדה \u0003מאה זוזי\u0004 \u0005[זוזים]\u0006 \u0003וקאזיל לגביה\u0004 \u0005[והלך אליו]\u0006 אל בעל החוב \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי שויא\u0004 \u0005[אם שווה]\u0006 \u0003לך\u0004 שדה זה \u0003מאה זוזי\u0004 \u0005[זוזים] —\u0006 \u0003לחיי\u0004 \u0005[בסדר],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — שקול\u0004 \u0005[קח]\u0006 \u0003מאה זוזי\u0004 \u0005[זוזים]\u0006 \u0003ואיסתלק\u0004 \u0005[והסתלק].\u0006","\u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב יוסף למימר\u0004 \u0005[לומר]\u0006 כי \u0003היינו מתניתין\u0004 \u0005[זוהי\u0006 ההלכה האמורה ב\u0005משנתנו],\u0006 ששנינו בה: \u0003אם אמרו יתומים\u0004 שרוצים להעלות את מחיר הנכסים — אין שומעים להם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם אית להו פסידא ליתמי\u0004 \u0005[שם יש להם הפסד ליתומים],\u0006 ואולם \u0003הכא מאי פסידא אית ליה\u0004 \u0005[כאן,\u0006 \u0005איזה הפסד יש לו\u0006 למלווה\u0005]?\u0006 הלא \u0003מאה\u0004 דינרים \u0003יהיב\u0004 \u0005[נתן]\u0006 ו\u0003מאה שקיל\u0004 \u0005[לקח],\u0006 ושואלים:","\u0003וטירפא\u0004 \u0005[ו\u0006את שטר ה\u0005טריפה]\u0006 \u0003בכמה כתבינן\u0004 \u0005[אנחנו כותבים]?\u0006 \u0003רבינא אמר\u0004 לשיטתו: \u0003במאה, רב עוירא אמר: בחמשין\u0004 \u0005[בחמישים].\u0006 ומסכמים, \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0005[בחמישים].\u0006","ועוד: \u0003ההוא גברא דהוו מסקי ביה\u0004 \u0005[אדם אחד שהיו נושים בו]\u0006 \u0003מאה זוזי\u0004 \u0005[זוזים].\u0006 \u0003שכיב, שבק קטינא דארעא דהוה שויא חמשין זוזי\u0004 \u0005[מת\u0006 ו\u0005הניח\u0006 חלקת \u0005אדמה קטנה שהיתה שווה חמישים זוזים].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003בעל\u0004 ה\u0003חוב וקטריף ליה\u0004 \u0005[וטרף אותה],\u0006 \u0003אזול יתמי יהבו ליה חמשין זוזי\u0004 \u0005[הלכו היתומים\u0006 ו\u0005נתנו לו חמישים זוז]\u0006 ופדו ממנו את השדה, \u0003הדר קטריף לה\u0004 \u0005[חזר\u0006 ו\u0005טרף אותה],\u0006 כדי לגבות את שאר חובו.","\u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003אביי\u0004 להתלונן. \u0003אמר להן\u0004 \u0005[להם]:\u0006 \u0003מצוה על היתומים לפרוע חוב אביהן\u0004 מן הנכסים שירשו ממנו, ואם כן \u0003הני קמאי\u0004 \u0005[אותם\u0006 כספים \u0005הראשונים]\u0006 שנתתם בפרעון החוב \u0003מצוה עבדיתו\u0004 \u0005[עשיתם],\u0006 שפרעתם מקצת חוב אביכם, אבל בשל כך לא בטל השעבוד, ולכן \u0003השתא כי טריף\u0004 \u0005[עכשיו ש\u0006הוא \u0005טורף],\u0006 \u0003בדין קטריף\u0004 \u0005[\u0006הוא \u0005טורף],\u0006 שהרי יש לו שעבוד על הקרקע.","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה אלא כש\u0003לא אמרו ליה\u0004 \u0005[לו]\u0006 היתומים \u0003\"הני חמשין זוזי דמי דארעא קטינא\u0004 \u0005[חמישים זוז אלה\u0006 הם \u0005דמי\u0006 חלקת \u0005האדמה הקטנה]\u0006 \u0003\",\u0004 שאז הוא כמכירה גמורה ולא כפרעון חוב, \u0003אבל\u0004 אם \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003\"הני חמשין זוזי דמי ארעא קטינא\u0004 \u0005[חמישים הזוז הללו,\u0006 הם \u0005דמי\u0006 חלקת \u0005האדמה הקטנה\u0006 הם\u0005]\u0006 \u0003\"\u0004\u0005—\u0006 \u0003סלוקי סלקוה\u0004 \u0005[סלקו אותו]\u0006 על ידי כך מכל תביעה לחלקה זו.","ועוד מסופר: \u0003ההוא גברא דזבנה לכתובתה דאימיה\u0004 \u0005[אדם אחד שמכר את כתובת אמו]\u0006 \u0003בטובת הנאה,\u0004 שקיבל סכום מסויים על מנת שאם יירש הוא את הכתובה (שימות אביו תחילה ואחר כך אמו) — יעביר את זכות הכתובה לקונה. \u0003ואמר ליה\u0004 \u0005[לו]\u0006 האיש לקונה: \u0003אי אתיא אם ומערערא\u0004 \u0005[אם תבוא אמי ותערער\u0006 על המכירה\u0005],\u0006 שלא תסכים למכירה זו, \u0003לא מפצינא לך\u0004 \u0005[אפצה אותך],\u0006 כלומר, איני אחראי על שטר מכירה זה ולא תקבל את מעותיך בחזרה.","\u0003שכיבא אימיה\u0004 \u0005[מתה אמו]\u0006 \u0003ולא איערערא\u0004 \u0005[ערערה],\u0006 \u0003ואתא איהו וקא מערער\u0004 \u0005[ובא הוא\u0006 עצמו \u0005וערער]\u0006 על המכירה, שאמר שהוא עומד במקום אמו והריהו נוטל את הקרקע וכיון שהקונה קנה קרקע זו שלא באחריות, אף אינו צריך לשלם לו. \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]\u0006 כי \u0003איהו\u0004 \u0005[הוא]\u0006 \u0003במקום אימיה קאי\u0004 \u0005[אמו\u0006 הוא \u0005עומד],\u0006 וכיון שהוא בא במקומה ותנאי היה במכירה זו שהיא תוכל לערער — הרי אף הוא רשאי לערער. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: נהי\u0004 \u0005[אם אמנם]\u0006 שאת ה\u0003אחריות\u0004 לערעור \u0003דידה\u0004 \u0005[שלה]\u0006 \u0003לא קביל עליה\u0004 \u0005[קיבל עליו],\u0006 מכל מקום את ה\u0003אחריות דידיה מי\u0004 \u0005[של עצמו, האם]\u0006 \u0003לא קביל\u0004 \u0005[קיבל]?\u0006 וכאשר מכר, ודאי סילק עצמו מלערער על המכירה.","ובענין דומה \u0003אמר רמי בר חמא: ראובן שמכר שדה לשמעון שלא באחריות,\u0004 כלומר, שאם יטרפוה מן הקונה לא יקבל מעותיו בחזרה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003שמעון ומכרה לראובן\u0004 בחזרה, אבל מכרה \u0003באחריות,\u0004"],["\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003בעל\u0004 ה\u0003חוב\u0004 של \u0003ראובן וקטריף ליה מיניה\u0004 \u0005[וטרף אותה ממנו,\u0006 מראובן\u0005]\u0006 — \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דאזיל\u0004 \u0005[שילך]\u0006 \u0003שמעון ומפצי ליה\u0004 \u0005[ויפצה אותו],\u0006 יחזיר לו את דמי המכירה, שהרי מכר לו את השדה באחריות, וראובן אינו חייב לשמעון ולא כלום, שהרי מכר לו את השדה שלא באחריות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: נהי\u0004 \u0005[אם אמנם]\u0006 שאת ה\u0003אחריות דעלמא קביל עליה\u0004 \u0005[של העולם,\u0006 של אחרים, \u0005קיבל עליו],\u0006 שאם יטרפו את השדה מראובן בשל חובות שמעון, קיבל על עצמו שמעון אחריות, ואולם \u0003אחריות דנפשיה מי קביל עליה\u0004 \u0005[של עצמו האם קיבל עליו]\u0006 לפצות את הלוקח על חובות שחב הוא עצמו לאחרים ובשל כך טרפו ממנו את השדה?","ומעירים: \u0003ומודה רבא\u0004 לרמי בר חמא \u0003בראובן שירש שדה מיעקב\u0004 אביו, \u0003ומכרה לשמעון שלא באחריות, ואתא\u0004 \u0005[ובא]\u0006 \u0003שמעון ומכרה לראובן\u0004 בחזרה \u0003באחריות, ואתא\u0004 \u0005[ובא]\u0006 \u0003בעל\u0004 ה\u0003חוב\u0004 של \u0003יעקב,\u0004 האב, \u0003וקטריף ליה מיניה\u0004 \u0005[וטרף אותה ממנו]\u0006 — אז \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דאזיל\u0004 \u0005[שילך]\u0006 \u0003שמעון ומפצי ליה מיניה\u0004 \u0005[ויפצה אותו ממנו].\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003בעל\u0004 ה\u0003חוב\u0004 של \u0003יעקב כבעל חוב דעלמא דמי\u0004 \u0005[סתם\u0006 הוא \u0005נחשב],\u0006 שאפילו לשיטת רבא, שאדם מקבל על עצמו בכל מקרה את האחריות על חובות עצמו, מכל מקום על חובותיו של האב ודאי לא קיבל עליו אחריות.","\u0003אמר רמי בר חמא: ראובן שמכר שדה לשמעון באחריות\u0004 ולא שילם שמעון \u0003וזקף עליו\u0004 ראובן את דמי השדה \u0003במלוה,\u0004 שכתב לו שמעון עליהם שטר חוב, \u0003ומת ראובן ואתא\u0004 \u0005[ובא]\u0006 \u0003בעל\u0004 ה\u0003חוב\u0004 של \u0003ראובן וקטריף לה\u0004 \u0005[וטרף אותה]\u0006 \u0003משמעון ופייסיה בזוזי\u0004 \u0005[ופייס אותו\u0006 שמעון \u0005בכסף],\u0006 כדי שלא יטרוף ממנו את השדה — לכשיבואו בני ראובן לתבוע ממנו את חוב אביהם,","\u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דאמרי ליה\u0004 \u0005[שאומרים לו]\u0006 \u0003בני ראובן\u0004 לשמעון: \u0003אנן מטלטלי שבק אבון גבך\u0004 \u0005[אנחנו מטלטלים הניח אבינו אצלך],\u0006 שהרי נשארת חייב לו כסף, \u0003ומטלטלי דיתמי\u0004 \u0005[ומטלטלים של יתומים]\u0006 \u0003לבעל חוב לא משתעבדי\u0004 \u0005[משתעבדים],\u0006 ואם כן כסף זה אי אפשר ליטלו מאיתנו, ותביעתנו שתתן לנו את הכסף שהיית חייב לאבינו במלואו. שאף שהיה שמעון צריך לשלם עבור השדה תשלום נוסף — דבר זה אינו מעניינם, משום ששדה זה כבר אינו שלהם.","\u0003אמר רבא: אי\u0004 \u0005[אם]\u0006 \u0003פקח\u0004 הוא \u0003אידך\u0004 \u0005[האחר,\u0006 שמעון\u0005],\u0006 \u0003מגבי להו ניהלייהו ארעא\u0004 \u0005[מגבה להם\u0006 בחוב זה \u0005קרקע]\u0006 \u0003והדר גבי לה מינייהו\u0004 \u0005[ואחר כך גובה אותה מהם]\u0006 בשל האחריות של המכירה, ו\u0003כ\u0004דברי \u0003רב נחמן.\u0004 ש\u0003אמר רב נחמן אמר רבה בר אבוה: יתומים שגבו קרקע בחובת אביהן — בעל חוב חוזר וגובה אותה מהן\u0004, כאילו נפלה להם בירושה.","ועוד בענין דומה, \u0003אמר רבה: ראובן שמכר כל שדותיו לשמעון, וחזר שמעון ומכר שדה אחת\u0004 משדות אלה \u0003ללוי, ואתא\u0004 \u0005[ובא]\u0006 \u0003בעל\u0004 ה\u0003חוב\u0004 של \u0003ראובן\u0004 לטרוף שדה שהיה משועבד לו — \u0003רצה מזה\u0004 משמעון \u0003גובה, רצה מזה\u0004 מלוי \u0003גובה,\u0004 שהרי שעבוד אחד יש לו על כל השדות כולם שהיו פעם של ראובן.","\u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא דזבנה\u0004 \u0005[שמכר אותה]\u0006 שמעון ללוי שדה שהיא \u0003בינונית, אבל\u0004 אם \u0003זבנה\u0004 \u0005[מכר אותה]\u0006 \u0003עידית\u0004 (משובחת) או \u0003זבורית\u0004 (גרועה) והותיר שדה בינונית אצל שמעון, \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 לוי למלווה: \u0003להכי טרחי וזביני ארעא דלא חזיא\u0004 \u0005[לכך טרחתי וקניתי קרקע שאינה ראויה]\u0006 \u0003לך\u0004 שבעל חוב נוטל לכתחילה מבינונית, ואם כן לך אל שמעון וגבה מן הבינונית.","ומעירים: \u0003ו\u0004גם אם קנה לוי משמעון \u0003בינונית נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שיכול בעל החוב לטרוף מלוי, \u0003אלא\u0004 כש\u0003לא שבק\u0004 \u0005[הניח]\u0006 לוי לשמעון \u0003בינונית דכוותה\u0004 \u0005[שכמותה],\u0006 בין השדות שנשארו אצלו, שאז יכול המלווה לטרוף גם מלוי,"],["\u0003אבל\u0004 אם \u0003שבק\u0004 \u0005[הניח]\u0006 \u0003בינונית דכוותה\u0004 \u0005[שכמותה]\u0006 אצל שמעון, \u0003מצי אמר ליה\u0004 \u0005[יכול\u0006 לוי \u0005לומר לו]\u0006 למלווה: \u0003הנחתי לך מקום לגבות הימנו,\u0004 ולך וגבה משמעון.","\u0003אמר אביי: ראובן שמכר שדה לשמעון באחריות,\u0004 שאם יטרפוה ממנו בשל חובות ראובן, יקבל שמעון מעותיו בחזרה, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003בעל\u0004 ה\u0003חוב\u0004 של \u0003ראובן וקטריף לה מיניה\u0004 \u0005[וטרף אותה,\u0006 את השדה, \u0005ממנו,\u0006 משמעון\u0005],\u0006 \u0003דינא\u0004 \u0005[דין]\u0006 \u0003הוא דאזיל\u0004 \u0005[שילך]\u0006 \u0003ראובן ומפצי ליה\u0004 \u0005[ויפצה אותו]\u0006 את המלווה בדרך כלשהי, ובכך תחזור הקרקע לידי שמעון. \u0003ולא מצי אמר ליה\u0004 \u0005[יכול\u0006 המלווה \u0005לומר לו]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בעל דברים דידי את\u0004 \u0005[שלי אתה],\u0006 שאני טרפתי את השדה משמעון שהוא עכשיו בעל השדה, ואתה אם יש לך עסקים עם שמעון — לך אתה ודון איתו, אבל אני איני רוצה לדון בדברים איתך. והטעם — \u0003משום דאמר ליה\u0004 \u0005[\u0006שיכול ראובן \u0005לומר לו\u0006 למלווה\u0005]:\u0006 \u0003דמפקת מיניה, עלי הדר\u0004 \u0005[\u0006מה \u0005שאתה מוציא ממנו, חוזר עלי],\u0006 שקיבלתי עלי אחריות, וכיון שהחוב חוזר עלי, אין אתה יכול לומר שאין הדבר מענייני.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אפילו\u0004 מכר ראובן לשמעון את השדה \u0003שלא באחריות נמי\u0004 \u0005[גם כן]\u0006 יכול ראובן להכנס בענין, ולנסות לסלק את המלווה מן הקרקע. ומדוע? \u0003דאמר ליה\u0004 \u0005[ש\u0006יכול הוא \u0005לומר לו]:\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דתהוי ליה\u0004 \u0005[שתהיה לו]\u0006 \u0003לשמעון תרעומת עלי\u0004 על שמכרתי לו שדה שהיתה משועבדת לבעל חוב.","ועוד \u0003אמר אביי: ראובן שמכר שדה לשמעון שלא באחריות, ויצאו עליו,\u0004 על השדה הזה,"],["\u0003עסיקין,\u0004 כלומר, עוררים על בעלות השדה אם היה זה \u0003עד שלא החזיק בה\u0004 הקונה — \u0003יכול לחזור בו\u0004 מן הקניה, ואם \u0003משהחזיק בה — אינו יכול לחזור בו. משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל השדה, המוכר: \u0003חייתא דקיטרי סברת וקבילת\u0004 \u0005[סל\u0006 מלא \u0005קשרים סברת וקיבלת],\u0006 שכיון שקנית שדה שלא באחריות, יכול היית להבין שיש בעיות במכירת שדה זה. ושואלים: \u0003ומאימת\u0004 (ממתי) \u0003מחזיק בה?\u0004 מתי נקבע זמן ההחזקה? ומשיבים: \u0003מכי דייש אמצרי\u0004 \u0005[מ\u0006זמן \u0005ש\u0006הוא \u0005עובר על מיצרי\u0006 השדה\u0005]\u0006 כדי לבודקו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אפילו\u0004 כאשר מכר לו \u0003באחריות נמי\u0004 \u0005[גם כן]\u0006 אין המכירה מתבטלת מיד כשמצא שיש עוררים. וטעם הדבר — \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המוכר לקונה: \u0003אחוי טירפך\u0004 \u0005[הראה\u0006 את שטר ה\u0005טריפה שלך]\u0006 \u0003ואשלם לך,\u0004 וכל עוד לא נטלו ממך את השדה, לא נגמר הדין ואינך יכול לתבוע את דמיו, שאין זה בטוח כלל שיקרה הדבר.","\u0003מי שהיה נשוי שלש נשים, ומת,\u0004 ו\u0003כתובתה של זו מנה\u0004 (מאה דינרים), \u0003ושל זו מאתים, ושל זו שלש מאות,\u0004 והזמן של כתובת כולן שווה, שאין זכות קדימה לאחת מהן, \u0003ואין שם\u0004 בירושה \u0003אלא מנה\u0004 אחד — \u0003חולקין\u0004 בין כל הנשים את המנה \u0003בשוה,\u0004 כיון שלשלושתן זכות שווה באותו מנה, שהרי לכל אחת מהן הוא חייב לפחות מנה.","\u0003היו שם\u0004 בירושה \u0003מאתים\u0004 דינר, זו שהיתה לה כתובה \u0003של מנה — נוטלת חמשים,\u0004 ואלו שהיו להן \u0003של מאתים ושל שלש מאות\u0004 נוטלות \u0003שלשה שלשה של זהב,\u0004 כלומר, כל אחת מהן מקבלת שלושה דינרי זהב, שהם שבעים וחמישה דינרי כסף. \u0003היו שם שלש מאות\u0004 דינר — זו \u0003של מנה נוטלת חמשים, ושל מאתים\u0004 נוטלת \u0003מנה, ושל שלש מאות\u0004 נוטלת \u0003ששה של זהב\u0004 שהם מאה וחמישים דינר.","\u0003וכן שלשה שהטילו לכיס,\u0004 כלומר, עשו שותפות בעסק בחלקים לא שווים, \u0003פיחתו או הותירו\u0004 ובאים אחר כך להתחלק בנותר — \u0003כך הן חולקין\u0004 לפי היחס בין הכספים שהכניסו לשותפות.","על ההלכה במשנה, שאם היו שם נכסים בשווי של מאתים הרי זו שהיתה לה כתובה מנה נוטלת חמישים דינר, שואלים: \u0003של מנה נוטלת חמשים,\u0004 מדוע? \u0003תלתין ותלתא ותילתא\u0004 \u0005[שלושים ושלוש ושליש]\u0006 \u0003הוא דאית\u0004 \u0005[שיש]\u0006 \u0003לה!\u0004 שהרי כל התביעה שלה היא רק לגבי המנה הראשון, ולגבי מנה זה יש לכולן זכות שווה, ואם כן היו צריכות להתחלק בשווה במנה הראשון!","\u0003אמר שמואל:\u0004 מדובר כאן \u0003בכותבת בעלת מאתים לבעלת\u0004 ה\u0003מנה: \"דין ודברים אין לי עמך במנה\".\u0004 וכיון שהיא ויתרה על חלקה, נמצא שיש רק שתי תובעות למנה זה, בעלת המנה ובעלת השלוש מאות, והן מתחלקות בשווה במנה זה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה,\u0006 המשכה של המשנה\u0005]:\u0006 \u0003של מאתים ושל שלש מאות\u0004 נוטלות \u0003שלש שלש\u0004 דינרים \u0003של זהב.\u0004 ומדוע? \u0003תימא\u0004 \u0005[תאמר]\u0006 \u0003לה\u0004 זו של שלוש מאות לבעלת המאתים: \u0003הא סלקת נפשך מינה\u0004 \u0005[הרי סילקת\u0006 את \u0005עצמך ממנה]\u0006 מן המנה האחד, ואם כן יש לך תביעה רק לגבי המנה הנותר, שהרי מן המנה הראשון מקבלת רק בעלת שלוש מאות, ואם כן היה צריך להיות שבעלת שלוש מאות תקבל מנה (חמישים ממנה ראשון וחמישים ממנה שני) ובעלת מאתים תקבל רק חמישים (חצי ממנה שני)!","ומשיבים: \u0003משום דאמרה\u0004 \u0005[שאומרת]\u0006 \u0003לה\u0004 בעלת מאתים: \u0003מדין ודברים הוא דסליקי נפשאי\u0004 \u0005[שסילקתי\u0006 את \u0005עצמי],\u0006 שלא ויתרתי לגמרי על זכותי במנה הראשון, אלא שהסכמתי שלא להתדיין עם בעלת הכתובה בת המנה, אבל כאשר אני באה לדון איתך, יש לי עדיין זכות במנה ראשון, ולכן יש לשתי הנשים זכות שווה לגבי מאה וחמישים דינר, והן מתחלקות בהם.","שנינו במשנה: אם \u0003היו שם שלש מאות\u0004 — מתחלקים באופן שבעלת מנה מקבלת חמישים, ושל מאתים מקבלת מנה, ושל שלוש מאות מקבלת מאה וחמישים דינר.","ושואלים: מדוע זו \u0003של מאתים\u0004 מקבלת \u0003מנה?\u0004 הלא רק \u0003שבעים וחמשה הוא דאית\u0004 \u0005[שיש]\u0006 \u0003לה,\u0004 שכפי שביאר שמואל למעלה ויתרה בעלת המאתים על התדיינות במנה ראשון, נמצא שיש לה רק תביעה לגבי חלקה במאה וחמישים דינרים, שאין לה זכות במנה שלישי כלל, וצריכה לקבל רק מחצית מסכום תביעתה שהוא שבעים וחמישה דינרים בלבד!","ומשיבים, \u0003אמר שמואל:\u0004 הסיפא מדברת \u0003בכותבת בעלת שלש מאות לבעלת מאתים ולבעלת מנה: \"דין ודברים אין לי עמכם במנה\u0004 ראשון","\u0003\",\u0004 ומשום כך במנה ראשון מתחלקות בעלת מאה ובעלת מאתים, וכל אחת מהן מקבלת חמישים דינרים. ובמנה שני מתחלקות בעלת מאתים ובעלת שלוש מאות, ונמצא שיש לבעלת מאתים מנה שלם. ומנה שלישי הוא לבעלת שלוש מאות בלבד, ונמצא שמקבלת חצי ממנה שני וכל מנה שלישי. \u0003רב יעקב מנהר פקוד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבינא אמר:\u0004 אין מדובר במשנתנו במקרה שאחת מהן ויתרה, אלא כאשר הרכוש לא הגיע לידן בבת אחת, ובכל פעם תפסו הנשים חלק מן הרכוש. ו\u0003רישא\u0004 \u0005[תחילתה]\u0006 מדובר \u0003בשתי תפיסות, וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בשתי תפיסות.\u0004 כיצד?","\u0003רישא\u0004 \u0005[תחילתה]\u0006 של המשנה מדברת באופן שהיו שם מאתים — הרי זה מדובר \u0003בשתי תפיסות;\u0004 ש\u0003נפלו שבעין\u0004 \u0005[שבעים]\u0006 \u0003וחמשה\u0004 דינר \u0003בחד זימנא\u0004 \u0005[בפעם אחת]\u0006 \u0003ומאה ועשרים וחמשה\u0004 דינר \u0003בחד זימנא\u0004 \u0005[בפעם אחת],\u0006 ולכן בפעם הראשונה כשהיתה לכולן תביעה שווה לסכום זה, לכך התחלקו שלוש הנשים בכסף וכל אחת קיבלה עשרים וחמישה דינרים. ובפעם השניה יש לבעלת המנה תביעה רק לגבי שליש משבעים וחמישה דינרים (להשלמת המנה שלה) והיא מקבלת את חלקה.","ובחמישים שנותרו יש תביעה שווה לשתי הנשים האחרות והן מתחלקות בהם, כך שכל אחת מהן מקבלת שבעים וחמישה דינרים (שליש משבעים וחמישה ראשונים, ושליש משבעים וחמישה שניים, וחצי מחמישים) ואילו \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר גם כן \u0003בשתי תפיסות;\u0004 ש\u0003נפלו שבעים וחמשה\u0004 דינר \u0003בחד זימנא\u0004 \u0005[בפעם אחת],\u0006 \u0003ומאתים ועשרים וחמשה\u0004 דינר \u0003בחד זימנא\u0004 \u0005[בפעם אחת].\u0006 ואם כן, בסכום שבתפיסה ראשונה היתה זכות שווה לכל הנשים, וכל אחת מקבלת עשרים וחמישה. ולגבי תפיסה שניה יש לכולן תביעה שווה רק לגבי שבעים וחמישה דינרים, ובהם כולן מתחלקות. נמצא שלראשונה יש בסך הכל חמישים (עשרים וחמישה מתפיסה ראשונה, ועשרים וחמישה מתפיסה שניה). ואילו בעלת כתובה שניה יש לה תביעה רק על מאה שבעים וחמישה דינרים להשלמת המאתים (שהרי קיבלה כבר עשרים וחמישה בתפיסה ראשונה), אבל לגבי החמישים הנוספים אין לה תביעה, ואם כן, בשבעים וחמישה מתחלקים שלושתן, ובמנה שנשאר מתחלקות בעלת מאתים ובעלת שלוש מאות, ונמצא שיש לבעלת המאתים עשרים וחמישה מתפיסה ראשונה ועשרים וחמישה מתפיסה שניה ועוד חמישים, ולבעלת שלוש מאות עשרים וחמישה מתפיסה הראשונה, ועשרים וחמישה מתפיסה שניה, חמישים שהתחלקה עם בעלת מאתים ועוד חמישים שלגביהם לא היתה לאחרות כל תביעה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 שיטה \u0003זו\u0004 שבמשנתנו, היא \u0003משנת ר' נתן.\u0004 ואילו \u0003רבי אומר: אין אני רואה דבריו של ר' נתן באלו, אלא\u0004 לדעתו \u0003חולקות בשוה.\u0004","שנינו במשנה: \u0003וכן שלשה שהטילו\u0004 לכיס. באופן זה הם חולקים. \u0003אמר שמואל: שנים שהטילו לכיס\u0004 לעשות עסק בשותפות, \u0003זה\u0004 הכניס \u0003מנה, וזה מאתים\u0004 —"],["\u0003השכר לאמצע,\u0004 כלומר, חולקים את הרווחים בשווה.","\u0003אמר רבה: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003שמואל ב\u0004קנו \u0003שור לחרישה ועומד\u0004 השור \u0003לחרישה,\u0004 והם באים להתחלק בשכר שמקבלים עבור עבודת השור, שכיון שאין השור מתקיים ומביא רווחים אלא בצירוף החלקים של כולם, אין לומר שחלקו של אחד שווה פחות. \u0003אבל\u0004 אם נשתתפו \u0003בשור לחרישה, ועומד\u0004 כעת \u0003לטביחה\u0004 ובאים להתחלק במה שקיבלו עבור בשרו — \u0003זה נוטל לפי מעותיו, וזה נוטל לפי מעותיו. ורב המנונא אמר: אפילו\u0004 אם נשתתפו ב\u0003שור לחרישה ועומד לטביחה — השכר לאמצע.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בתוספתא: \u0003שנים שהטילו לכיס, זה מנה וזה מאתים — השכר לאמצע.\u0004 וכיון שנאמר הדבר כדין כללי, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר גם \u0003ב\u0004אופן שקנו \u0003שור לחרישה ועומד לטביחה, ו\u0004אם כן תהא זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003רבה!\u0004 ודוחים \u0003לא,\u0004 מדובר שם \u0003בשור לחרישה ועומד לחרישה.\u0004","ושואלים: \u0003אבל\u0004 לפי זה, אם נשתתפו ב\u0003שור לחרישה ועומד לטביחה מאי\u0004 \u0005[מה]\u0006 יהא הדין — \u0003זה נוטל לפי מעותיו, וזה נוטל לפי מעותיו.\u0004 אם כן, \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה\u0006 של אותה ברייתא\u0005]:\u0006 \u0003לקח זה בשלו וזה בשלו,\u0004 שכל אחד מהם קנה סחורה בפני עצמו \u0003ונתערבו,\u0004 שכל אחד הביא את סחורתו ונשתתפו בכל — הרי \u0003זה נוטל לפי מעותיו, וזה נוטל לפי מעותיו.\u0004","ואם היה הדין כדברי רבה, במקום לדון ולחלק בנושא אחר \u0003ליפלוג וליתני בדידיה\u0004 \u0005[שיחלק וישנה בו עצמו]:\u0006 \u0003במה דברים אמורים —\u0004 בשנשתתפו \u0003בשור לחרישה ועומד לחרישה, אבל\u0004 אם נשתתפו \u0003בשור לחרישה ועומד לטביחה — זה נוטל לפי מעותיו וזה נוטל לפי מעותיו!\u0004","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כלומר, כך צריך להבין את הדברים: \u0003במה דברים אמורים — בשור לחרישה ועומד לחרישה, אבל בשור לחרישה ועומד לטביחה — נעשה כמי שלקח זה בשלו וזה בשלו ונתערבו, זה נוטל לפי מעותיו וזה נוטל לפי מעותיו.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וכן שלשה שהטילו לכיס, פחתו או הותירו — כך הן חולקין,\u0004 כל אחד לפי השקעתו בשותפות","\u0003. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003\"פחתו\" — פחתו ממש,\u0004 שהפסידו כסף בעסקה, \u0003\"הותירו\" — הותירו ממש,\u0004 ונאמר שהם מתחלקים לפי מעותיהם ולא בשווה, וקשה מכאן לדברי שמואל שאמר שחולקים בשווה!","\u0003אמר רב נחמן אמר רבה בר אבוה: לא, \"הותירו\"\u0004 כוונתו ל\u0003זוזי חדתי\u0004 \u0005[מעות חדשות],\u0006 שתוך כדי המסחר קיבלו מטבעות משובחים יותר, שערך הכספים עצמם עלה, ו\u0003\"פחתו\" כוונתו שקיבלו אסתירא דצוניתא\u0004 \u0005[מטבע של מכה],\u0006 כלומר, שנמצאו בידם בשעת חלוקה מטבעות ישנים וחלודים שאינם יוצאים לפי ערכם ומשמשים כמתכת בלבד, וכשמתחלקים בכספים עצמם (ולא ברווח) הם מתחלקים לפי הכסף שהכניסו.","\u0003מי שהיה נשוי ארבע נשים, ומת\u0004 — זו שנישאה \u0003ראשונה קודמת לשניה\u0004 בתביעת הכתובה, \u0003ושניה לשלישית, ושלישית לרביעית. וראשונה נשבעת לשניה\u0004 שלא נטלה כלום מנכסי הבעל שלא כדין. \u0003ושניה\u0004 נשבעת \u0003לשלישית, ושלישית לרביעית, והרביעית נפרעת\u0004 את חלקה ומקבלת \u0003בלא שבועה. בן ננס אומר: וכי מפני שהיא אחרונה\u0004 תהא \u0003נשכרת?\u0004 והרי אף היא נפרעת מנכסי יתומים, וכלל הוא שאין נפרעים מנכסי יתומים אלא בשבועה! אלא אמור: \u0003אף היא לא תפרע אלא בשבועה.\u0004 עד כאן דיברנו במקרה שנשא נשים זו אחר זו והיו הכתובות מסודרות לפי תאריכים שונים.","אולם אם \u0003היו יוצאות\u0004 כל הכתובות \u0003כולן ביום אחד — כל הקודמת לחברתה אפילו שעה אחת זכתה. וכך היו כותבין בירושלים שעות\u0004 בשטרות, כדי להוכיח על ידי כך איזה שטר קדם. \u0003היו כולן יוצאות בשעה אחת, ואין שם אלא מנה — חולקות\u0004 כולן \u0003בשוה.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה חלוקים],\u0006 באיזה נושא עקרוני חולקים תנא קמא ובן ננס? \u0003אמר שמואל:\u0004"],["\u0003כגון שנמצאת אחת מהן\u0004 מן השדות שהיו רכושו של הבעל \u0003שדה שאינה שלו,\u0004 וכגון שגזלה מאחר ונמצא שאותה אשה שקיבלה שדה זה עבור כתובתה תצטרך להחזיר את מה שלקחה, ונמצאת נפסדת. \u0003וב\u0004דין \u0003בעל חוב מאוחר שקדם וגבה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 שכן גם הנשים כבעלות חוב הן לפרוע כתובתן.","\u0003תנא קמא סבר: מה שגבה — לא גבה,\u0004 כלומר, מה שגבה אינו זוכה בו לגמרי, אלא חוזר לבעל החוב המוקדם יותר. ואף כאן, אם תפסיד אחת מן הנשים את חלקה, וכגון שנמצא שהשדה שגבתה איננו שלו — תצטרך אף הרביעית להחזיר את מה שנטלה כדי לחלוק מחדש, ולכן אינה צריכה שבועה מיוחדת.","\u0003ובן ננס סבר: מה שגבה גבה,\u0004 ולכן צריכה גם הרביעית להשבע שלא גבתה כבר את כתובתה, שהרי ייתכן שתימצא מפסידה לשלישית במה שגבתה.","\u0003רב נחמן אמר\u0004 בשם \u0003רבה בר אבוה: דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 בעל חוב מאוחר שגבה — \u0003מה שגבה לא גבה,\u0004 וצריך להחזיר, ואם נמצא שדה אחד שלא היה שלו — יחזרו ויחלקו. \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תכסיף\u0004 \u0005[\u0006תזניח ו\u0005תפסיד]\u0006 הרביעית את השדה \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006","\u0003מר\u0004 \u0005[חכם זה,\u0006 בן ננס\u0005]\u0006 \u0003סבר: חיישינן\u0004 \u0005[אנו חוששים]\u0006 \u0003שמא תכסיף\u0004 \u0005[תפסיד],\u0006 שאם אין משביעים אותה, תבין שאין חזקתה בשדה בטוחה, שייתכן ותבוא הקודמת לה ותטרוף ממנה, ולכן תרבה בינתיים לנצל את השדה ותפחית מערכו, ואם תצטרך בסוף להחזירו, נמצא שנטלה בינתיים שלא כדין ולכן הטילו עליה שבועה. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר: לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תכסיף\u0004 \u0005[תפסיד],\u0006 ויש להניח שיישאר השדה בערכו הקודם ואין הקודמת מפסידה כלום.","\u0003אביי אמר:\u0004 לגבי ההלכה שאמר \u0003אביי קשישא\u0004 \u0005[הזקן]\u0006 \u0003איכא בינייהו\u0004 \u0005[\u0006הוא \u0005שיש ביניהם\u0006 מחלוקת\u0005].\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003אביי קשישא\u0004 \u0005[הזקן]:\u0006 \u0003יתומים שאמרו\u0004 חכמים שאין נפרעים מנכסיהם אלא בשבועה — הכוונה אפילו ליתומים \u0003גדולים\u0004 ובני דעת, שמאחר שאין יודעים בטיב עסקיו של המוריש, אפשר לתבוע מהם שלא כדין, ולכן משביעים את כל מי שנפרע מהם. \u0003ואין צריך לומר\u0004 שדין זה הוא ביתומים \u0003קטנים,\u0004 שודאי אינם יודעים בטיב משא ומתן וצריכים להגנה זו.","ונסביר כך: משנתנו מדברת ביתומים גדולים, וה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל את שיטת\u0005]\u0006 \u0003אביי קשישא\u0004 \u0005[הזקן],\u0006 ולכן אין האשה צריכה להשבע כאשר היא באה לגבות מהם את כתובתה. \u0003ובן ננס אית ליה\u0004 \u0005[יש לו,\u0006 הוא מקבל\u0005]\u0006 את דברי \u0003אביי קשישא\u0004 \u0005[הזקן],\u0006 ולכן אף שהיורשים היו גדולים, צריכה להשבע שלא נטלה. שאין נפרעים מנכסי יתומים אלא בשבועה.","\u0003אמר רב הונא: הני תרי אחי ותרי שותפי\u0004 \u0005[אותם שני אחים,\u0006 או \u0005שני שותפים]\u0006 \u0003דאית להו דינא בהדי חד\u0004 \u0005[שיש להם דין עם\u0006 אדם \u0005אחד],\u0006 \u0003ואזל חד מינייהו בהדיה לדינא\u0004 \u0005[והלך אחד מהם,\u0006 ועמד \u0005עימו לדין]\u0006 והפסיד בדינו — \u0003לא מצי\u0004 \u0005[יכול]\u0006 \u0003אידך למימר ליה\u0004 \u0005[\u0006השותף \u0005האחר,\u0006 או האח האחר, \u0005לומר לו]\u0006 לתובע: \u0003את לאו\u0004 \u0005[אתה לא]\u0006 \u0003בעל דברים דידי את\u0004 \u0005[שלי אתה],\u0006 כי הדיון שלך היה רק לגבי החלק שיש לאחי או לשותפי, אבל לגבי חלקי בשותפות, תצטרך לעשות דין חדש. \u0003אלא\u0004 אנו אומרים שהאח או השותף הראשון שהלך לדין והפסיד, \u0003שליחותיה עבד\u0004 \u0005[\u0006את \u0005שליחותו\u0006 של האח או השותף השני \u0005עשה].\u0006","מסופר: \u0003אקלע\u0004 \u0005[הזדמן]\u0006 פעם \u0003רב נחמן ל\u0004עיר \u0003סורא. שיילוהי\u0004 \u0005[שאלו אותו]:\u0006 \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה מהו]?\u0006","כלומר, שאלה זו ביחס לשותפים שרק אחד מהם בא לדין, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 וממנה נלמד מה הדין. שהרי שנינו: \u0003הראשונה נשבעת לשניה, ושניה לשלישית, ושלישית לרביעית. ואילו ראשונה לשלישית לא קתני\u0004 \u0005[שנינו],\u0006 שאין הראשונה צריכה להשבע גם לשלישית (ולרביעית), \u0003מאי טעמא, לאו\u0004 \u0005[מה הטעם,\u0006 האם \u0005לא]\u0006 \u0003משום\u0004 שהשניה שהשביעה את הראשונה, את \u0003שליחותה\u0004 של השלישית \u0003עבדה\u0004 \u0005[\u0006היא \u0005עושה]?\u0006 כיון שיש להן תביעה משותפת על הראשונה.","ודוחים: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר? \u0003התם\u0004 \u0005[שם]\u0006 בענין זה של הנשים \u0003שבועה לאחד ושבועה למאה,\u0004 וכיון שנשבעה פעם אחת שלא נטלה כלום, אין צורך שתשבע פעם אחרת, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 במקרה של השותפים, \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר]\u0006 האח או השותף השני: \u0003אילו אנא הואי, טעיננא טפי\u0004 \u0005[אילו אני הייתי\u0006 שם, \u0005הייתי טוען\u0006 טוב \u0005יותר].\u0006","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיש מקום לספק זה \u0003אלא דלא איתיה במתא\u0004 \u0005[\u0006כ\u0005שאינו בעיר]\u0006 והלך האחר בשביל שניהם, \u0003אבל\u0004 אם \u0003איתיה במתא\u0004 \u0005[ישנו בעיר]\u0006 — \u0003איבעי ליה למיתי\u0004 \u0005[היה צריך לו לבוא],\u0006 ואם לא בא — ברור שעשה את שותפו כשליח עבורו.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה. \u0003שני שטרות היוצאים\u0004 (שזמן כתיבתם הוא) \u0003ביום אחד,\u0004 כגון שנתן או מכר אותו דבר לשני אנשים שונים. \u0003רב אמר: חולקין\u0004 ביניהם, שאין לנו דרך להחליט למי שייך הנכס, ולכן צריך לחלוק. \u0003ושמואל אמר:\u0004 במקרה הזה \u0003שודא דדייני\u0004 \u0005[השלכת,\u0006 הכרעת \u0005הדיינים],\u0006 והם מחליטים כראות עיניהם למי מהתובעים מגיע הדבר.","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003רב\u0004 הוא ש\u0003אמר\u0004 את דבריו \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 לגבי גט, ולגבי שטר בכלל כי \u0003עדי חתימה כרתי\u0004 \u0005[\u0006הם ה\u0005כורתים],\u0006 כלומר, אימותו וחלותו של שטר באים יחד עם החתימה. וכאן, כיון שלא ביקשו מן העדים החותמים שיציינו זמן מדוייק יותר — משמע שהנותן התכוון לתת לשני אנשים בשווה, אלא שלא רצה לגלות להם שנותן לשניהם."],["\u0003ושמואל\u0004 ש\u0003אמר\u0004 שהדבר תלוי בהערכת הדיינים, הוא סובר \u0003כ\u0004דעת \u0003ר' אלעזר,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 שעדי מסירת השטר הם הקובעים את חלותו, ועדי החתימה הם רק לשם אימות הדברים במקרה של ערעור. ולכן, אף שהזמן הכתוב בשטר שווה הוא — אין זה חשוב, משום שעיקר הקנין בשעת המסירה, ולזה שמסר ראשון התכוון לתת. וכיון שמן הסתם קדם ומסר שטר אחר לפני השני, מסתבר שרצה לזכות רק לאחד מהם, ואין לחלק ביניהם אלא להכריע באופן אחר.","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שדעת הכל]\u0006 היא \u0003כ\u0004דעת \u0003ר' אלעזר, והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה\u0006 הם \u0005חולקים]\u0006 בבעיה עקרונית אחרת, \u0003רב סבר:\u0004 במקרה של ספק ממון שאין דרך לבררו \u0003חלוקה עדיפא\u0004 \u0005[עדיפה]\u0006 שאז ברור שמקבל הזכאי לכך לפחות חלק מן הנכס. \u0003ושמואל סבר: שודא דדייני עדיפא\u0004 \u0005[השלכת,\u0006 הכרעת, \u0005הדיינים עדיפה].\u0006","ושואלים: \u0003ומי מצית מוקמת ליה\u0004 \u0005[והאם יכול אתה\u0006 ל\u0005העמיד אותו]\u0006 את \u0003רב כ\u0004שיטת \u0003ר' אלעזר? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב: הלכה כר' אלעזר בגיטין.\u0004 ומספר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי\u0006 הלכה \u0005זו לפני]\u0006 \u0003שמואל, אמר: אף בשטרות\u0004 הלכה כמותו. ו\u0003מכלל\u0004 הדברים אתה למד ש\u0003רב סבר\u0004 שרק בגיטין הלכה כר' אלעזר, אבל \u0003בשטרות לא! אלא\u0004 צריך לחזור לתירוץ הקודם: \u0003מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 הוא שדעת \u0003רב כ\u0004שיטת \u0003ר' מאיר, ו\u0004דעת \u0003שמואל כ\u0004שיטת \u0003ר' אלעזר\u0004 כבתירוץ הקודם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003שני שטרות היוצאים ביום אחד — חולקין,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003שמואל!\u0004 ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך שמואל: הא מני\u0004 \u0005[\u0006ברייתא זו כשיטת \u0005מי\u0006 היא\u0005]\u0006 — כשיטת \u0003ר' מאיר\u0004 הסובר כי עדי חתימה כרתי \u0003היא, ואנא דאמרי\u0004 \u0005[ו\u0006אילו \u0005אני שאמרתי] —\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר\u0004 הסובר כי עדי מסירה כרתי, אמרתי.","וממשיכים להקשות: \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' מאיר\u0004 היא, \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה ברייתא: \u0003כתב לאחד ומסר\u0004 לבסוף \u0003לאחר — זה שמסר לו קנה. ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' מאיר\u0004 היא, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003קנה? האמר\u0004 \u0005[הרי אמר]\u0006 ר' מאיר כי \u0003עדי חתימה כרתי\u0004 \u0005[\u0006הם \u0005הכורתים]\u0006 ומקנים ולא עדי מסירה!","ומתרצים: לשיטת שמואל הברייתא כולה כשיטת ר' אלעזר, אלא \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בנושא זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שכאשר אמר אדם לשליח שיוליך סכום כסף לאדם אחר, ולא מצא השליח את האיש, שמת, ובינתיים מת גם השולח, נחלקו תנאים שונים מה יעשה השליח בכסף זה. \u0003וחכמים אומרים: יחלוקו,\u0004 יורשי השולח עם יורשי מי שנשלח אליו הכסף, \u0003וכאן אמרו: מה שירצה השליש\u0004 (השליח, שהכסף בידו) \u0003יעשה\u0004 (שהוא כעין שודא דדייני). הרי שיש מחלוקת תנאים כיצד נוהגים במקרה של ספק.","מסופר: \u0003אמיה\u0004 \u0005[אמו]\u0006 של \u0003רמי בר חמא כתבתינהו לנכסה\u0004 \u0005[כתבה את נכסיה]\u0006 \u0003לרמי בר חמא\u0004 בנה \u0003בצפרא\u0004 \u0005[בבוקר],\u0006 \u0003לאורתא כתבתינהו\u0004 \u0005[בערב כתבה אותם]\u0006 \u0003למר עוקבא בר חמא,\u0004 אחיו.","\u0003אתא\u0004 \u0005[בא]\u0006 \u0003רמי בר חמא לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב ששת, אוקמיה בנכסא\u0004 \u0005[\u0006ו\u0005העמיד אותו בנכסים],\u0006 שפסק שהנכסים שלו הם. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003מר עוקבא\u0004 אחיו \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, אוקמיה בנכסא\u0004 \u0005[\u0006ו\u0005העמידו בנכסים].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב ששת לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא עבד מר הכי\u0004 \u0005[מה טעם עשה אדוני כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003ומאי טעמא עבד מר הכי\u0004 \u0005[ומה טעם עשה אדוני כך]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 מפני ששטרו של רמי בר חמא \u0003קדים\u0004 \u0005[קדם]\u0006 לשטרו של מר עוקבא. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003בירושלים יתבינן דכתבינן\u0004 \u0005[יושבים אנו, שכותבים אנו]\u0006 \u0003שעות?\u0004 ובכל מקום שאין כותבים שעות בשטר, מחשבים את כל היום כולו כאותו זמן עצמו. חזר רב ששת ושאל: \u0003אלא מר מאי טעמא עבד הכי\u0004 \u0005[אדוני,\u0006 רב נחמן, \u0005מה טעם עשה כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003שודא דדייני\u0004 \u0005[השלכת,\u0006 הכרעת \u0005הדיינים],\u0006 כלומר, אני הכרעתי, שכך נראה לי שזה היה רצונה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003אנא נמי שודא דדייני\u0004 \u0005[אני גם כן\u0006 עושה זאת משום \u0005הכרעת הדיינים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: יש שני דברים כנגד זה; \u0003חדא, דאנא דיינא ומר לאו דיינא\u0004 \u0005[אחד, שאני דיין ואדוני אינו דיין],\u0006 כי רב נחמן היה דיין רשמי ורב ששת לא היה דיין רשמי במקומו, ולכן אין בידו הכוח של הכרעת הדיינים. \u0003ועוד, מעיקרא לאו בתורת הכי אתית לה\u0004 \u0005[מתחילה לא משום כך\u0006 (הכרעת הדיינים) \u0005באת לזה]\u0006 אלא משום סברה, והתברר אחר כך שסברה זו אינה נכונה.","מסופר: \u0003הנהו תרי שטרי דאתו לקמיה\u0004 \u0005[אותם שתי שטרות שבאו לפני]\u0006 \u0003רב יוסף,\u0004 שמכר אדם נכס אחד לשני אנשים שונים. \u0003חד הוה\u0004 \u0005[אחד היה]\u0006 \u0003כתוב\u0004 בו התאריך \u0003בחמשא\u0004 \u0005[חמישה]\u0006 \u0003בניסן, וחד הוה\u0004 \u0005[ואחד היה]\u0006 \u0003כתוב ביה\u0004 \u0005[בו]\u0006 \u0003בניסן סתמא\u0004 \u0005[סתם].\u0006 \u0003אוקמיה\u0004 \u0005[העמידו]\u0006 \u0003רב יוסף לההוא\u0004 ששטרו היה ב\u0003חמשא\u0004 \u0005[\u0006ב\u0005חמישה]\u0006 \u0003בניסן בנכסים.\u0004","\u0003אמר ליה אידך\u0004 \u0005[לו האחר]:\u0006 \u0003ואנא\u0004 \u0005[ואני]\u0006 \u0003אפסיד?\u0004 והרי ייתכן ששטרי היה מוקדם לשטרו של האחר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את\u0004 \u0005[אתה]\u0006 \u0003ידך על התחתונה,\u0004 משום שאין תאריך מסויים בשטרך, \u0003אימא בר\u0004 \u0005[אמור\u0006 ש\u0005בן]\u0006 \u0003עשרים ותשעה בניסן את\u0004 \u0005[אתה],\u0006 ושטרך מאוחר יותר, וכיון שאין בידו להוכיח, נותנים את הנכסים לזה שהתאריך בשטר שלו ברור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו איש: \u0003ונכתוב\u0004 \u0005[ויכתוב]\u0006 \u0003לי מר\u0004 \u0005[אדוני]\u0006"],["\u0003טירפא\u0004 \u0005[\u0006שטר \u0005טריפה]\u0006 המתיר לטרוף (לגבות) קרקע שנמכרה \u0003מ\u0004ראש חודש \u0003אייר ואילך,\u0004 ששטרי הלא ודאי מוקדם לשטרו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003יכלי למימר\u0004 \u0005[יכולים\u0006 אותם לקוחות \u0005לומר]\u0006 \u0003לך: את בר חד\u0004 \u0005[אתה,\u0006 שטרך, \u0005בן אחד]\u0006 \u0003בניסן את\u0004 \u0005[אתה],\u0006 ובעצם השדה שקנית היה מגיע לך, והאחר הוא שלקחו שלא כדין, וכיון שכן אין הלקוחות צריכים לשלם לו דבר, שאין ברור אם מגיע לו.","ושואלים: אם כן, \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 שהרי לפי זה הריהו מפסיד מכל צד שהוא! ומשיבים: \u0003נכתבו\u0004 \u0005[שיכתבו]\u0006 שני בעלי השטר שטר \u0003הרשאה להדדי\u0004 \u0005[זה לזה]\u0006 ויוכלו לטרוף מלקוחות ששטרם מאוחר יותר.","\u0003מי שהיה נשוי שתי נשים ומכר את שדהו, וכתבה\u0004 האשה שנישאה \u0003ראשונה ללוקח\u0004 (לקונה): \u0003\"דין ודברים אין לי עמך\"\u0004 — אשתו \u0003השניה\u0004 שלא ויתרה \u0003מוציאה מהלוקח,\u0004 שהרי שעבוד כתובתה היה קודם ללוקח. \u0003ו\u0004אז \u0003ראשונה\u0004 מוציאה \u0003מן השניה,\u0004 שכיון שעכשיו הנכסים בחזקת האשה השניה, ושטר הכתובה הראשון קודם לשטר הכתובה השני — הרי היא לוקחת את השדה ממנה. \u0003והלוקח\u0004 מוציא \u0003מן הראשונה,\u0004 שהרי הראשונה ויתרה על זכותה על השדה לגבי לוקח זה \u0003וחוזרות חלילה\u0004 (במעגל) שזה מוציא מזה, \u0003עד שיעשו פשרה ביניהם. וכן\u0004 אם היה \u0003בעל חוב\u0004 באופן כזה \u0003וכן אשה בעלת חוב.\u0004","שואלים: \u0003וכי כתבה ליה מאי הוי\u0004 \u0005[וכאשר תכתוב לו\u0006 כך \u0005מה יהיה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לחבירו\u0004 שהוא שותף עימו בשדה: \u0003\"דין ודברים אין לי על שדה זו\",\u0004 או שאמר לו: \u0003\"אין לי עסק בה\",\u0004 או שאמר: \u0003\"ידי מסולקת הימנה\" — לא אמר כלום.\u0004 שהבטחה כגון זו אין לה תוקף משפטי! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשקנו מידה,\u0004 ומאחר ועשו מעשה קנין על הויתור הזה, הריהו מקבל תוקף חוקי.","ושואלים: \u0003וכי\u0004 \u0005[ו\u0006גם \u0005כאשר]\u0006 \u0003קנו מידה מאי הוי\u0004 \u0005[מה יהיה]?\u0006 \u0003תימא\u0004 \u0005[\u0006ש\u0005תאמר]\u0006 האשה אחר כך: \u0003נחת רוח עשיתי לבעלי,\u0004 שראיתי שהוא רוצה למכור את השדה, ולא רציתי לריב עימו, אבל לא התכוונתי לכך באמת. \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 מי ש\u0003לקח\u0004 (קנה) דבר \u0003מן האיש ו\u0004אפילו \u0003חזר ולקח מן האשה\u0004 את הזכויות שיש לה בדבר — \u0003מקחו בטל. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003יכולה היא,\u0004 האשה, \u0003שתאמר\u0004 \"זה שמכרתי אחר כך את הדבר לקונה מפני ש\u0003נחת רוח עשיתי לבעלי,\u0004 לפי שעה\".","\u0003אמר רב זירא אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' מאיר, הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 כשיטת \u0003ר' יהודה.\u0004 ומה עניינם?","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בעל שהיו לו שני שדות ומכר שדה אחד ו\u0003כתב\u0004 שטר מכר \u0003לראשון ו\u0004האשה \u0003לא חתמה לו,\u0004 שלא הסכימה למכר זה, ואחר כך מכר שדה \u0003לשני וחתמה לו\u0004 שמסכימה למכר — הרי זו \u0003איבדה כתובתה,\u0004 אם לא נשאר לו רכוש אחר שתוכל לגבות ממנו, אלו \u0003דברי ר' מאיר.\u0004 וסברתו, שלא זו בלבד שאינה יכולה לתבוע מן השני, שהרי חתמה על השטר, אלא גם מן הראשון אינה יכולה לתבוע, משום שהוא אומר: כאשר קניתי אני שדה אחד, השארתי לך ממה לגבות כתובתך, ואתה הוא שהפסדת לעצמך.","\u0003ר' יהודה אומר: יכולה היא שתאמר \"נחת רוח עשיתי לבעלי,\u0004 ובאמת לא הסכמתי גם לשני, \u0003אתם מה לכם עלי\"?\u0004","ושואלים: אמנם הסברנו את טעם ההבדל בין משנתנו ובין המשנה האחרת, \u0003ו\u0004אולם האם ייתכן ש\u0003רבי,\u0004 עורך המשנה, \u0003סתם לה הכא\u0004 \u0005[כאן]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר וסתם לה התם\u0004 \u0005[שם]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה?!\u0004","אלא \u0003אמר רב פפא\u0004 תירוץ אחר לקושיה: במשנתנו מדובר \u0003ב\u0004אשה \u0003גרושה,\u0004 שכאשר היתה גרושה כתבה ללוקח את שטר הויתור הזה, \u0003ודברי הכל\u0004 היא, שהרי אינה יכולה לומר שעשתה נחת רוח לבעלה.","\u0003רב אשי אמר: כולה\u0004 (כל המשניות) כשיטת \u0003ר' מאיר היא, ו\u0004אולם \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם]\u0006 שאין האשה יכולה לטעון שעשתה נחת רוח לבעלה, \u0003אלא בשני לקוחות\u0004 שונים, \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003לה: אי איתא\u0004 \u0005[אם יש\u0006 אמת בדבר\u0005]\u0006 ש\u0003נחת רוח עבדת\u0004 \u0005[עשית]\u0006 לבעלך \u0005—\u0006 במכירה \u0003לקמא איבעי\u0004 \u0005[ל\u0006לוקח \u0005ראשון היה]\u0006 \u0003לך למיעבד\u0004 \u0005[לעשות],\u0006 ולא במכירה לשני. \u0003אבל\u0004 כאן, שמדובר \u0003בלוקח אחד — אפילו ר' מאיר מודה,\u0004 שיכולה היא לומר שעשתה כן רק כדי לעשות נחת רוח לבעלה. \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 מדברת במקרה ש\u0003כתב ליה\u0004 \u0005[לו]\u0006 הבעל \u0003לאחר\u0004 לפני כן שטר על מכירת השדה, ולא הסכימה האשה, ובפעם שניה הסכימה וחתמה, ובמקרה זה, אפילו ר' מאיר יודה שיכולה לומר \"נחת רוח עשיתי לבעלי\".","\u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה\u0005]:\u0006 \u0003אין נפרעין מנכסים משועבדים במקום שיש נכסים בני חורין, ואפילו\u0004 הנכסים בני החורין \u0003הן זיבורית\u0004 (קרקע גרועה). \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003אישתדוף בני חרי\u0004 \u0005[נשדפו\u0006 והתקלקלו אחר כך הנכסים \u0005בני חורין]\u0006 ואינם מספיקים לתשלום חובו, \u0003מהו דליטרוף ממשעבדי\u0004 \u0005[האם\u0006 יכול הנושה \u0005לטרוף מ\u0006נכסים \u0005משועבדים]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003כתב לראשון ולא חתמה לו\u0004 האשה להבהיר לו את הסכמתה למכר, ואחר כך כתב \u0003לשני וחתמה לו — איבדה כתובתה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ואי סלקא דעתך אישתדוף בני חרי טריף ממשעבדי\u0004 \u0005[ואם עולה על דעתך\u0006 שאם \u0005נשדפו\u0006 הנכסים \u0005בני החורין טורף ממשועבדים],\u0006 אם כן, \u0003נהי\u0004 \u0005[אם אמנם]\u0006 \u0003איבדה כתובתה משני,\u0004 שהרי חתמה לו — \u0003מראשון מיהא תיגבי\u0004 \u0005[על כל פנים תיגבה]\u0006 שהרי הוא מבחינתה כנכסים משועבדים לגבי בני חורין שנפסדו, משמע שאי אפשר לטרוף אם נפסדו.","\u0003אמר רב נחמן בר יצחק:\u0004 אפשר לומר כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"איבדה\"\u0004 שאמר ר' מאיר — \u0003איבדה משני\u0004 בלבד.","\u0003אמר רבא: שתי תשובות בדבר, חדא\u0004 \u0005[אחת],\u0006 שלשון \u0003\"איבדה\" — לגמרי משמע,\u0004 ואף מהראשון. \u0003ועוד,\u0004 הלא \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא במפורש\u0005]:\u0006 \u0003לוה מן האחד ומכר\u0004 הלוה \u0003נכסיו לשנים, וכתב בעל חוב ללוקח שני: \"דין ודברים אין לי עמך\" — אין לו\u0004 גם \u0003על\u0004 ה\u0003לוקח\u0004 ה\u0003ראשון כלום.\u0004 ומדוע? \u0003מפני שיכול\u0004 הלוקח הראשון \u0003לומר: הנחתי לך מקום לגבות הימנו.\u0004 שכאשר קניתי אני, עוד היו נכסים בני חורין בידי הלווה, ואם כן אין לך תביעות עלי.","ודוחים את הראיה מר' מאיר באופן אחר: \u0003התם איהו דאפסיד נפשיה\u0004 \u0005[שם\u0006 הרי \u0005הוא שהפסיד לעצמו]\u0006 \u0003בידים,\u0004 שכיון שחתם מעצמו נמצא שהוא הזיק לעצמו, ואין הדבר דומה לנכסים שנשתדפו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי:\u0004"],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003מעשים בכל יום\u0004 שבית דין נוהג שגובים מנכסים משועבדים כאשר הופסדו נכסים בני חורין, כגון מעשה \u0003דההוא גברא דמישכן ליה פרדיסא לחבריה\u0004 \u0005[של אותו אדם שמישכן לו פרדס לחבירו]\u0006 \u0003לעשר שנין\u0004 \u0005[שנים],\u0006 שיאכל מפירות הפרדס כתשלום של ההלוואה שהלוה לו, \u0003וקש\u0004 \u0005[והזדקן]\u0006 הפרדס \u0003ל\u0004אחר \u0003חמש שנין\u0004 \u0005[שנים],\u0006 ולא הוציא עוד פירות כראוי, \u0003ואתא לקמייהו דרבנן\u0004 \u0005[ובא\u0006 המלווה \u0005לפני חכמים]\u0006 לטעון \u0003וכתבו ליה טירפא\u0004 \u0005[לו שטר טריפה]\u0006 על נכסיו של הלווה שיטרוף מנכסים אחרים שמכר הלווה. הרי שבית הדין מגבים לתובע מנכסים משועבדים של החייב כאשר הופסדו בני החורין!","ומשיבים: \u0003התם נמי אינהו הוא דאפסידו אנפשייהו\u0004 \u0005[שם גם כן\u0006 הקונים \u0005הם שהפסידו לעצמם],\u0006 \u0003כיון דהוו ידעי דפרדיסא עביד דקיש\u0004 \u0005[שהיו יודעים שפרדס עשוי שיזדקן],\u0006 לכך \u0003לא איבעי להו למיזבן\u0004 \u0005[היה להם לקנות]\u0006 מן הלווה, שמא לא יוכל לשלם את חובו הראשון מפירות הפרדס.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 למעשה היא: אם \u0003אישתדוף בני חרי\u0004 \u0005[\u0006אם \u0005השתדפו,\u0006 נפסדו, נכסים \u0005בני חורין] —\u0006 \u0003טרפא ממשעבדי\u0004 \u0005[טורפת ממשועבדים].\u0006","\u0003אמר אביי,\u0004 אמר אדם לאשה פנויה: \u0003\"נכסי ליך\u0004 (לך) \u0003ואחריך לפלוני\",\u0004 שלאחר מותה יירש פלוני זה את הנכסים, \u0003ועמדה\u0004 אותה אשה \u0003וניסת — בעל לוקח\u0004 (קונה) \u0003הוי\u0004 \u0005[הוא],\u0006 כלומר, כאילו מכרה לו האשה בחייה את הנכסים, \u0003ואין ל\"אחריך\"\u0004 (לזה שהובטחו לו הנכסים אחרי האשה) \u0003במקום בעל כלום.\u0004 הואיל ובזמן שהיו הנכסים אצלה היו שלה לגמרי, וכל מה שמכרה באותו זמן — מכור.","ומסכמים: שיטה זו \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 היא — \u0003כי האי תנא\u0004 \u0005[כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר \u0003\"נכסי ליך\u0004 \u0005[לך]\u0006 \u0003ואחריך לפלוני\"\u0004 ואחר כך \u0003ירד הראשון ומכר,\u0004 וממילא לא נותר מה להעביר לזה שציווהו \"ואחריך לפלוני\" — \u0003השני מוציא מיד הלקוחות,\u0004 אלו \u0003דברי רבי.\u0004 שלדעתו ניתנו הנכסים לראשון רק כדי להשתמש בהם, אבל אינו רשאי להעבירם לצמיתות לאחרים. \u0003רבן שמעון בן גמליאל אומר: אין לשני\u0004 בנכסים \u0003אלא מה ששייר ראשון\u0004 ולא יותר מכך. ופסק איפוא אביי כרבן שמעון בן גמליאל.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי\u0004 עצמו: \u0003איזהו רשע ערום — זה המשיא עצה\u0004 לחבירו \u0003למכור בנכסים כ\u0004דעת \u0003רבן שמעון בן גמליאל,\u0004 הרי שאין דעתו נוחה ממי שמשתמש למעשה בדרך זו!","ומשיבים: \u0003מי קאמר\u0004 \u0005[האם אמר]\u0006 לתת עצה לאשה ש\u0003תינשא?\u0004 הלא \u0003\"נשאת\" קאמר\u0004 \u0005[אמר]\u0006 שדרך העולם שאשה נישאת, ולא עשתה זאת כדי להפקיע נכסים מן האחר, אלא שממילא באו הנכסים לידי בעלה.","ומביאים מימרא נוספת של אביי בענין זה, \u0003ואמר אביי:\u0004 האומר לאשה נשואה \u0003\"נכסי ליך ואחריך לפלוני\" ומכרה ומתה — הבעל מוציא מיד הלקוחות.\u0004 שאם דינו כלוקח — הריהו כלוקח ראשון, הטורף מיד הבאים אחריו, \u0003ו\u0004זה שאודותיו היה הציווי \u0003\"אחריך\u0004 לפלוני \u0003\"\u0004מוציא \u0003מיד\u0004 ה\u0003בעל,\u0004 שהרי לפי הוראת הנותן הראשון הנכסים שייכים לו במות האשה, \u0003ולוקח\u0004 מוציא \u0003מיד \"אחריך\"\u0004 שהרי קנה את הנכסים. \u0003ו\u0004בסופו של דבר \u0003מוקמינן לכולהו בידא\u0004 \u0005[מעמידים את\u0006 הנכסים \u0005כולם ביד]\u0006 ה\u0003לוקח.\u0004","ושואלים: \u0003מאי שנא מהא דתנן\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וחוזרות חלילה עד שיעשו פשרה ביניהן?\u0004 ומשיבים: \u0003התם אית להו פסידא לכולהו\u0004 \u0005[שם יש להם הפסד לכולם],\u0006 שהרי כל אחד מהם יש לו תביעת ממונות ברורה ולכן עושים פשרה ביניהם, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לוקח\u0004 בלבד \u0003הוא דאית ליה פסידא\u0004 \u0005[שיש לו הפסד],\u0006 שהוא היחיד ששילם עבור הנכסים והאחרים קיבלום כמתנה, ולכן מעמידים את הנכסים ברשותו.","\u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רפרם אמר לשמעתא קמיה\u0004 \u0005[את ההלכה\u0006 הזו \u0005לפני]\u0006 \u0003רב אשי\u0004 ושאל אותו: \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר אביי הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אביי: \"נכסי ליך ואחריך לפלוני\",\u0004 אם \u0003עמדה וניסת — בעל לוקח הוי\u0004 \u0005[הוא]\u0006 \u0003ואין ל\"אחריך\" במקום בעל כלום.\u0004 והואיל והבעל לוקח הוא, מדוע יש ל\"אחריך\" או ללוקח השני זכות בנכסים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 שזכה הבעל לגמרי בנכסים, מדובר כש\u0003אמר לה\u0004 המוריש \u0003כשהיא פנויה, הכא\u0004 ש\u0003אמר\u0004 \u0005[כאן שאמר]\u0006 \u0003לה כשהיא נשואה.\u0004 שכאשר היא כבר נשואה \u0003מאי קאמר\u0004 \u0005[מה אומר]\u0006 \u0003לה,\u0004 הרי משמעות דבריו בהקשר זה היא — \u0003\"אחריך\" ליקני\u0004 \u0005[\u0006הוא \u0005שיקנה]\u0006 את הנכסים, \u0003בעל\u0004 ש\u0003לא ליקני\u0004 \u0005[יקנה],\u0006 שמתוך דבריו מובן שאינו רוצה שיעברו הנכסים לבעל.","","שנינו במשנה \u0003וכן בעל חוב.\u0004 והלשון סתומה, שאין מובן ממנה במה בדיוק מדובר. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003וכן בעל חוב\u0004 שהלווה לאחר ולו שני שדות ששוויים כערך החוב \u0003ושני לקוחות\u0004 שקנו ממנו אותם וכתב המלווה ללוקח השני \"דין ודברים אין לי עמך\", שטורף המלווה מבעל חוב ראשון, והראשון ששטרו קודם טורף מלוקח שני, והמלווה חוזר וטורף מן הראשון.","\u0003וכן אשה בעלת חוב\u0004 הבאה לגבות כתובתה מנכסי בעלה \u0003ושני לקוחות\u0004 שקנו ממנו את נכסיו.","","\u0003אלמנה\u0004 שהיא \u0003ניזונת מנכסי יתומים\u0004 (שאינם בניה אלא בני בעלה מאשה אחרת) שירשו מאביהם — \u0003מעשה ידיה שלהן\u0004 הוא, \u0003ואין\u0004 היתומים \u0003חייבין בקבורתה,\u0004 שחובת הקבורה באה במקום כתובה, וכיון שאינם יורשים את כתובתה, אף אינם חייבים לקוברה. \u0003יורשיה\u0004 שהם \u0003יורשי כתובתה,\u0004 הם ה\u0003חייבין בקבורתה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם \u0003\"ניזונת\" תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003או \"הניזונת\" תנן\u0004 \u0005[שנינו]?\u0006 ומה משמעות ההבדל — אם \u0003\"ניזונת\" תנן\u0004 \u0005[שנינו]\u0006 ומשמעו שסתם אלמנה ניזונת, \u0003וכ\u0004מנהג \u0003אנשי גליל\u0004 שהיו כותבים בכתובה שזכות האלמנה לשבת בבית בעלה לאחר מות בעלה ולהתפרנס מנכסיו כל עוד לא נישאה לאחר, \u0003ולא סגי\u0004 \u0005[די],\u0006 אי אפשר, ש\u0003לא יהבי\u0004 \u0005[יתנו]\u0006 \u0003לה,\u0004","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"הניזונת\" תנן\u0004 \u0005[שנינו]\u0006 (כלומר, שמדובר באותה אלמנה שניזונת) ו\u0003כאנשי יהודה\u0004 שהיו כותבים בכתובה שתשב האלמנה בבית בעלה עד שיתנו לה היורשים את כתובתה, \u0003ו\u0004לכן \u0003אי בעו\u0004 \u0005[אם ירצו]\u0006 \u0003לא יהבי\u0004 \u0005[יתנו]\u0006 \u0003לה\u0004 מזונות, אלא יתנו לה כתובתה ויפטרוה."],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממה ש\u0003אמר ר' זירא אמר שמואל: מציאת אלמנה לעצמה. אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003\"הניזונת\" תנן\u0004 \u0005[שנינו] —\u0006 אם כן \u0003שפיר\u0004 \u0005[יפה]\u0006 שיש מקרים שניזונת ויש כאלה שאינה ניזונת, ואפשר לומר ששמואל מדבר במקרה מיוחד, כאשר אינה ניזונת ולכן מציאתה לעצמה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003\"ניזונת\" תנן\u0004 \u0005[שנינו],\u0006 כלומר, שחייבים היתומים לזונה במקום הבעל, אם כן \u0003ניהוו\u0004 \u0005[שיהיו]\u0006 היורשים \u0003כבעל\u0004 לכל דבר, ולכן: \u0003מה\u0004 לגבי \u0003בעל מציאת אשה לבעלה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מציאת אשה ליורשים!\u0004","ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך:\u0004 כי \u0003\"ניזונת\" תנן\u0004 \u0005[שנינו]\u0006 ולמרות זה דברי שמואל קיימים בכל מקרה, כי \u0003טעמא מאי אמור רבנן\u0004 \u0005[מה טעם אמרו חכמים]\u0006 כי \u0003מציאת אשה לבעלה\u0004 — כדי ש\u0003לא תהוי\u0004 \u0005[תהא]\u0006 \u0003לה איבה\u0004 עימו, שלא יסתכסכו בגלל כסף שיש בידה שאין הוא בטוח לגבי מקורו, ולכן תיקנו שתהא מציאתה לו כדי שיהיה שלום ביניהם. ואולם \u0003הני\u0004 \u0005[אלה]\u0006 היורשים — \u0003תהוי להו\u0004 \u0005[\u0006ש\u0005תהיה להם]\u0006 \u0003איבה,\u0004 וכיון שהם מחוייבים בתשלום מזונות בכל מקרה, לפיכך אין חייבים לדאוג במיוחד לשלום ביניהם.","\u0003אמר ר' יוסי בר חנינא: כל מלאכות שהאשה עושה לבעלה\u0004 (המנויות לעיל כתובות נט, ב), גם \u0003אלמנה עושה ליורשים, חוץ ממזיגת הכוס והצעת המטה והרחצת פניו ידיו ורגליו,\u0004 שהן מלאכות של חיבה שאשה עושה לבעלה דווקא.","\u0003אמר ר' יהושע בן לוי: כל מלאכות שהעבד עושה לרבו\u0004 — אף \u0003תלמיד עושה לרבו, חוץ מהתרת (לו) מנעל,\u0004 שהיא פעולה בזויה, שאז הוא נראה כעבד, ולא כתלמיד.","\u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא במקום שאין מכירין אותו\u0004 ואפשר שיחשבו שהוא עבד, \u0003אבל במקום שמכירין אותו — לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור, שהכל יודעים שאינו עבד. \u0003אמר רב אשי: ובמקום שאין מכירין אותו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאינו מתיר מנעל רבו \u0003אלא\u0004 בשעה שהוא \u0003לא מנח\u0004 \u0005[מניח]\u0006 \u0003תפלין, אבל\u0004 בשעה שהוא \u0003מנח\u0004 \u0005[מניח]\u0006 \u0003תפלין\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור, כי מאחר וידוע שעבד אינו מניח תפילין, הרי מוכח שאינו עבד.","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל המונע תלמידו מלשמשו — כאילו מונע ממנו,\u0004 מן התלמיד, \u0003חסד. שנאמר: \"למס מרעהו חסד\"\u0004 (איוב ו, יד), שהוא מפרשו בדרך זו: מי שמונע (\"למס\" כמו ממיס, מסיר) עצמו מלקבל טובה מרעהו — מונע ממנו את מצוות החסד שצריך עושה החסד לעשות. \u0003רב נחמן בר יצחק אומר: אף פורק ממנו\u0004 מן התלמיד \u0003יראת שמים, שנאמר\u0004 בהמשך אותו כתוב: \u0003\"ויראת שדי יעזוב\"\u0004 (איוב ו, ד).","\u0003אמר ר' אלעזר: אלמנה שתפסה מטלטלין במזונותיה\u0004 (לצורך המזונות) — \u0003מה שתפסה תפסה\u0004 ואין מוציאים מידה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אלמנה שתפסה מטלטלין במזונותיה — מה שתפסה תפסה.\u0004","\u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: מעשה בכלתו של ר' שבתי שתפסה דסקיא\u0004 (שק עור) \u0003מלאה מעות\u0004 לצורך מזונותיה, \u0003ולא היה כח ביד חכמים להוציא מידה,\u0004 שהרי כפי שאמרנו — מה שתפסה תפסה.","\u0003אמר רבינא: ולא אמרן\u0004 \u0005[אמרנו]\u0006 שאין מוציאים מידה, \u0003אלא\u0004 כאשר תפסה \u0003למזוני\u0004 \u0005[ל\u0006צורך \u0005מזונות],\u0006 \u0003אבל\u0004 אם תפסה \u0003ל\u0004צורך \u0003כתובה — מפקינן מינה\u0004 \u0005[מוציאים ממנה].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 שאם תפסה \u0003ל\u0004צורך \u0003כתובה\u0004 שמוציאים ממנה? — שכתובה נוטלת \u0003ממקרקעי\u0004 \u0005[מקרקעות]\u0006 \u0003ולא ממטלטלי\u0004 \u0005[ממטלטלים]\u0006 אולם, \u0003מזונות נמי\u0004 \u0005[גם כן]\u0006 הלא התקנה היא שנוטלת \u0003ממקרקעי\u0004 \u0005[מקרקעות]\u0006 \u0003ולא ממטלטלי\u0004 \u0005[ממטלטלים]!\u0006 \u0003אלא\u0004 כשם שאתה אומר שאם תפסה \u0003למזוני\u0004 \u0005[ל\u0006צורך \u0005מזונות]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003תפסה\u0004 — \u0003תפסה, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר כאשר תפסה \u0003ל\u0004צורך \u0003כתובה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יצחק בר נפתלי לרבינא: הכי אמרינן משמיה\u0004 \u0005[כך אמרנו משמו]\u0006 של \u0003רבא כוותיך\u0004 \u0005[כמותך,\u0006 כשיטתך\u0005],\u0006 שאם תפסה מטלטלים לצורך כתובה, מוציאים מידה.","\u0003אמר ר' יוחנן משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוסי בן זימרא: אלמנה ששהתה שתים ושלש שנים\u0004 לאחר מות בעלה, \u0003ולא תבעה מזונות\u0004 מיורשי הבעל — \u0003איבדה מזונות.\u0004 שאנו אומרים שכיון שלא תבעה, ודאי מחלה עליהם.","ודנים בלשון מימרה זו: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם שהתה \u0003שתים\u0004 (שתי שנים) ולא תבעה — \u0003איבדה\u0004 מזונותיה, אם כן, כאשר לא תבעה \u0003שלש\u0004 שנים, \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר?! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן — בעניה\u0004 שאינה יכולה להתפרנס משל עצמה אלא זמן קצר, אם כן שנתיים זמן ארוך הוא, ואם לא תבעה בתוך זמן זה — ודאי מחלה, ואילו \u0003כאן — בעשירה\u0004 שיכולה לשהות שנתיים ולהתפרנס משל עצמה, ורק אם שהתה שלוש שנים משמע שמחלה על המגיע לה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לומר כי \u0003כאן — בפרוצה,\u0004 אשה שאיננה צנועה כל כך, ואינה מתביישת לבוא ולתבוע, ואם לא תבעה בתוך שנתיים — ודאי מחלה, ואילו \u0003כאן — בצנועה,\u0004 שמתביישת לתבוע ודוחה עד לשלוש שנים את תביעתה למזונות.","\u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא למפרע,\u0004 כלומר, שאיבדה את דמי המזונות שלא תבעה עד עכשיו, \u0003אבל להבא,\u0004 מזמן תביעה ואילך, \u0003יש לה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן\u0004 שאלה זו, \u0003יתומים אומרים: נתננו\u0004 לה מזונות, \u0003והיא אומרת: לא נטלתי, על מי\u0004 מהם \u0003להביא ראיה\u0004 לדבריהם?"],["\u0003נכסי\u0004 \u0005[הנכסים]\u0006 \u0003בחזקת יתמי קיימי\u0004 \u0005[היתומים עומדים]\u0006 \u0003ועל אלמנה להביא ראיה\u0004 משום שהיא מוציאה מידם, והמוציא מחבירו עליו חובת הראיה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003נכסי\u0004 \u0005[הנכסים]\u0006 \u0003בחזקת\u0004 ה\u0003אלמנה קיימי\u0004 \u0005[עומדים],\u0006 שהרי הם משועבדים לכל מה שהתחייב בכתובתה, \u0003ועל היתומים להביא ראיה\u0004 כאשר מוציאים ממנה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי\u0004 ברייתא זו: \u0003אלמנה, כל זמן שלא ניסת\u0004 (נישאה) — \u0003על היתומים להביא ראיה\u0004 שנתנו לה. \u0003ניסת,\u0004 ובאה לתבוע מזונות שהיתה צריכה לקבל בעבר — \u0003עליה להביא ראיה.\u0004","\u0003אמר רב שימי בר אשי:\u0004 שאלת ר' יוחנן היא \u0003כתנאי\u0004 \u0005[כ\u0006דברי \u0005תנאים]\u0006 שנחלקו בבעיה זו, ששנינו: \u0003מוכרת\u0004 אלמנה מנכסי הנפטר, \u0003וכותבת: \"\u0004נכסים \u0003אלו ל\u0004צורך \u0003מזונות מכרתי, ואלו ל\u0004צורך ה\u0003כתובה מכרתי\",\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר: מוכרת וכותבת סתם,\u0004 כמה מכרה, \u0003וכן כחה יפה\u0004 (טוב לה), שלפי מצב התביעות האחרות מנכסי הבעל תוכל להחליט אם מה שנטלה ייחשב לכתובתה או למזונותיה.","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006בעיה \u0005זו חלוקים\u0006 הם\u0005],\u0006 ש\u0003לר' יהודה\u0004 ש\u0003אמר\u0004 כי \u0003בעי לפרושי\u0004 \u0005[צריכה\u0006 היא \u0005לפרש],\u0006 משמע ש\u0003סבר\u0004 כי \u0003נכסי\u0004 \u0005[הנכסים]\u0006 \u0003בחזקת יתמי קיימי\u0004 \u0005[היתומים עומדים],\u0006 \u0003ו\u0004לכן \u0003על האלמנה להביא ראיה,\u0004 ולכן צריכה לכתוב על מה הוציאה כל דבר. \u0003ו\u0004אילו \u0003ר' יוסי סבר\u0004 ש\u0003לא בעי לפרושי\u0004 \u0005[צריכה לפרש],\u0006 כי לדעתו \u0003נכסי\u0004 \u0005[הנכסים]\u0006 \u0003בחזקת\u0004 ה\u0003אלמנה קיימי\u0004 \u0005[עומדים],\u0006 \u0003ו\u0004לכן \u0003על היתומים להביא ראיה.\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה מסקנה זו? \u0003דלמא דכולי עלמא\u0004 \u0005[שמא לדעת הכל]\u0006 \u0003נכסי\u0004 \u0005[הנכסים]\u0006 \u0003בחזקת\u0004 ה\u0003אלמנה קיימי\u0004 \u0005[עומדים]\u0006 \u0003ועל היתומים להביא ראיה, ו\u0004אולם \u0003ר' יהודה עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 — ש\u0003לא ליקרו\u0004 \u0005[יקראו]\u0006 \u0003לה רעבתנותא\u0004 \u0005[רעבתנית],\u0006 שמוציאה הרבה כל כך, למזונותיה. ולכן מייעץ לה שתפרט מה הוציאה למזונות ומה מכרה לצורך אחר.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שמדובר רק בעצה טובה, \u0003הא דבעי\u0004 \u0005[\u0006שאלה \u0005זו ששאל]\u0006 \u0003ר' יוחנן\u0004 על מי להביא ראיה, \u0003תפשוט ליה ממתניתין\u0004 \u0005[תפתור אותה ממשנתנו]\u0006 ששנינו: \u0003מוכרת\u0004 האשה \u0003למזונות שלא בבית דין, וכותבת: \"אלו למזונות מכרתי\"\u0004 ולפי הדרך שאמרנו אפשר היה לפתור מכאן שהנכסים בחזקת היתומים ועליה להביא ראיה! \u0003אלא\u0004 צריך לומר כי \u0003ממתניתין ליכא למשמע מינה\u0004 \u0005[ממשנתנו אין לשמוע ממנה]\u0006 הלכה בענין זה כי \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא יבואו להתרעם עליה, \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 בברייתא \u0003עצה טובה\u0004 בלבד \u0003קא משמע לן\u0004 \u0005[השמיע לנו].\u0006","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר להיפך: \u0003דכולי עלמא נכסי\u0004 \u0005[שלדעת הכל הנכסים]\u0006 \u0003בחזקת יתמי קיימי\u0004 \u0005[היתומים עומדים]\u0006 \u0003והיינו טעמא\u0004 \u0005[וזה הטעם]\u0006 של \u0003ר' יוסי\u0004 — שהוא סובר \u0003כ\u0004דברי \u0003אביי קשישא\u0004 \u0005[הזקן],\u0006 ש\u0003אמר אביי קשישא\u0004 \u0005[הזקן],\u0006 \u0003משל\u0004 של \u0003ר' יוסי: למה הדבר דומה? לשכיב מרע שאמר \"תנו\u0004 (שהוא לשון מתנה) \u0003מאתים זוז לפלוני בעל חובי\",\u0004 שאז הרשות ביד אותו בעל חוב להחליט, אם \u0003רצה — בחובו נוטלן\u0004 לסכום זה, והרויח על ידי כך שאם מכר השכיב מרע נכסיו לפני מותו, יוכל לטרוף מן הלקוחות, כדין בעל חוב שטורף ממשועבדים. ואם \u0003רצה — במתנה נוטלן.\u0004"],["\u0003אם במתנה נוטלן לא כך יפה כחו\u0004 (לא זאת האפשרות הטובה ביותר בשבילו), לפי שאינו יכול לטרוף נכסים מן הלקוחות לצורך המתנה, ואף האשה רשאית למכור נכסים סתם, ולהחליט אחר כך לאיזה צורך היא נוטלת את השאר.","לעצם הענין דנים: \u0003כיצד מוכרת?\u0004 כלומר, באיזה אופן מוכרת היא מן הנכסים לצרכיה? \u0003אמר ר' דניאל בר רב קטינא אמר רב הונא: מוכרת אחת לשנים עשר חדש\u0004 כדי צורך מזונותיה לשנים עשר חודש, \u0003ולוקח\u0004 שקנה את הנכס ממנה \u0003מפרנס\u0004 אותה בכספים \u0003אחת לשלשים יום,\u0004 כדי שאם תינשא בינתיים ותתבטל זכותה בנכסים יתן הקונה את הכסף ליורשים. \u0003ורב יהודה אמר: מוכרת לששה חדשים, ולוקח מפרנס אחת לשלשים יום.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב הונא,\u0004 ששנינו: \u0003מוכרת לשנים עשר חדש, ולוקח מפרנס אחת לשלשים יום.\u0004 וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה: מוכרת לששה חדשים ולוקח מפרנס אחת לשלשים יום.\u0004","\u0003אמר אמימר: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003מוכרת לששה חדשים ולוקח מפרנס אחת לשלשים יום,\u0004 כדברי רב יהודה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר:\u0004 שיטה זו של \u0003רב הונא מאי\u0004 \u0005[מה],\u0006 כלומר, מה אומר אתה על דבריו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שמיע לי\u0004 \u0005[לא שמעתי\u0006 דבר זה\u0005],\u0006 \u0003כלומר,\u0004 לא שלא שמעתי, אלא \u0003לא סבירא לי\u0004 \u0005[אין אני סבור\u0006 כן\u0005].\u0006","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 הלומדים \u0003מרב ששת:\u0004 אשה שהיתה \u0003מוכרת\u0004 נכסים \u0003למזונות, מהו שתחזור ותטרוף\u0004 מאותם הנכסים שהיא עצמה מכרה \u0003ל\u0004תשלום ה\u0003כתובה\u0004 שלה?","ומעירים: \u0003קמיבעיא להו\u0004 \u0005[נשאלה,\u0006 נסתפקה \u0005להם]\u0006 שאלה זו \u0003ב\u0004הלכה שקבע \u0003רב יוסף.\u0004 ש\u0003אמר רב יוסף: ארמלתא דזבין\u0004 \u0005[אלמנה שמכרה\u0006 נכסים\u0005]\u0006 — ה\u0003אחריות\u0004 היא \u0003איתמי\u0004 \u0005[על היתומים].\u0006 שאם היה על הנכסים שעבוד קודם וטרפו נכסים אלה מיד הלקוחות — הרי האחריות מוטלת על היתומים, ומהנכסים שירשו משלמים ללקוחות. \u0003ובי דינא דזבין\u0004 \u0005[ו\u0006כן \u0005בית דין שמכרו]\u0006 מנכסי המת — ה\u0003אחריות איתמי\u0004 \u0005[על היתומים],\u0006 ולפי דברים אלה היתה השאלה: \u0003מאי\u0004 \u0005[מה]\u0006 הדין במקרה שלנו?","האם \u0003כיון\u0004 שה\u0003אחריות איתמי\u0004 \u0005[על היתומים],\u0006 אם כן \u0003טרפא\u0004 \u0005[\u0006יכולה היא \u0005לטרוף],\u0006 שכיון שלא קיבלה על עצמה אחריות למכר, יפה כוחה לטרוף ככל בעל חוב אחר, \u0003או דלמא מצי אמרי\u0004 \u0005[שמא יכולים\u0006 הלוקחים \u0005לומר]\u0006 \u0003לה: נהי\u0004 \u0005[\u0006אם \u0005אמנם]\u0006 \u0003אחריות דעלמא\u0004 \u0005[של העולם,\u0006 של אחרים\u0005]\u0006 \u0003לא קבילת עילוך\u0004 \u0005[קיבלת עליך]\u0006 ואין את חייבת לשלם משלך, אלא משל היתומים, מכל מקום \u0003אחריות דנפשך מי\u0004 \u0005[של עצמך האם]\u0006 \u0003לא קבולי קבילת\u0004 \u0005[קיבלת],\u0006 שאת היא המוכרת ולא תחזרי ותטרפי?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת לשואל: \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה].\u0006 ששנינו: \u0003מוכרת\u0004 האלמנה מנכסי המת לצורך מזונות \u0003והולכת\u0004 (וממשיכה) \u0003עד\u0004 שישאר בנכסים \u0003כדי כתובתה, וסמך לה\u0004 \u0005[וסומכת]\u0006 \u0003שתגבה כתובתה מן השאר. שמע מינה\u0004 \u0005[למד מכאן]:\u0006 אם \u0003שיירא\u0004 \u0005[שיירה]\u0006 כדי כתובתה — \u0003אין\u0004 \u0005[כן],\u0006 יכולה לקחת את שאר הנכסים לתשלום הכתובה, אבל אם \u0003לא שיירא\u0004 \u0005[שיירה] —\u0006 משמע ש\u0003לא\u0004 תוכל לטרוף מהנכסים שמכרה כבר, שאם לא כן אינה צריכה סמך מן השאר, ויכולה למכור הכל למזונותיה, ותחזור ותטרוף לצורך כתובתה.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא ליקרו\u0004 \u0005[יקראו]\u0006 \u0003לה הדרינתא\u0004 \u0005[חזרנית],\u0006 אדם בלתי נאמן, החוזר בו מהסכמים שעשה, אבל מן הדין יכולה לטרוף. ודוחים: \u0003אם כן\u0004 פירוש הדברים, שזו רק עצה טובה, \u0003ליתני\u0004 \u0005[שישנה]\u0006 אם כן: \u0003\"גובה כתובתה מן השאר\", מאי\u0004 \u0005[מה]\u0006 טעם ההדגשה \u0003\"סמך לה\"? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמדוייקים הדברים, ודווקא אם \u0003שיירא\u0004 \u0005[שיירה] —\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא שיירא\u0004 \u0005[שיירה] —\u0006 \u0003לא.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אם \u0003זבין\u0004 \u0005[מכר]\u0006 אדם קרקעות לצורך מסויים, \u0003ו\u0004לבסוף \u0003לא איצטריכו ליה זוזי\u0004 \u0005[הוצרכו לו הכספים]\u0006 לאותו דבר, \u0003הדרי זביני\u0004 \u0005[חוזר המכר],\u0006 \u0003או לא הדרי זביני\u0004 \u0005[חוזר המכר]?\u0006 כלומר, האם יש לראות במכירה זו טעות שיכול המוכר לחזור בו, או שמא מה שעשה עשוי?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לכך ממעשה זה: \u0003דההוא גברא דזבין ארעא\u0004 \u0005[שאדם אחד מכר קרקע]\u0006 \u0003לרב פפא\u0004 משום \u0003דאצטריכו ליה זוזי למיזבן תורי\u0004 \u0005[שהוצרכו לו כספים לקנות שוורים].\u0006 \u0003לסוף\u0004 \u0005[לבסוף]\u0006 \u0003לא איצטריכו ליה\u0004 \u0005[הוצרכו לו]\u0006 הכספים, והתחרט על מכירת הקרקע, \u0003ואהדריה ניהליה\u0004 \u0005[והחזירה לו]\u0006 \u0003רב פפא לארעיה\u0004 \u0005[את קרקעו].\u0006 ודוחים: זו אינה ראיה, כי \u0003רב פפא לפנים משורת הדין הוא דעבד\u0004 \u0005[שעשה],\u0006 אבל אין זה אומר שכך ההלכה שבמקרה כזה חוזר המיקח.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר: \u0003דההוא בצורתא דהוה\u0004 \u0005[שאותה בצורת שהיתה]\u0006 \u0003בנהרדעא, זבנינהו כולי עלמא לאפדנייהו\u0004 \u0005[\u0006ו\u0005מכרו הכל את ארמונותיהם]\u0006 כדי לקנות חיטה, \u0003לסוף אתו חיטי\u0004 \u0005[לבסוף באו חיטים].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן: דינא\u0004 \u0005[הדין]\u0006 \u0003הוא דהדרי אפדני למרייהו\u0004 \u0005[שחוזרים הארמונות לבעליהם].\u0006 הרי שהוא סבור שמכר שנעשה מתוך צורך בכסף, חוזר כשמתברר למוכר שאינו צריך לכך.","ומשיבים: \u0003התם נמי זביני\u0004 \u0005[שם גם כן מכירה]\u0006 \u0003בטעות הוו\u0004 \u0005[היתה]\u0006 בשעת המכירה עצמה, \u0003דאיגלאי מילתא דארבא בעקולי הוה קיימא\u0004 \u0005[שהתגלה הדבר שהאניה\u0006 עם החיטים כבר \u0005בפיתולי\u0006 הנהר \u0005היתה עומדת]\u0006 ואילו היו יודעים שהאניה קרובה כל כך, לא היו מוכרים, שהיתה זו טעות בשעת המכר ולא טעות שנתגלתה לאחר מכן.","ומביאים ראיה לתירוץ זה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003היינו\u0004 \u0005[זה]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר שמואל לרב נחמן,\u0004 שהקשה על פסק ההלכה שלו: \u0003אם כן נמצאת מכשילן לעתיד לבא,\u0004 שלפי פסק זה אין אפשרות למכר ממש, שאנשים לא ירצו לקנות קרקע, שמא יחזור בו המוכר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אטו\u0004 \u0005[וכי]\u0006 ב\u0003כל יומא בצורתא שכיחא\u0004 \u0005[בצורת מצויה\u0006 היא\u0005]?\u0006 ואני לא אמרתי שחוזרים אלא במקרה כגון זה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003בצורתא\u0004 \u0005[בצורת]\u0006 \u0003בנהרדעא משכח שכיחא\u0004 \u0005[מצויה\u0006 היא\u0005].\u0006","ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה\u0006 היא\u0005]:\u0006 אם \u0003זבין\u0004 \u0005[מכר]\u0006 \u0003ולא איצטריכו ליה זוזי\u0004 \u0005[הוצרכו לו הכספים] —\u0006 \u0003הדרי זביני\u0004 \u0005[חוזר המיקח].\u0006","\u0003אלמנה, בין\u0004 שהיתה אלמנה \u0003מן האירוסין בין מן הנשואין — מוכרת\u0004 מנכסי בעלה \u0003שלא בבית דין.\u0004","\u0003ר' שמעון אומר:\u0004 אלמנה \u0003מן הנשואין מוכרת שלא בבית דין,\u0004 ואילו אלמנה \u0003מן האירוסין לא תמכור אלא בבית דין, מפני שאין לה\u0004 עדיין \u0003מזונות\u0004 אלא כתובה בלבד, \u0003וכל שאין לה מזונות — לא תמכור אלא בבית דין.\u0004","מבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שאלמנה \u0003מן הנשואין\u0004 מוכרת שלא בבית דין — \u0003משום\u0004 שהיא צריכה \u0003מזוני\u0004 \u0005[למזונות],\u0006 ולצורך דחוף זה אין שוהים עד שתמצא בית דין שתמכור בפניהם,"],["\u0003אלא מן האירוסין מאי טעמא\u0004 \u0005[מה טעם]\u0006 יכולה למכור לצרכיה מנכסי בעלה אף מחוץ לבית דין? \u0003אמר עולא: משום חינא\u0004 \u0005[חן],\u0006 שתיקנו חכמים כמה תקנות עבור הנשים, כדי שיבואו לשאתן (ר\"ח). \u0003ר' יוחנן אמר: לפי שאין אדם רוצה שתתבזה אשתו\u0004 בכך שתצטרך להתדיין \u0003בבית דין.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003גרושה. למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום חינא\u0004 \u0005[חן] —\u0006 \u0003גרושה נמי בעיא\u0004 \u0005[גם כן צריכה]\u0006 \u0003חן,\u0004 ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לפי שאין אדם רוצה שתתבזה אשתו בבית דין — גרושה לא איכפת ליה\u0004 \u0005[לו]\u0006 שתתבזה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בהמשך: \u0003וגרושה לא תמכור אלא בבית דין.\u0004 ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהטעם הוא \u0003לפי שאין אדם רוצה שתתבזה אשתו בבית דין\u0004 — אפשר לומר ש\u0003גרושה לא איכפת ליה\u0004 \u0005[לו]\u0006 שתתבזה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום חינא\u0004 \u0005[חן],\u0006 הלא \u0003גרושה נמי בעיא\u0004 \u0005[גם כן צריכה]\u0006 \u0003חן!\u0004","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 שבהמשך כשיטת \u0005מי היא] —\u0006 כדעת \u0003ר' שמעון\u0004 שבמשנתנו \u0003היא,\u0004 שלדעתו כל שאינה מוכרת למזונות אלא לכתובה — מוכרת רק בבית דין, ולגרושה הרי אין מזונות.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 דעת \u0003ר' שמעון — הא תנא ליה רישא\u0004 \u0005[הרי\u0006 כבר \u0005שנה אותה\u0006 ב\u0005ראשה]:\u0006 אלמנה \u0003מן האירוסין לא תמכור\u0004 אלא בבית דין מפני שאין לה מזונות, ומאותו הטעם גם גרושה לא תמכור אלא בבית דין, ולשם מה צריך לחזור ולשנות בגרושה?","ומשיבים: יש צורך בכך שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003אלמנה מן האירוסין הוא\u0004 ש\u0003לא נפיש\u0004 \u0005[מרובה]\u0006 צרכה ל\u0003חן דידה\u0004 \u0005[שלה],\u0006 שמכיון שלא נפגמה בביאה, לא יימנעו מלשאתה, \u0003אבל גרושה דנפיש\u0004 \u0005[שמרובה]\u0006 צרכה ל\u0003חן דידה\u0004 \u0005[שלה],\u0006 שצריכה סיוע לנישואין \u0003אימא תיבעי\u0004 \u0005[אמור שתצטרך]\u0006 \u0003חן,\u0004 כדי שלא יזלזלו בה ולכן שנה הלכה זו.","ומקשים: \u0003הא נמי תנינא\u0004 \u0005[\u0006הרי \u0005זו גם כן שנינו],\u0006 שנאמר במשנה בלשון כללית: \u0003\"כל שאין לה מזונות\". לאתויי מאי\u0004 \u0005[להביא\u0006 לרבות, את \u0005מה]?\u0006 \u0003לאו לאתויי\u0004 \u0005[\u0006האם \u0005לא להביא]\u0006 \u0003גרושה\u0004 שגם היא מוכרת בבית דין, ואם כן הסיפא לכאורה מיותרת?","ודוחים: \u0003לא, לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 את זו שדינה \u0003\"מגורשת ואינה מגורשת\"\u0004 — ו\u0003כ\u0004דברי \u0003ר' זירא.\u0004 ש\u0003אמר ר' זירא: כל מקום שאמרו\u0004 על אשה ש\u0003מגורשת ואינה מגורשת — בעל חייב במזונותיה\u0004 כל עוד לא נתגרשה לגמרי, ולכן מוכרת גם שלא בבית דין.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003כשם ש\u0004היא עצמה \u0003מוכרת שלא בבית דין — כך יורשיה\u0004 שהם \u0003יורשי כתובתה, מוכרים שלא בבית דין. בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003לפי שאין אדם רוצה שתתבזה אשתו בבית דין\u0004 אפשר לומר \u0003כי היכי דאיהי\u0004 \u0005[כמו שהיא\u0006 עצמה\u0005]\u0006 \u0003לא ניחא ליה דתתבזי\u0004 \u0005[נוח לו שתתבזה]\u0006 — \u0003יורשיה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ניחא ליה דליבזו\u0004 \u0005[נוח לו שיתבזו],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003משום חינא\u0004 \u0005[חן],\u0006 \u0003יורשיה מאי\u0004 \u0005[מה]\u0006 \u0003חן איכא\u0004 \u0005[יש]\u0006 בהם? תרגמה \u0005[תרגם\u0006 הסביר זאת\u0005]\u0006 \u0003עולא: כגון שירשתה בתה או אחותה,\u0004 שגם הן צריכות חן.","\u0003מכרה\u0004 האשה את \u0003כתובתה או מקצתה\u0004 של הכתובה, \u0003משכנה כתובתה או מקצתה, נתנה\u0004 במתנה \u0003כתובתה לאחר או מקצתה — לא תמכור את השאר,\u0004 כלומר לא תמכור מנכסי בעלה כדי להפרע מהם את השאר, \u0003אלא בבית דין. וחכמים אומרים: מוכרת היא אפילו ארבעה וחמשה פעמים,\u0004 כלומר, אינה חייבת למכור את הכל בבת אחת. \u0003ומוכרת למזונות\u0004 בתוך כדי כך אפילו \u0003שלא בבית דין, וכותבת\u0004 בשטר המכירה \u0003\"למזונות מכרתי\". וגרושה\u0004 שאין לה מזונות — \u0003לא תמכור אלא בבית דין.\u0004","שואלים: \u0003מתניתין מני\u0004 \u0005[\u0006הדעה הראשונה ב\u0005משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 ומשיבים: כשיטת \u0003ר' שמעון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מכרה\u0004 את כל \u0003כתובתה, משכנה כתובתה, עשתה כתובתה אפותיקי\u0004 (משכון) \u0003לאחר — אין לה\u0004 עוד \u0003מזונות,\u0004 אלו \u0003דברי ר' מאיר. ר' שמעון אומר: אף על פי שלא מכרה ולא משכנה כתובתה\u0004 כולה \u0003אלא מחציתה — אבדה מזונותיה,\u0004 ולכן מוכרת את שאר הכתובה דווקא בבית דין.","ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003ר' שמעון סבר דלא אמרינן\u0004 \u0005[שאין אנו אומרים]\u0006 \u0003מקצת כסף\u0004 דינו \u0003ככל כסף.\u0004 ולכן, כיון שאין לה עוד תביעה לכל כסף הכתובה, הרי זה כאילו אין לה כתובה כלל, ואין לה גם מזונות, \u0003ורבנן סברי\u0004 \u0005[וחכמים סוברים]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מקצת כסף ככל כסף?\u0004","אולם, \u0003הא איפכא שמעינן להו\u0004 \u0005[הרי ההיפך שמענו אותם]\u0006 אומרים! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על מה שנאמר בכהן הגדול: \u0003\"והוא אשה בבתוליה\u0004 יקח\u0003\"\u0004 (ויקרא כא, יג) — \u0003פרט לבוגרת שכלו בתוליה\u0004 (שעם הבגרות קטן ביותר קרום הבתולים), אלו \u0003דברי ר' מאיר. ר' אלעזר ור' שמעון מכשירין בבוגרת.\u0004 משמע שהם סבורים שמקצתו אינו ככולו, ואף על פי שכלו מקצת בתוליה — הלא לא כלו לגמרי.","ומשיבים: \u0003התם בקראי פליגי\u0004 \u0005[שם ב\u0006פירוש \u0005הכתובים\u0006 הם \u0005חלוקים].\u0006 \u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 כך: אילו נאמר \u0003\"בתולה\"\u0004 לשון כללית זו משמעה כל שהיא בתולה ו\u0003אפילו\u0004 אין לה אלא \u0003מקצת בתולים.\u0004 אולם כיון שנאמר \u0003\"בתוליה\" — עד דאיכא כולהו\u0004 \u0005[שיש\u0006 את \u0005כל]\u0006 ה\u0003בתולים\u0004 ומה שנאמר \u0003\"בבתוליה\"\u0004 בבי\"ת השימוש, משמעו: אם נבעלה \u0003בכדרכה\u0004 בבתוליה, במקום בתוליה — \u0003אין\u0004 \u0005[כן],\u0006 ואינה נחשבת עוד בתולה. ואם נבעלה \u0003שלא כדרכה — לא.\u0004","ו\u0003ר' אלעזר ור' שמעון סברי\u0004 \u0005[סבורים]:\u0006 \u0003\"בתולה\"\u0004 — בתולה \u0003שלמה משמע,\u0004 שכל בתוליה קיימים איתה, ולכן \u0003\"בתוליה\"\u0004 בא לומר — \u0003אפילו מקצת בתולים\u0004 נחשבים כבתולים לענין זה."]]};
